INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C1','kor',3,2,'u6',2,'이 단원에서 배울 두 가지 — 재미나 감동을 느끼며 작품 감상하기(받아들이는 일)와 의견을 제시하는 글 쓰기(내 생각과 이유를 내놓는 일)',ARRAY['[4국05-02][4국03-03]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C2','kor',3,2,'u6',2,'작품을 감상한다는 것 — 줄거리를 외우거나 점수를 매기는 일이 아니라, 마음이 움직인 자리를 찾고 어디를 보고 그랬는지 말하는 일',ARRAY['[4국05-02]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C3','kor',3,2,'u6',2,'재미와 감동 — 재미는 웃음이 나거나 다음이 궁금하거나 놀라운 곳, 감동은 마음이 뭉클하거나 오래 남거나 내 일처럼 느껴지는 곳 — 한 작품 안에 둘 다 있을 수 있음',ARRAY['[4국05-02]']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C4','kor',3,2,'u6',2,'같은 작품을 다르게 느낌 — 같은 작품을 보고 다르게 느껴도 둘 다 제 감상이며, 어디를 보고 그렇게 느꼈는지 말하면 됨(하나가 틀린 것도, 아무렇게나 말해도 되는 것도 아님)',ARRAY['[4국05-02]']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C5','kor',3,2,'u6',2,'사람마다 느낀 곳이 다른 까닭 — 저마다 겪은 일과 처지가 달라 마음이 걸리는 자리가 다름',ARRAY['[4국05-02]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C6','kor',3,2,'u6',2,'감상을 말하는 틀 — 어느 장면에서 + 어떤 마음이 들었는지를 이어 말함(줄거리만 옮기기·느낌만 던지기는 모자람)',ARRAY['[4국05-02]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C7','kor',3,2,'u6',2,'느낌과 근거 잇기 — 느낀 것 옆에는 늘 무엇을 보고 그랬는지(작품 안의 근거)가 붙음',ARRAY['[4국05-02]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C8','kor',3,2,'u6',3,'말없이 마음을 아는 법 — 말이 없어도 얼굴 표정·몸짓과 행동·말투와 목소리로 인물의 마음을 알 수 있음',ARRAY['[4국05-02]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C9','kor',3,2,'u6',3,'행동으로 마음 짐작하기 — 말로 적지 않은 마음이 행동에 남아 있음 — 그 앞에 있었던 일과 이어 짐작함(「손에 힘이 들어갔다」 → 서운함)',ARRAY['[4국05-02]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C10','kor',3,2,'u6',3,'「접힌 쪽지」 내용 알기 — 서랍에서 쪽지를 찾고 → 쓴 사람을 찾다 국을 쏟고 → 아무도 나서지 않고 → 뒷면에서 작년의 내 글씨임이 밝혀짐',ARRAY['[4국05-02]']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C11','kor',3,2,'u6',3,'감상하는 방법이 여럿 — 표정과 말투에 주의하며 보기 · 장면을 눈앞에 그리며 상상하기 · 인물의 일을 내 일과 이어 보기',ARRAY['[4국05-02]']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C12','kor',3,2,'u6',3,'한 작품에 느낄 자리가 여럿 — 한 이야기 안에 재미를 느끼는 곳도 감동을 느끼는 곳도 여럿 있음 — 단, 작품 안에 실제로 있는 곳',ARRAY['[4국05-02]']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C13','kor',3,2,'u6',3,'감상을 나누면 좋은 점 — 같은 곳을 느꼈는지 맞춰 보거나 확인받으려는 것이 아니라, 내가 못 보고 지나친 자리를 알게 되어 작품이 넓어짐',ARRAY['[4국05-02]']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C14','kor',3,2,'u6',5,'소중히 여기는 것은 말과 행동에서 — 인물이 무엇을 소중히 여기는지는 이야기에 적혀 있지 않고, 인물이 한 말과 행동을 보고 읽어 냄',ARRAY['[4국05-02]']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C15','kor',3,2,'u6',5,'「같은 자리」 내용 알기 — 나는 화분을 돌보고 짝은 사물함이 화분에 걸려 불편해 말이 없어졌다가, 복도에서 잎이 노래진 뒤 짝이 먼저 창가를 말해 둘 다 지킬 자리를 찾음',ARRAY['[4국05-02]']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C16','kor',3,2,'u6',5,'부딪친 두 사람 둘 다 소중한 것 — 부딪친 두 인물은 한쪽이 잘못한 것이 아니라 둘 다 소중히 여기는 것이 있어 물러설 수 없었음 — 「누가 옳은가」는 한쪽을 고를 물음이 아님',ARRAY['[4국05-02]']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C17','kor',3,2,'u6',5,'인물에게 물어볼 질문 — 그때의 마음·그렇게 한 까닭·지금이라면 어떻게 할지처럼 인물이 답할 수 있는 질문(답이 이야기 밖에 있는 질문은 알맞지 않음)',ARRAY['[4국05-02]']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C18','kor',3,2,'u6',5,'내 일과 이어 보기 — 친구와 부딪친 일을 떠올릴 때 누가 잘못했는지보다 서로 무엇을 소중히 여겼는지를 먼저 봄(덮어 두기도 아님)',ARRAY['[4국05-02]']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C19','kor',3,2,'u6',7,'의견이란 — 어떤 일이나 대상에 대한 생각 — 있었던 일(사실)과 다르며 “좋겠다·하자·해야 한다”가 붙음',ARRAY['[4국03-03]']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C20','kor',3,2,'u6',7,'의견을 제시하는 글의 세 부분 — 문제 상황(무엇이 불편한지) · 내 의견(어떻게 하면 좋을지) · 그렇게 생각한 이유(왜 그런지) — 의견만 있으면 글이 서지 않음',ARRAY['[4국03-03]']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C21','kor',3,2,'u6',7,'글에서 의견과 이유 찾기 — “그래서 …면 좋겠다”는 의견, “왜냐하면·첫째·둘째·또”로 시작하는 줄은 이유',ARRAY['[4국03-03]']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C22','kor',3,2,'u6',7,'적절한 이유 — 이유는 의견과 이어져 의견을 받쳐 주어야 함(의견과 관련 없는 이유는 받침이 되지 못함)',ARRAY['[4국03-03]']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C23','kor',3,2,'u6',7,'의견과 이유를 재는 네 가지 — 문제 상황에 어울리는 의견인가 · 의견을 뒷받침하는 이유인가 · 이유가 겹치지 않고 여러 가지인가 · 문제를 푸는 데 도움이 되는가 — 「나만 잘한다」는 받침이 아님',ARRAY['[4국03-03]']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C24','kor',3,2,'u6',7,'한 문제에 여러 의견 — 같은 문제 상황에도 의견이 여럿 나올 수 있으며, 가르는 것은 어느 의견인가가 아니라 이유가 의견을 받쳐 주는가임',ARRAY['[4국03-03]']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C25','kor',3,2,'u6',7,'의견 글을 쓸 때 먼저 할 일 — 고운 말·친구가 좋아할 말보다 무엇이 불편한지(문제 상황)를 먼저 찾음',ARRAY['[4국03-03]']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C26','kor',3,2,'u6',9,'고쳐 쓸 때 살펴볼 것 — 어울리는 의견인가 · 이유가 받쳐 주는가 · 어색한 곳은 없는가 · 띄어쓰기와 맞춤법(글의 길이·글씨 모양이 아님)',ARRAY['[4국03-03]']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C27','kor',3,2,'u6',9,'이어지지 않는 이유 고치기 — 의견과 이어지지 않는 이유를 찾아, 지우기만 하지 않고 의견을 받쳐 주는 다른 이유로 바꿈',ARRAY['[4국03-03]']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C28','kor',3,2,'u6',9,'고칠 곳이 있는 글은 못 쓴 글이 아님 — 고칠 곳이 보인 것은 글을 다시 읽었다는 뜻이고, 글은 고쳐 가며 좋아짐 — 고쳐 쓰면 내 생각이 더 잘 전해짐',ARRAY['[4국03-03]']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C29','kor',3,2,'u6',9,'친구 글에 말해 주기 — 잘된 곳을 먼저 한 가지 말하고, 고칠 곳은 어디인지 짚어 까닭과 함께 말함(점수를 매기는 자리가 아님)',ARRAY['[4국03-03]']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C30','kor',3,2,'u6',10,'다룰 문제 고르기 — 우리가 함께 바꿀 수 있는 일을 고름 — 어쩔 수 없는 일·누군가를 탓하는 일은 의견 글의 문제가 아님',ARRAY['[4국03-03]']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C31','kor',3,2,'u6',10,'읽을 사람 정하기 — 쓰기 전에 누가 읽을지와 어디에 쓸지를 정하면 쓸 말이 정해짐(읽을 사람이 아는 일은 짧게, 함께 할 일은 자세히)',ARRAY['[4국03-03]']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C32','kor',3,2,'u6',10,'이유 떠올리기 — 내 의견대로 하면 무엇이 좋아질지를 먼저 적어 보면 이유가 보임',ARRAY['[4국03-03]']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C33','kor',3,2,'u6',10,'글의 뼈대 — 문제 상황 → 의견 → 이유 두 가지 → 맺음(함께 해 보자는 말)',ARRAY['[4국03-03]']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C34','kor',3,2,'u6',10,'점검표로 내 글 재기 — 문제를 풀 수 있는 의견인가 · 받쳐 주는 이유인가 · 어색한 곳 · 띄어쓰기와 맞춤법으로 재어 고쳐 씀(틀린 곳 찾기·점수 깎기가 아님)',ARRAY['[4국03-03]']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C35','kor',3,2,'u6',12,'의견을 제시하는 손 팻말 — 팻말에도 의견과 이유가 함께 — 의견만 크게 쓰면 명령이 되고, 이유만 길면 무엇을 하자는지 안 보임',ARRAY['[4국05-02][4국03-03](케이티처 l12 표기)']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C36','kor',3,2,'u6',12,'「만약 이랬더라면?」 — 작품을 고치는 놀이가 아니라 마음이 움직인 장면의 말이나 행동을 바꾸어 보며 왜 그랬는지 다시 보는 놀이',ARRAY['[4국05-02][4국03-03](케이티처 l12 표기)']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C37','kor',3,2,'u6',12,'한 줄 평 — 느낀 곳과 마음을 한 줄에 함께 담음(점수만·줄거리만으로는 친구가 따라올 수 없음)',ARRAY['[4국05-02][4국03-03](케이티처 l12 표기)']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C38','kor',3,2,'u6',12,'-ㄹ게 · -ㄹ걸은 그대로 쓰기 — “갈게”가 [갈께]로 소리 나도 약속하는 말·되돌아보는 말은 글자 그대로 씀(기초 다지기)',ARRAY['[4국05-02][4국03-03](케이티처 l14 표기)']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C39','kor',3,2,'u6',12,'묻는 말 -ㄹ까는 소리 나는 대로 — “먹을까?·갈까?”처럼 묻는 말은 소리 나는 대로 씀(‘-ㄹ가’ 아님, 기초 다지기)',ARRAY['[4국05-02][4국03-03](케이티처 l14 표기)']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C40','kor',3,2,'u6',12,'낱말 잇기 — 앞 낱말의 끝 글자로 시작하는 낱말을 찾아 줄줄이 이음(기초 다지기)',ARRAY['[4국05-02][4국03-03](케이티처 l14 표기)']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u6-C41','kor',3,2,'u6',12,'ㅝ · ㅞ · ㅟ가 든 글자 쓰기 — ㅝ(ㅜ+ㅓ) · ㅞ(ㅜ+ㅔ) · ㅟ(ㅜ+ㅣ)를 살피며 씀(원숭이 · 웬일 · 스웨터 · 바퀴, 기초 다지기)',ARRAY['[4국05-02][4국03-03](케이티처 l14 표기)']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X01','kor',3,'u6',ARRAY['K3-2-u6-C2']::text[],'감상을 줄거리를 빠짐없이 외우는 일로 여긴다','마음이 움직인 자리는?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X02','kor',3,'u6',ARRAY['K3-2-u6-C2','K3-2-u6-C37']::text[],'감상을 작품에 점수를 매기거나 좋고 나쁨을 가리는 일로 여긴다','점수로는 마음이 안 보여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X03','kor',3,'u6',ARRAY['K3-2-u6-C4']::text[],'같은 작품을 보고 다르게 느끼면 둘 가운데 하나는 틀린 감상이라고 여긴다','어디를 보고 그랬는지 들어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X04','kor',3,'u6',ARRAY['K3-2-u6-C4','K3-2-u6-C7','K3-2-u6-C12']::text[],'감상은 근거 없이 아무렇게나 말해도 된다고 여겨, 작품에 없는 장면이나 작품 밖의 일을 든다','작품 안에서 무엇을 보았나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X05','kor',3,'u6',ARRAY['K3-2-u6-C5']::text[],'사람마다 느낀 곳이 다른 까닭을 한 사람만 제대로 읽었기 때문이라고 여긴다','겪은 일과 처지가 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X06','kor',3,'u6',ARRAY['K3-2-u6-C6','K3-2-u6-C37']::text[],'줄거리만 옮겨 말하고 감상을 말했다고 여긴다','그 장면에서 어떤 마음이었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X07','kor',3,'u6',ARRAY['K3-2-u6-C6']::text[],'“그냥 좋았어”처럼 느낌만 던지고 어디에서 그랬는지는 말하지 않는다','어느 장면에서?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X08','kor',3,'u6',ARRAY['K3-2-u6-C3']::text[],'재미와 감동을 엇갈리게 알거나, 한 작품에는 둘 가운데 하나만 있다고 여긴다','웃음 · 뭉클함') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X09','kor',3,'u6',ARRAY['K3-2-u6-C8']::text[],'말없이 마음을 알 때 키·날씨·옷처럼 마음과 상관없는 것을 본다','얼굴 · 몸짓 · 말투') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X10','kor',3,'u6',ARRAY['K3-2-u6-C8','K3-2-u6-C9']::text[],'행동을 겉뜻으로만 읽거나 앞에 있었던 일과 잇지 않아 인물의 마음을 잘못 짐작한다','그 앞줄에 무슨 일이?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X11','kor',3,'u6',ARRAY['K3-2-u6-C10','K3-2-u6-C15']::text[],'이야기에 나온 일의 차례나 내용을 이야기에 없는 것으로 잘못 읽는다','그 줄을 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X12','kor',3,'u6',ARRAY['K3-2-u6-C11']::text[],'작품을 감상하는 방법은 하나뿐이라고 여기거나 방법을 엇갈리게 안다','표정 · 상상 · 내 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X13','kor',3,'u6',ARRAY['K3-2-u6-C12']::text[],'작품마다 정해진 감동 지점이 하나 있어 그 밖의 곳을 고르면 잘못 감상한 것이라고 여긴다','느낄 자리는 여럿') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X14','kor',3,'u6',ARRAY['K3-2-u6-C13']::text[],'감상을 나누는 까닭을 같은 곳을 느꼈는지 맞춰 보거나 내 감상이 맞는지 확인받는 것으로 여긴다','내가 못 본 자리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X15','kor',3,'u6',ARRAY['K3-2-u6-C14']::text[],'인물이 소중히 여기는 것이 이야기에 적혀 있다고 여기거나, 말과 행동을 살피지 않고 짐작한다','한 말과 한 행동') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X16','kor',3,'u6',ARRAY['K3-2-u6-C16','K3-2-u6-C18']::text[],'두 인물이 부딪치면 한쪽이 옳고 한쪽이 잘못한 것이라고 여겨 누가 옳은지 고르려 한다','둘 다 소중한 것이 있었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X17','kor',3,'u6',ARRAY['K3-2-u6-C17']::text[],'인물에게 답이 이야기 밖에 있는 질문(가게·학교 이름·쓴 사람)을 한다','인물이 답할 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X18','kor',3,'u6',ARRAY['K3-2-u6-C18']::text[],'친구와 부딪친 일은 덮어 두고 말하지 않는 것이 좋다고 여긴다','무엇을 소중히 여겼는지 말해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X19','kor',3,'u6',ARRAY['K3-2-u6-C19']::text[],'있었던 일(사실)과 내 생각(의견)을 가르지 못한다','“좋겠다 · 하자”가 붙었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X20','kor',3,'u6',ARRAY['K3-2-u6-C20']::text[],'의견을 제시하는 글에 의견만 있으면 되고 이유는 없어도 된다고 여긴다','읽는 사람이 “왜?”') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X21','kor',3,'u6',ARRAY['K3-2-u6-C20','K3-2-u6-C21','K3-2-u6-C33']::text[],'문제 상황·의견·이유(·맺음)를 엇갈리게 가른다','불편 · 하자 · 왜냐하면') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X22','kor',3,'u6',ARRAY['K3-2-u6-C22','K3-2-u6-C27','K3-2-u6-C34']::text[],'의견과 관련 없는 이유도 의견을 받쳐 준다고 여긴다','그 이유가 의견과 이어지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X23','kor',3,'u6',ARRAY['K3-2-u6-C22','K3-2-u6-C23','K3-2-u6-C27']::text[],'「내가 제일 잘하기 때문이다」처럼 나만 잘한다는 것을 이유로 든다','의견대로 하면 무엇이 좋아지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X24','kor',3,'u6',ARRAY['K3-2-u6-C24']::text[],'한 문제에는 정답 의견이 하나뿐이라 나와 다르거나 나중에 나온 의견은 틀렸다고 여긴다','이유가 받쳐 주는지로 재기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X25','kor',3,'u6',ARRAY['K3-2-u6-C23','K3-2-u6-C27']::text[],'같은 이유를 말만 바꾸어 되풀이하고 이유를 여러 가지 썼다고 여긴다','겹치지 않게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X26','kor',3,'u6',ARRAY['K3-2-u6-C25']::text[],'의견 글을 쓸 때 문제 상황보다 고운 말·긴 글·친구가 좋아할 말을 먼저 생각한다','무엇이 불편한지부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X27','kor',3,'u6',ARRAY['K3-2-u6-C26','K3-2-u6-C34']::text[],'고쳐 쓸 때 글의 길이·글씨 모양처럼 내용과 상관없는 것을 보거나, 한 가지만 본다','뜻이 통하나 · 맞춤법은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X28','kor',3,'u6',ARRAY['K3-2-u6-C27']::text[],'의견과 이어지지 않는 이유를 지우기만 하거나 그대로 둔다','받쳐 주는 이유로 바꾸기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X29','kor',3,'u6',ARRAY['K3-2-u6-C28','K3-2-u6-C34']::text[],'고칠 곳이 있는 글은 못 쓴 글이고 잘 쓴 글은 처음부터 고칠 곳이 없다고 여긴다','다시 읽었다는 뜻') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X30','kor',3,'u6',ARRAY['K3-2-u6-C28','K3-2-u6-C29']::text[],'고쳐 쓰기나 친구 글 읽기를 흠을 찾아 알려 주는 일로 여겨, 잘된 곳과 까닭 없이 고칠 곳만 말한다','잘된 곳 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X31','kor',3,'u6',ARRAY['K3-2-u6-C30']::text[],'날씨나 지난 일처럼 우리가 어쩔 수 없는 일을 의견 글의 문제로 고른다','우리 힘으로 바꿀 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X32','kor',3,'u6',ARRAY['K3-2-u6-C30','K3-2-u6-C35']::text[],'누군가를 탓하는 일(친구 이름 적기)을 의견 글이나 팻말의 문제로 삼는다','함께 바꿀 일인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X33','kor',3,'u6',ARRAY['K3-2-u6-C31']::text[],'읽을 사람을 생각하지 않고 누가 읽든 글을 똑같이 쓴다','누가 읽을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X34','kor',3,'u6',ARRAY['K3-2-u6-C35']::text[],'팻말에 “하지 마!”처럼 의견(명령)만 크게 쓰면 된다고 여긴다','이유도 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X35','kor',3,'u6',ARRAY['K3-2-u6-C35']::text[],'팻말에 이유만 길게 늘어놓아 무엇을 하자는지 보이지 않게 쓴다','의견을 한눈에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X36','kor',3,'u6',ARRAY['K3-2-u6-C36']::text[],'「만약 이랬더라면?」에서 제목·길이처럼 마음이 움직인 장면과 상관없는 것을 바꾼다','마음이 움직인 장면') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X37','kor',3,'u6',ARRAY['K3-2-u6-C37']::text[],'한 줄 평을 점수나 별 개수만으로 쓴다','느낀 곳과 마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X38','kor',3,'u6',ARRAY['K3-2-u6-C38']::text[],'약속하는 말·되돌아보는 말을 소리 나는 대로 쓴다(갈께·일어날껄)','쓸 때는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X39','kor',3,'u6',ARRAY['K3-2-u6-C39']::text[],'묻는 말을 ‘-ㄹ가’로 쓰거나 약속하는 말과 섞는다(먹을가)','묻는 말은 소리 나는 대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X40','kor',3,'u6',ARRAY['K3-2-u6-C40']::text[],'낱말 잇기에서 앞 낱말의 끝 글자가 아닌 다른 글자로 잇는다','끝 글자로 시작') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u6-X41','kor',3,'u6',ARRAY['K3-2-u6-C41']::text[],'ㅝ·ㅞ·ㅟ를 이루는 모음자를 엇갈리게 알아 글자를 틀리게 쓴다','ㅜ 옆에 무엇이 붙었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L02_basic#1','kor',3,2,'u6','L02','g3_2_kor_u6_L02_basic','lesson_basic','K3-2-u6-C2',1,'mc','auto','작품을 감상한다는 것은 무엇을 하는 일인가요?',ARRAY['K3-2-u6-X01','K3-2-u6-X02']::text[],false,'{"seq":1,"concept":"K3-2-u6-C2","difficulty":1,"kind":"mc","stem":"작품을 감상한다는 것은 무엇을 하는 일인가요?","options":[{"t":"마음이 움직인 자리를 찾고, 어디를 보고 그랬는지 말하는 일","correct":true},{"t":"줄거리를 빠짐없이 외우는 일","mis":"K3-2-u6-X01"},{"t":"작품에 몇 점을 줄지 매기는 일","mis":"K3-2-u6-X02"},{"t":"작품의 좋은 점만 찾아내는 시험","mis":"K3-2-u6-X02"}],"explanation":["줄거리를 외우는 일이 아니에요.","점수를 매기는 일도 아니에요.","마음이 움직인 자리와 그 까닭을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L02_basic#2','kor',3,2,'u6','L02','g3_2_kor_u6_L02_basic','lesson_basic','K3-2-u6-C3',1,'mc','auto','감동을 느낀 곳을 말한 것은 무엇인가요?',ARRAY['K3-2-u6-X08']::text[],false,'{"seq":2,"concept":"K3-2-u6-C3","difficulty":1,"kind":"mc","stem":"감동을 느낀 곳을 말한 것은 무엇인가요?","options":[{"t":"마음이 뭉클해서 오래 남는 곳","correct":true},{"t":"웃음이 터지는 곳","mis":"K3-2-u6-X08"},{"t":"다음이 궁금해지는 곳","mis":"K3-2-u6-X08"},{"t":"깜짝 놀라는 곳","mis":"K3-2-u6-X08"}],"explanation":["웃음·궁금함·놀라움은 재미예요.","뭉클하고 오래 남으면 감동이에요.","둘을 갈라 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L02_basic#3','kor',3,2,'u6','L02','g3_2_kor_u6_L02_basic','lesson_basic','K3-2-u6-C4',1,'ox','auto','같은 작품을 보고 친구와 다르게 느꼈다면 둘 가운데 하나는 틀린 감상이에요.',ARRAY['K3-2-u6-X03']::text[],false,'{"seq":3,"concept":"K3-2-u6-C4","difficulty":1,"kind":"ox","stem":"같은 작품을 보고 친구와 다르게 느꼈다면 둘 가운데 하나는 틀린 감상이에요.","answer":"X","reason_options":[{"t":"저마다 어디를 보고 그렇게 느꼈는지 말할 수 있으면 둘 다 제 감상이기 때문에","correct":true},{"t":"한 작품에서 느낄 곳은 하나로 정해져 있기 때문에","mis":"K3-2-u6-X03"}],"mis":"K3-2-u6-X03","explanation":["느낀 곳이 달라도 돼요.","어디를 보고 그랬는지 말하면 돼요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L02_basic#4','kor',3,2,'u6','L02','g3_2_kor_u6_L02_basic','lesson_basic','K3-2-u6-C1',1,'mc','auto','이 단원에서 배울 두 가지를 알맞게 짝지은 것은 무엇인가요?',ARRAY['K3-2-u6-X01','K3-2-u6-X03','K3-2-u6-X20']::text[],false,'{"seq":4,"concept":"K3-2-u6-C1","difficulty":1,"kind":"mc","stem":"이 단원에서 배울 두 가지를 알맞게 짝지은 것은 무엇인가요?","options":[{"t":"재미나 감동을 느끼며 작품 감상하기 · 의견을 제시하는 글 쓰기","correct":true},{"t":"줄거리 빨리 외우기 · 작품에 점수 매기기","mis":"K3-2-u6-X01"},{"t":"작품 감상하기 · 친구 감상에서 틀린 곳 찾기","mis":"K3-2-u6-X03"},{"t":"작품 줄거리 쓰기 · 의견만 크게 쓰기","mis":"K3-2-u6-X20"}],"explanation":["하나는 받아들이는 일이에요.","하나는 내 생각을 내놓는 일이에요.","감상하기와 의견 글 쓰기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L02_basic#5','kor',3,2,'u6','L02','g3_2_kor_u6_L02_basic','lesson_basic','K3-2-u6-C7',2,'match','auto','세 사람이 그렇게 느낀 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u6-C7","difficulty":2,"kind":"match","stem":"세 사람이 그렇게 느낀 까닭을 알맞게 이으세요.","pairs":[{"l":"쪽지 말이 오래 남았다","r":"손잡이에 감긴 쪽지의 한 줄"},{"l":"장면이 눈앞에 그려졌다","r":"접힌 우산이 놓인 모습"},{"l":"끝까지 안 나와서 재미있었다","r":"누가 놓았는지 밝히지 않은 끝"}],"mis":"K3-2-u6-X04","explanation":["각 사람이 어느 곳을 보았는지 찾아요.","느낌 옆에는 까닭이 붙어요.","세 짝을 이어요."],"asset":{"type":"passage","lines":["비가 그친 뒤, 나는 우산을 버스에 두고 내렸다.","다음 날 정류장에 갔더니 의자 위에 그 우산이 접힌 채 놓여 있었다.","손잡이에 쪽지가 감겨 있었다. “비 올 때 또 써요.”","나는 누가 놓아 두었는지 끝내 알지 못했다."],"title":"이야기 「두고 온 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L02_basic#6','kor',3,2,'u6','L02','g3_2_kor_u6_L02_basic','lesson_basic','K3-2-u6-C5',2,'mc','auto','「두고 온 우산」을 읽고 세 사람이 서로 다른 곳에서 마음이 움직인 까닭은 무엇인가요?',ARRAY['K3-2-u6-X05','K3-2-u6-X04','K3-2-u6-X03']::text[],false,'{"seq":6,"concept":"K3-2-u6-C5","difficulty":2,"kind":"mc","stem":"「두고 온 우산」을 읽고 세 사람이 서로 다른 곳에서 마음이 움직인 까닭은 무엇인가요?","options":[{"t":"저마다 겪은 일과 처지가 달라 마음이 걸리는 자리가 다르기 때문에","correct":true},{"t":"셋 가운데 한 사람만 제대로 읽었기 때문에","mis":"K3-2-u6-X05"},{"t":"감상은 아무 데나 느껴도 되기 때문에","mis":"K3-2-u6-X04"},{"t":"이야기가 짧아서 셋이 잘못 읽었기 때문에","mis":"K3-2-u6-X03"}],"explanation":["우산을 잃어 본 사람도 있어요.","쪽지를 받아 본 사람도 있어요.","눈이 가는 곳이 달라요."],"asset":{"type":"speech","turns":[{"who":"㉮","text":"쪽지에 적힌 말이 오래 남았어."},{"who":"㉯","text":"우산이 접힌 채 놓인 장면이 눈앞에 그려졌어."},{"who":"㉰","text":"누가 놓아 두었는지 끝까지 안 나오는 게 재미있었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L02_basic#7','kor',3,2,'u6','L02','g3_2_kor_u6_L02_basic','lesson_basic','K3-2-u6-C6',2,'mc','auto','감상을 말한 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X06','K3-2-u6-X07','K3-2-u6-X02']::text[],false,'{"seq":7,"concept":"K3-2-u6-C6","difficulty":2,"kind":"mc","stem":"감상을 말한 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“쪽지를 읽는 곳에서 마음이 뭉클했어.”","correct":true},{"t":"“우산을 두고 내렸는데 다음 날 의자에 있었대.”","mis":"K3-2-u6-X06"},{"t":"“그냥 좋았어. 되게 좋았어.”","mis":"K3-2-u6-X07"},{"t":"“백 점 만점에 구십 점이야.”","mis":"K3-2-u6-X02"}],"explanation":["줄거리만 옮기면 모자라요.","느낌만 던져도 모자라요.","장면과 마음을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L02_basic#8','kor',3,2,'u6','L02','g3_2_kor_u6_L02_basic','lesson_basic','K3-2-u6-C6',2,'blank','auto','“(　)에서 마음이 뭉클했어.”처럼 감상을 말할 때 빈칸에 들어갈 것은 무엇인가요?',ARRAY['K3-2-u6-X02','K3-2-u6-X06','K3-2-u6-X03']::text[],false,'{"seq":8,"concept":"K3-2-u6-C6","difficulty":2,"kind":"blank","stem":"“(　)에서 마음이 뭉클했어.”처럼 감상을 말할 때 빈칸에 들어갈 것은 무엇인가요?","options":[{"t":"마음이 움직인 장면","correct":true},{"t":"작품에 매긴 점수","mis":"K3-2-u6-X02"},{"t":"작품의 처음부터 끝까지 줄거리","mis":"K3-2-u6-X06"},{"t":"친구가 느낀 곳","mis":"K3-2-u6-X03"}],"explanation":["어디에서 느꼈는지 말해요.","그다음 어떤 마음인지 말해요.","장면이 들어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L02_basic#9','kor',3,2,'u6','L02','g3_2_kor_u6_L02_basic','lesson_basic','K3-2-u6-C3',2,'mc','auto','재미와 감동에 대해 바르게 말한 것은 무엇인가요?',ARRAY['K3-2-u6-X08']::text[],false,'{"seq":9,"concept":"K3-2-u6-C3","difficulty":2,"kind":"mc","stem":"재미와 감동에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"한 작품 안에 재미와 감동이 둘 다 있을 수 있다","correct":true},{"t":"한 작품에는 재미나 감동 가운데 하나만 있다","mis":"K3-2-u6-X08"},{"t":"웃음이 나는 곳은 감동이다","mis":"K3-2-u6-X08"},{"t":"감동은 슬픈 작품에만 있다","mis":"K3-2-u6-X08"}],"explanation":["웃긴 곳도 있어요.","뭉클한 곳도 있어요.","한 작품에 둘 다 있을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L02_basic#10','kor',3,2,'u6','L02','g3_2_kor_u6_L02_basic','lesson_basic','K3-2-u6-C2',3,'error','auto','감상을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u6-X01','K3-2-u6-X07']::text[],false,'{"seq":10,"concept":"K3-2-u6-C2","difficulty":3,"kind":"error","stem":"감상을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「줄거리를 빠짐없이 외워야 감상한 거야.」","correct":true,"mis_target":"K3-2-u6-X01"},{"t":"친구 가 — 「마음이 움직인 자리를 찾는 게 감상이야.」","mis":"K3-2-u6-X01"},{"t":"친구 다 — 「어디를 보고 그랬는지도 말해야 해.」","mis":"K3-2-u6-X07"}],"explanation":["외우는 일이 아니에요.","마음이 움직인 자리를 찾아요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L02_challenge#1','kor',3,2,'u6','L02','g3_2_kor_u6_L02_challenge','lesson_challenge','K3-2-u6-C3',2,'sa','auto','마음이 뭉클하거나 오래 남거나 내 일처럼 느껴지는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u6-C3","difficulty":2,"kind":"sa","stem":"마음이 뭉클하거나 오래 남거나 내 일처럼 느껴지는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["감동"],"explanation":["웃음이 나면 재미예요.","뭉클하면 다른 말이에요.","‘감동’이에요."],"mis":"K3-2-u6-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L02_challenge#2','kor',3,2,'u6','L02','g3_2_kor_u6_L02_challenge','lesson_challenge','K3-2-u6-C4',2,'mc','auto','같은 이야기를 보고 한 사람은 마지막에서 눈물이 났고, 옆 사람은 가운데서 제일 웃었어요. 어떻게 된 걸까요?',ARRAY['K3-2-u6-X03','K3-2-u6-X04','K3-2-u6-X05']::text[],false,'{"seq":2,"concept":"K3-2-u6-C4","difficulty":2,"kind":"mc","stem":"같은 이야기를 보고 한 사람은 마지막에서 눈물이 났고, 옆 사람은 가운데서 제일 웃었어요. 어떻게 된 걸까요?","options":[{"t":"둘 다 제 감상이다. 어디를 보고 그랬는지 말하면 된다","correct":true},{"t":"둘 가운데 하나는 틀린 감상이다","mis":"K3-2-u6-X03"},{"t":"감상은 아무렇게나 말해도 되는 것이다","mis":"K3-2-u6-X04"},{"t":"웃은 사람은 이야기를 제대로 보지 않았다","mis":"K3-2-u6-X05"}],"explanation":["마음이 움직인 자리가 달랐어요.","둘 다 틀리지 않았어요.","근거를 말하면 돼요."],"asset":{"type":"passage","lines":["나란히 앉아 같은 이야기를 보고 나오며","한 사람은 “마지막에서 눈물이 났어.”라고 했고,","옆 사람은 “나는 가운데서 제일 웃었는데.”라고 했어요."],"title":"같은 것을 보았는데"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L02_challenge#3','kor',3,2,'u6','L02','g3_2_kor_u6_L02_challenge','lesson_challenge','K3-2-u6-C7',3,'mc','auto','「두고 온 우산」을 읽고 “이야기가 마음에 들었어.”라고만 말한 친구에게 물어볼 말로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X06','K3-2-u6-X02','K3-2-u6-X03']::text[],false,'{"seq":3,"concept":"K3-2-u6-C7","difficulty":3,"kind":"mc","stem":"「두고 온 우산」을 읽고 “이야기가 마음에 들었어.”라고만 말한 친구에게 물어볼 말로 알맞은 것은 무엇인가요?","options":[{"t":"“어느 곳을 보고 그렇게 느꼈어?”","correct":true},{"t":"“줄거리를 처음부터 말해 줄래?”","mis":"K3-2-u6-X06"},{"t":"“몇 점짜리 이야기였어?”","mis":"K3-2-u6-X02"},{"t":"“나랑 같은 곳에서 느꼈어?”","mis":"K3-2-u6-X03"}],"explanation":["느낌만 말했어요.","근거가 빠졌어요.","어디를 보았는지 물어요."],"asset":{"type":"passage","lines":["비가 그친 뒤, 나는 우산을 버스에 두고 내렸다.","다음 날 정류장에 갔더니 의자 위에 그 우산이 접힌 채 놓여 있었다.","손잡이에 쪽지가 감겨 있었다. “비 올 때 또 써요.”","나는 누가 놓아 두었는지 끝내 알지 못했다."],"title":"이야기 「두고 온 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L02_challenge#4','kor',3,2,'u6','L02','g3_2_kor_u6_L02_challenge','lesson_challenge','K3-2-u6-C5',3,'ox','auto','감상이 사람마다 다른 까닭은 감상은 아무 데나 느껴도 되기 때문이에요.',ARRAY['K3-2-u6-X04']::text[],false,'{"seq":4,"concept":"K3-2-u6-C5","difficulty":3,"kind":"ox","stem":"감상이 사람마다 다른 까닭은 감상은 아무 데나 느껴도 되기 때문이에요.","answer":"X","reason_options":[{"t":"저마다 겪은 일과 처지가 달라 마음이 걸리는 자리가 다르기 때문에","correct":true},{"t":"근거 없이 아무렇게나 느끼는 것도 감상이기 때문에","mis":"K3-2-u6-X04"}],"mis":"K3-2-u6-X04","explanation":["아무 데나가 아니에요.","겪은 일과 처지가 달라서예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L02_challenge#5','kor',3,2,'u6','L02','g3_2_kor_u6_L02_challenge','lesson_challenge','K3-2-u6-C6',3,'error','auto','「두고 온 우산」의 감상을 말했어요. 감상이라고 하기에 모자란 친구는 누구인가요?',ARRAY['K3-2-u6-X06','K3-2-u6-X07']::text[],false,'{"seq":5,"concept":"K3-2-u6-C6","difficulty":3,"kind":"error","stem":"「두고 온 우산」의 감상을 말했어요. 감상이라고 하기에 모자란 친구는 누구인가요?","options":[{"t":"친구 다 — 「우산을 두고 내렸는데 다음 날 의자 위에 있었대.」","correct":true,"mis_target":"K3-2-u6-X06"},{"t":"친구 가 — 「쪽지를 읽는 곳에서 마음이 따뜻해졌어.」","mis":"K3-2-u6-X06"},{"t":"친구 나 — 「끝까지 누군지 안 알려 줘서 궁금했어.」","mis":"K3-2-u6-X07"}],"explanation":["친구 다는 줄거리만 옮겼어요.","어떤 마음인지 빠졌어요.","친구 다가 모자라요."],"asset":{"type":"passage","lines":["비가 그친 뒤, 나는 우산을 버스에 두고 내렸다.","다음 날 정류장에 갔더니 의자 위에 그 우산이 접힌 채 놓여 있었다.","손잡이에 쪽지가 감겨 있었다. “비 올 때 또 써요.”","나는 누가 놓아 두었는지 끝내 알지 못했다."],"title":"이야기 「두고 온 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L02_challenge#6','kor',3,2,'u6','L02','g3_2_kor_u6_L02_challenge','lesson_challenge','K3-2-u6-C1',3,'mc','auto','감상하기와 의견을 제시하는 글 쓰기를 바르게 견준 것은 무엇인가요?',ARRAY['K3-2-u6-X01','K3-2-u6-X02','K3-2-u6-X20']::text[],false,'{"seq":6,"concept":"K3-2-u6-C1","difficulty":3,"kind":"mc","stem":"감상하기와 의견을 제시하는 글 쓰기를 바르게 견준 것은 무엇인가요?","options":[{"t":"감상하기는 받아들이는 일, 의견 글 쓰기는 내 생각을 내놓는 일이다","correct":true},{"t":"둘 다 작품의 줄거리를 외우는 일이다","mis":"K3-2-u6-X01"},{"t":"감상하기는 점수 매기기, 의견 글 쓰기는 고운 말 쓰기이다","mis":"K3-2-u6-X02"},{"t":"의견 글 쓰기에는 이유가 없어도 된다","mis":"K3-2-u6-X20"}],"explanation":["작품을 보며 받아들여요.","내 생각을 글로 내놓아요.","앞과 뒤가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L02_challenge#7','kor',3,2,'u6','L02','g3_2_kor_u6_L02_challenge','lesson_challenge','K3-2-u6-C2',3,'mc','auto','친구가 본 만화 영화를 소개하며 줄거리를 아주 자세히 말했어요. 감상이 되려면 무엇을 더해야 할까요?',ARRAY['K3-2-u6-X01','K3-2-u6-X02','K3-2-u6-X04']::text[],false,'{"seq":7,"concept":"K3-2-u6-C2","difficulty":3,"kind":"mc","stem":"친구가 본 만화 영화를 소개하며 줄거리를 아주 자세히 말했어요. 감상이 되려면 무엇을 더해야 할까요?","options":[{"t":"마음이 움직인 장면과 그때 든 마음","correct":true},{"t":"빠뜨린 줄거리","mis":"K3-2-u6-X01"},{"t":"그 만화 영화에 줄 점수","mis":"K3-2-u6-X02"},{"t":"나오는 인물의 수","mis":"K3-2-u6-X04"}],"explanation":["줄거리는 이미 말했어요.","마음이 빠졌어요.","장면과 마음을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L02_challenge#8','kor',3,2,'u6','L02','g3_2_kor_u6_L02_challenge','lesson_challenge','K3-2-u6-C5',4,'mc','auto','세 사람의 감상 ㉮ ㉯ ㉰를 두고 한 말 가운데 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X05','K3-2-u6-X03','K3-2-u6-X04']::text[],false,'{"seq":8,"concept":"K3-2-u6-C5","difficulty":4,"kind":"mc","stem":"세 사람의 감상 ㉮ ㉯ ㉰를 두고 한 말 가운데 가장 알맞은 것은 무엇인가요?","options":[{"t":"셋이 다른 곳에서 느꼈지만, 저마다 이야기 속 근거가 있으니 셋 다 제 감상이다","correct":true},{"t":"㉮만 쪽지라는 중요한 곳을 보았으니 ㉮만 맞다","mis":"K3-2-u6-X05"},{"t":"셋이 다르니 누가 맞는지 손을 들어 정해야 한다","mis":"K3-2-u6-X03"},{"t":"셋 다 근거 없이 말했으니 셋 다 틀렸다","mis":"K3-2-u6-X04"}],"explanation":["셋 다 이야기 속 곳을 보았어요.","보는 곳이 달랐을 뿐이에요.","셋 다 제 감상이에요."],"asset":{"type":"speech","turns":[{"who":"㉮","text":"쪽지에 적힌 말이 오래 남았어."},{"who":"㉯","text":"우산이 접힌 채 놓인 장면이 눈앞에 그려졌어."},{"who":"㉰","text":"누가 놓아 두었는지 끝까지 안 나오는 게 재미있었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L02_challenge#9','kor',3,2,'u6','L02','g3_2_kor_u6_L02_challenge','lesson_challenge','K3-2-u6-C4',4,'essay','teacher','같은 작품을 보고 친구와 다르게 느꼈을 때 어떻게 생각하면 좋을지 쓰고, 그래도 감상을 말할 때 꼭 함께 말해야 할 것을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u6-C4","difficulty":4,"kind":"essay","stem":"같은 작품을 보고 친구와 다르게 느꼈을 때 어떻게 생각하면 좋을지 쓰고, 그래도 감상을 말할 때 꼭 함께 말해야 할 것을 쓰세요.","answer_guide":{"answer":"예: 둘 가운데 하나가 틀린 것이 아니라 둘 다 제 감상이다. 사람마다 겪은 일과 처지가 달라 마음이 움직인 자리가 다를 수 있다. 다만 아무렇게나 말하는 것은 아니므로, 작품의 어느 장면을 보고 그렇게 느꼈는지를 함께 말해야 한다.","scoring_points":["둘 다 제 감상이라고 썼는가","다르게 느끼는 까닭을 썼는가","어느 장면을 보고 그랬는지 함께 말한다고 썼는가"]},"explanation":["하나가 틀린 게 아니에요.","까닭이 있어요.","근거를 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L02_challenge#10','kor',3,2,'u6','L02','g3_2_kor_u6_L02_challenge','lesson_challenge','K3-2-u6-C6',4,'essay','teacher','「두고 온 우산」에서 마음이 움직인 곳을 하나 골라 「어느 장면에서 + 어떤 마음」이 드러나게 감상을 쓰고, 그렇게 느낀 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u6-C6","difficulty":4,"kind":"essay","stem":"「두고 온 우산」에서 마음이 움직인 곳을 하나 골라 「어느 장면에서 + 어떤 마음」이 드러나게 감상을 쓰고, 그렇게 느낀 까닭을 쓰세요.","answer_guide":{"answer":"예: 손잡이에 감긴 쪽지 “비 올 때 또 써요.”를 읽는 장면에서 마음이 따뜻해졌다. 모르는 사람이 우산을 접어 두고 다음에 쓸 일까지 생각해 준 것이 고마웠기 때문이다. (고른 장면은 사람마다 다를 수 있다.)","scoring_points":["이야기 속 장면을 하나 골랐는가","그때 든 마음을 썼는가","그렇게 느낀 까닭을 썼는가"]},"explanation":["장면을 골라요.","마음을 이어요.","까닭을 붙여요."],"asset":{"type":"passage","lines":["비가 그친 뒤, 나는 우산을 버스에 두고 내렸다.","다음 날 정류장에 갔더니 의자 위에 그 우산이 접힌 채 놓여 있었다.","손잡이에 쪽지가 감겨 있었다. “비 올 때 또 써요.”","나는 누가 놓아 두었는지 끝내 알지 못했다."],"title":"이야기 「두고 온 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L03_basic#1','kor',3,2,'u6','L03','g3_2_kor_u6_L03_basic','lesson_basic','K3-2-u6-C8',1,'mc','auto','말이 없을 때 인물의 마음을 알 수 있는 것은 무엇인가요?',ARRAY['K3-2-u6-X09']::text[],false,'{"seq":1,"concept":"K3-2-u6-C8","difficulty":1,"kind":"mc","stem":"말이 없을 때 인물의 마음을 알 수 있는 것은 무엇인가요?","options":[{"t":"얼굴 표정","correct":true},{"t":"그 인물의 키","mis":"K3-2-u6-X09"},{"t":"그날의 날씨","mis":"K3-2-u6-X09"},{"t":"입은 옷의 색깔","mis":"K3-2-u6-X09"}],"explanation":["친구 기분을 알아챈 때를 떠올려요.","얼굴이 먼저 보여요.","표정이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L03_basic#2','kor',3,2,'u6','L03','g3_2_kor_u6_L03_basic','lesson_basic','K3-2-u6-C11',1,'mc','auto','작품을 감상하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X01','K3-2-u6-X02','K3-2-u6-X13']::text[],false,'{"seq":2,"concept":"K3-2-u6-C11","difficulty":1,"kind":"mc","stem":"작품을 감상하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"장면을 눈앞에 그리며 상상한다","correct":true},{"t":"줄거리만 빨리 외운다","mis":"K3-2-u6-X01"},{"t":"작품에 점수를 매기며 본다","mis":"K3-2-u6-X02"},{"t":"정해진 감동 지점 하나만 찾는다","mis":"K3-2-u6-X13"}],"explanation":["감상하는 길은 여럿이에요.","상상하며 보는 것도 그 하나예요.","외우기는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L03_basic#3','kor',3,2,'u6','L03','g3_2_kor_u6_L03_basic','lesson_basic','K3-2-u6-C12',1,'ox','auto','한 이야기 안에는 재미나 감동을 느낄 수 있는 자리가 여러 곳 있을 수 있어요.',ARRAY['K3-2-u6-X13']::text[],false,'{"seq":3,"concept":"K3-2-u6-C12","difficulty":1,"kind":"ox","stem":"한 이야기 안에는 재미나 감동을 느낄 수 있는 자리가 여러 곳 있을 수 있어요.","answer":"O","reason_options":[{"t":"「접힌 쪽지」에서도 국을 쏟는 곳은 웃음이, 작년 글씨를 보는 곳은 뭉클함이 있기 때문에","correct":true},{"t":"작품마다 감동 지점은 딱 한 곳으로 정해져 있기 때문에","mis":"K3-2-u6-X13"}],"mis":"K3-2-u6-X13","explanation":["웃긴 곳이 있어요.","뭉클한 곳도 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L03_basic#4','kor',3,2,'u6','L03','g3_2_kor_u6_L03_basic','lesson_basic','K3-2-u6-C10',1,'mc','auto','「접힌 쪽지」에서 쪽지를 쓴 사람은 누구였나요?',ARRAY['K3-2-u6-X11']::text[],false,'{"seq":4,"concept":"K3-2-u6-C10","difficulty":1,"kind":"mc","stem":"「접힌 쪽지」에서 쪽지를 쓴 사람은 누구였나요?","options":[{"t":"작년의 나","correct":true},{"t":"짝","mis":"K3-2-u6-X11"},{"t":"앞에 선 친구","mis":"K3-2-u6-X11"},{"t":"선생님","mis":"K3-2-u6-X11"}],"explanation":["짝은 주워 놓았을 뿐이에요.","뒷면 글씨를 봐요.","작년의 내 글씨였어요."],"asset":{"type":"passage","lines":["㉰ 하루가 끝날 때까지 아무도 자기가 쓴 것이라고 하지 않았다.","   나는 가방을 싸면서 쪽지를 구겨 넣었다. 손에 힘이 들어갔다.","㉱ 짝이 말했다. “그거 내 거 아니야. 네 사물함 밑에 떨어져 있길래 주워 놨어.”","   쪽지를 뒤집어 보니 뒷면에 번지지 않은 글씨가 남아 있었다.","   작년에 내가 쓰던 글씨였다. “3학년 되면 꼭 물어보기.”"],"title":"이야기 「접힌 쪽지」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L03_basic#5','kor',3,2,'u6','L03','g3_2_kor_u6_L03_basic','lesson_basic','K3-2-u6-C9',2,'mc','auto','㉰의 “손에 힘이 들어갔다”는 무엇을 말해 줄까요?',ARRAY['K3-2-u6-X10']::text[],false,'{"seq":5,"concept":"K3-2-u6-C9","difficulty":2,"kind":"mc","stem":"㉰의 “손에 힘이 들어갔다”는 무엇을 말해 줄까요?","options":[{"t":"아무도 나서지 않아 서운한 마음이 들었다","correct":true},{"t":"힘이 세다는 것을 자랑하고 있다","mis":"K3-2-u6-X10"},{"t":"교실이 추워서 손이 굳었다","mis":"K3-2-u6-X10"},{"t":"쪽지가 무거워서 꽉 쥐었다","mis":"K3-2-u6-X10"}],"explanation":["앞줄을 다시 읽어요.","아무도 나서지 않았어요.","마음이 행동에 남았어요."],"asset":{"type":"passage","lines":["㉰ 하루가 끝날 때까지 아무도 자기가 쓴 것이라고 하지 않았다.","   나는 가방을 싸면서 쪽지를 구겨 넣었다. 손에 힘이 들어갔다.","㉱ 짝이 말했다. “그거 내 거 아니야. 네 사물함 밑에 떨어져 있길래 주워 놨어.”","   쪽지를 뒤집어 보니 뒷면에 번지지 않은 글씨가 남아 있었다.","   작년에 내가 쓰던 글씨였다. “3학년 되면 꼭 물어보기.”"],"title":"이야기 「접힌 쪽지」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L03_basic#6','kor',3,2,'u6','L03','g3_2_kor_u6_L03_basic','lesson_basic','K3-2-u6-C10',2,'match','auto','「접힌 쪽지」 ①에서 일어난 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K3-2-u6-C10","difficulty":2,"kind":"match","stem":"「접힌 쪽지」 ①에서 일어난 일을 알맞게 이으세요.","pairs":[{"l":"서랍","r":"접힌 쪽지를 찾았다"},{"l":"곁눈질","r":"남의 공책을 들여다보았다"},{"l":"급식 줄","r":"국을 신발에 쏟았다"}],"mis":"K3-2-u6-X11","explanation":["장면마다 일어난 일이 달라요.","하나씩 짚어요.","세 짝을 이어요."],"asset":{"type":"passage","lines":["㉮ 서랍을 뒤지다가 접힌 쪽지 하나를 찾았다. 글씨가 번져 읽히지 않았다.","   나는 쪽지를 손바닥에 올려놓고 한참을 들여다보았다.","㉯ 누가 썼는지 알고 싶어서 하루 종일 남의 공책을 곁눈질했다.","   급식 줄에서까지 앞 친구의 공책을 들여다보다가 국을 신발에 쏟았다.","   뒤에 선 친구들이 한꺼번에 웃었고, 나는 얼굴이 빨개진 채 자리로 갔다."],"title":"이야기 「접힌 쪽지」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L03_basic#7','kor',3,2,'u6','L03','g3_2_kor_u6_L03_basic','lesson_basic','K3-2-u6-C11',2,'match','auto','세 사람이 쓴 감상 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u6-C11","difficulty":2,"kind":"match","stem":"세 사람이 쓴 감상 방법을 알맞게 이으세요.","pairs":[{"l":"“얼굴이 빨개진 게 보이는 것 같았어.”","r":"표정과 말투에 주의하기"},{"l":"“국이 쏟아지는 장면이 그려졌어.”","r":"눈앞에 그리며 상상하기"},{"l":"“나도 옛 물건에서 내 글씨를 본 적 있어.”","r":"내 일과 이어 보기"}],"mis":"K3-2-u6-X12","explanation":["무엇에 눈을 두었는지 봐요.","길이 여럿이에요.","세 짝을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L03_basic#8','kor',3,2,'u6','L03','g3_2_kor_u6_L03_basic','lesson_basic','K3-2-u6-C13',2,'mc','auto','감상을 친구와 나누면 무엇이 좋을까요?',ARRAY['K3-2-u6-X14','K3-2-u6-X03']::text[],false,'{"seq":8,"concept":"K3-2-u6-C13","difficulty":2,"kind":"mc","stem":"감상을 친구와 나누면 무엇이 좋을까요?","options":[{"t":"내가 못 보고 지나친 자리를 알게 된다","correct":true},{"t":"같은 곳을 느꼈는지 맞춰 볼 수 있다","mis":"K3-2-u6-X14"},{"t":"내 감상이 맞는지 확인받을 수 있다","mis":"K3-2-u6-X14"},{"t":"누가 더 잘 감상했는지 가릴 수 있다","mis":"K3-2-u6-X03"}],"explanation":["맞춰 보려는 게 아니에요.","확인받으려는 것도 아니에요.","작품이 넓어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L03_basic#9','kor',3,2,'u6','L03','g3_2_kor_u6_L03_basic','lesson_basic','K3-2-u6-C12',2,'mc','auto','「접힌 쪽지」에서 재미나 감동을 느낄 곳으로 알맞지 않은 것은 무엇인가요?',ARRAY['K3-2-u6-X13']::text[],false,'{"seq":9,"concept":"K3-2-u6-C12","difficulty":2,"kind":"mc","stem":"「접힌 쪽지」에서 재미나 감동을 느낄 곳으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"쪽지를 쓴 사람이 선생님으로 밝혀지는 곳","correct":true},{"t":"국을 신발에 쏟는 곳","mis":"K3-2-u6-X13"},{"t":"작년 내 글씨를 알아보는 곳","mis":"K3-2-u6-X13"},{"t":"짝이 주워 놓았다고 말하는 곳","mis":"K3-2-u6-X13"}],"explanation":["이야기 안에 있는 곳이면 돼요.","선생님이 쓴 곳은 없어요.","없는 곳은 고를 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L03_basic#10','kor',3,2,'u6','L03','g3_2_kor_u6_L03_basic','lesson_basic','K3-2-u6-C9',3,'error','auto','㉯에서 “얼굴이 빨개진 채 자리로 갔다”를 보고 말했어요. 잘못 짐작한 친구는 누구인가요?',ARRAY['K3-2-u6-X10']::text[],false,'{"seq":10,"concept":"K3-2-u6-C9","difficulty":3,"kind":"error","stem":"㉯에서 “얼굴이 빨개진 채 자리로 갔다”를 보고 말했어요. 잘못 짐작한 친구는 누구인가요?","options":[{"t":"친구 다 — 「더워서 얼굴이 빨개졌을 거야.」","correct":true,"mis_target":"K3-2-u6-X10"},{"t":"친구 가 — 「친구들이 웃어서 부끄러웠을 거야.」","mis":"K3-2-u6-X10"},{"t":"친구 나 — 「국을 쏟아 창피했을 거야.」","mis":"K3-2-u6-X10"}],"explanation":["바로 앞에 무슨 일이 있었나요?","국을 쏟고 다들 웃었어요.","친구 다가 잘못 짐작했어요."],"asset":{"type":"passage","lines":["㉮ 서랍을 뒤지다가 접힌 쪽지 하나를 찾았다. 글씨가 번져 읽히지 않았다.","   나는 쪽지를 손바닥에 올려놓고 한참을 들여다보았다.","㉯ 누가 썼는지 알고 싶어서 하루 종일 남의 공책을 곁눈질했다.","   급식 줄에서까지 앞 친구의 공책을 들여다보다가 국을 신발에 쏟았다.","   뒤에 선 친구들이 한꺼번에 웃었고, 나는 얼굴이 빨개진 채 자리로 갔다."],"title":"이야기 「접힌 쪽지」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L03_challenge#1','kor',3,2,'u6','L03','g3_2_kor_u6_L03_challenge','lesson_challenge','K3-2-u6-C8',2,'sa','auto','말이 없어도 인물의 마음을 알려 주는 것 가운데, 얼굴에 드러나는 것을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u6-C8","difficulty":2,"kind":"sa","stem":"말이 없어도 인물의 마음을 알려 주는 것 가운데, 얼굴에 드러나는 것을 두 글자로 쓰세요.","answer":["표정"],"explanation":["몸짓은 몸에 드러나요.","얼굴에 드러나는 것은?","‘표정’이에요."],"mis":"K3-2-u6-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L03_challenge#2','kor',3,2,'u6','L03','g3_2_kor_u6_L03_challenge','lesson_challenge','K3-2-u6-C10',2,'mc','auto','「접힌 쪽지」의 일을 차례대로 늘어놓은 것은 무엇인가요?',ARRAY['K3-2-u6-X11']::text[],false,'{"seq":2,"concept":"K3-2-u6-C10","difficulty":2,"kind":"mc","stem":"「접힌 쪽지」의 일을 차례대로 늘어놓은 것은 무엇인가요?","options":[{"t":"쪽지를 찾았다 → 국을 쏟았다 → 아무도 나서지 않았다 → 쓴 사람이 밝혀졌다","correct":true},{"t":"국을 쏟았다 → 쪽지를 찾았다 → 쓴 사람이 밝혀졌다 → 아무도 나서지 않았다","mis":"K3-2-u6-X11"},{"t":"쪽지를 찾았다 → 쓴 사람이 밝혀졌다 → 국을 쏟았다 → 아무도 나서지 않았다","mis":"K3-2-u6-X11"},{"t":"쓴 사람이 밝혀졌다 → 쪽지를 찾았다 → 국을 쏟았다 → 아무도 나서지 않았다","mis":"K3-2-u6-X11"}],"explanation":["㉮ 서랍부터예요.","㉯ 급식 줄, ㉰ 하루의 끝이에요.","㉱ 뒷면에서 밝혀져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L03_challenge#3','kor',3,2,'u6','L03','g3_2_kor_u6_L03_challenge','lesson_challenge','K3-2-u6-C9',3,'mc','auto','㉮에서 쪽지를 “한참을 들여다보았다”는 행동에서 짐작할 수 있는 마음은 무엇인가요?',ARRAY['K3-2-u6-X10']::text[],false,'{"seq":3,"concept":"K3-2-u6-C9","difficulty":3,"kind":"mc","stem":"㉮에서 쪽지를 “한참을 들여다보았다”는 행동에서 짐작할 수 있는 마음은 무엇인가요?","options":[{"t":"누가 무슨 말을 썼는지 몹시 궁금했다","correct":true},{"t":"쪽지가 귀찮아 버리고 싶었다","mis":"K3-2-u6-X10"},{"t":"글씨가 예뻐서 따라 쓰고 싶었다","mis":"K3-2-u6-X10"},{"t":"손바닥이 아파서 쉬고 있었다","mis":"K3-2-u6-X10"}],"explanation":["글씨가 번져 읽히지 않았어요.","그래도 오래 들여다보았어요.","궁금했던 거예요."],"asset":{"type":"passage","lines":["㉮ 서랍을 뒤지다가 접힌 쪽지 하나를 찾았다. 글씨가 번져 읽히지 않았다.","   나는 쪽지를 손바닥에 올려놓고 한참을 들여다보았다.","㉯ 누가 썼는지 알고 싶어서 하루 종일 남의 공책을 곁눈질했다.","   급식 줄에서까지 앞 친구의 공책을 들여다보다가 국을 신발에 쏟았다.","   뒤에 선 친구들이 한꺼번에 웃었고, 나는 얼굴이 빨개진 채 자리로 갔다."],"title":"이야기 「접힌 쪽지」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L03_challenge#4','kor',3,2,'u6','L03','g3_2_kor_u6_L03_challenge','lesson_challenge','K3-2-u6-C12',3,'ox','auto','「접힌 쪽지」를 읽고 “국을 쏟는 곳이 재미있었어.”라고 말한 친구는 감동적인 곳을 놓쳤으니 잘못 감상한 거예요.',ARRAY['K3-2-u6-X13']::text[],false,'{"seq":4,"concept":"K3-2-u6-C12","difficulty":3,"kind":"ox","stem":"「접힌 쪽지」를 읽고 “국을 쏟는 곳이 재미있었어.”라고 말한 친구는 감동적인 곳을 놓쳤으니 잘못 감상한 거예요.","answer":"X","reason_options":[{"t":"이야기 안에 실제로 있는 곳을 보고 느낀 것이니 제 감상이기 때문에","correct":true},{"t":"이 이야기의 감동 지점은 마지막 한 곳으로 정해져 있기 때문에","mis":"K3-2-u6-X13"}],"mis":"K3-2-u6-X13","explanation":["국을 쏟는 곳도 이야기 안에 있어요.","느낄 자리는 여럿이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L03_challenge#5','kor',3,2,'u6','L03','g3_2_kor_u6_L03_challenge','lesson_challenge','K3-2-u6-C13',3,'error','auto','감상을 나눈 뒤 말했어요. 감상을 나누는 까닭을 잘못 안 친구는 누구인가요?',ARRAY['K3-2-u6-X14']::text[],false,'{"seq":5,"concept":"K3-2-u6-C13","difficulty":3,"kind":"error","stem":"감상을 나눈 뒤 말했어요. 감상을 나누는 까닭을 잘못 안 친구는 누구인가요?","options":[{"t":"친구 나 — 「내 감상이 정답인지 확인받아서 좋았어.」","correct":true,"mis_target":"K3-2-u6-X14"},{"t":"친구 가 — 「나는 못 본 곳을 친구가 말해 줘서 좋았어.」","mis":"K3-2-u6-X14"},{"t":"친구 다 — 「다시 보니 작품이 더 넓어진 것 같아.」","mis":"K3-2-u6-X14"}],"explanation":["감상에 정답은 없어요.","못 본 자리를 알게 돼요.","친구 나가 잘못 알았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L03_challenge#6','kor',3,2,'u6','L03','g3_2_kor_u6_L03_challenge','lesson_challenge','K3-2-u6-C11',3,'mc','auto','“나도 작년 물건에서 내 글씨를 본 적 있어.”라고 말한 친구가 쓴 감상 방법은 무엇인가요?',ARRAY['K3-2-u6-X12','K3-2-u6-X01']::text[],false,'{"seq":6,"concept":"K3-2-u6-C11","difficulty":3,"kind":"mc","stem":"“나도 작년 물건에서 내 글씨를 본 적 있어.”라고 말한 친구가 쓴 감상 방법은 무엇인가요?","options":[{"t":"인물의 일을 내 일과 이어 보기","correct":true},{"t":"표정과 말투에 주의하기","mis":"K3-2-u6-X12"},{"t":"장면을 눈앞에 그리며 상상하기","mis":"K3-2-u6-X12"},{"t":"줄거리를 차례대로 외우기","mis":"K3-2-u6-X01"}],"explanation":["“나도 … 본 적 있어”예요.","내 일을 떠올렸어요.","내 일과 이어 본 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L03_challenge#7','kor',3,2,'u6','L03','g3_2_kor_u6_L03_challenge','lesson_challenge','K3-2-u6-C8',3,'mc','auto','이야기 속 인물이 아무 말을 하지 않을 때 그 마음을 짐작하는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X10','K3-2-u6-X09']::text[],false,'{"seq":7,"concept":"K3-2-u6-C8","difficulty":3,"kind":"mc","stem":"이야기 속 인물이 아무 말을 하지 않을 때 그 마음을 짐작하는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"표정과 몸짓, 그 앞에 있었던 일을 함께 살핀다","correct":true},{"t":"말을 하지 않았으니 마음도 없다고 본다","mis":"K3-2-u6-X10"},{"t":"인물의 키나 옷을 보고 정한다","mis":"K3-2-u6-X09"},{"t":"그날 날씨로 마음을 정한다","mis":"K3-2-u6-X09"}],"explanation":["몸이 마음을 말해요.","앞에 있었던 일도 봐요.","함께 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L03_challenge#8','kor',3,2,'u6','L03','g3_2_kor_u6_L03_challenge','lesson_challenge','K3-2-u6-C12',4,'mc','auto','「접힌 쪽지」에서 재미나 감동을 느낄 수 있는 곳을 바르게 모은 것은 무엇인가요?',ARRAY['K3-2-u6-X13','K3-2-u6-X04']::text[],false,'{"seq":8,"concept":"K3-2-u6-C12","difficulty":4,"kind":"mc","stem":"「접힌 쪽지」에서 재미나 감동을 느낄 수 있는 곳을 바르게 모은 것은 무엇인가요?","options":[{"t":"국을 쏟는 곳 · 짝이 주워 놓았다고 말하는 곳 · 작년 내 글씨를 알아보는 곳","correct":true},{"t":"작년 내 글씨를 알아보는 곳 한 곳뿐","mis":"K3-2-u6-X13"},{"t":"국을 쏟는 곳 · 쪽지를 쓴 사람이 선생님인 곳","mis":"K3-2-u6-X04"},{"t":"이 이야기를 읽은 사람 수 · 국을 쏟는 곳","mis":"K3-2-u6-X04"}],"explanation":["이야기 안의 곳은 모두 돼요.","없는 곳과 이야기 밖의 일은 빼요.","여러 곳을 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L03_challenge#9','kor',3,2,'u6','L03','g3_2_kor_u6_L03_challenge','lesson_challenge','K3-2-u6-C9',4,'essay','teacher','㉰에서 인물은 마음을 말로 적지 않았어요. “손에 힘이 들어갔다”에서 짐작한 마음을 쓰고, 무엇을 보고 그렇게 짐작했는지 앞 줄의 일과 이어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u6-C9","difficulty":4,"kind":"essay","stem":"㉰에서 인물은 마음을 말로 적지 않았어요. “손에 힘이 들어갔다”에서 짐작한 마음을 쓰고, 무엇을 보고 그렇게 짐작했는지 앞 줄의 일과 이어 쓰세요.","answer_guide":{"answer":"예: 서운하고 속상한 마음이었을 것이다. 바로 앞 줄에서 하루가 끝날 때까지 아무도 자기가 썼다고 하지 않았고, 그래서 쪽지를 구겨 넣으며 손에 힘이 들어갔기 때문이다. 말 대신 행동에 마음이 남아 있다.","scoring_points":["짐작한 마음을 썼는가","앞 줄의 일을 근거로 들었는가","행동에 마음이 드러난다고 썼는가"]},"explanation":["마음을 짐작해요.","앞줄의 일과 이어요.","행동이 근거예요."],"asset":{"type":"passage","lines":["㉰ 하루가 끝날 때까지 아무도 자기가 쓴 것이라고 하지 않았다.","   나는 가방을 싸면서 쪽지를 구겨 넣었다. 손에 힘이 들어갔다.","㉱ 짝이 말했다. “그거 내 거 아니야. 네 사물함 밑에 떨어져 있길래 주워 놨어.”","   쪽지를 뒤집어 보니 뒷면에 번지지 않은 글씨가 남아 있었다.","   작년에 내가 쓰던 글씨였다. “3학년 되면 꼭 물어보기.”"],"title":"이야기 「접힌 쪽지」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L03_challenge#10','kor',3,2,'u6','L03','g3_2_kor_u6_L03_challenge','lesson_challenge','K3-2-u6-C13',4,'essay','teacher','친구와 감상을 나누었더니 친구는 내가 못 본 곳에서 감동을 느꼈어요. 이때 어떻게 하면 좋을지 쓰고, 감상을 나누면 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u6-C13","difficulty":4,"kind":"essay","stem":"친구와 감상을 나누었더니 친구는 내가 못 본 곳에서 감동을 느꼈어요. 이때 어떻게 하면 좋을지 쓰고, 감상을 나누면 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 친구에게 어디를 보고 그렇게 느꼈는지 물어보고, 그 장면을 다시 보겠다. 감상을 나누면 내가 못 보고 지나친 자리를 알게 되어 작품을 더 넓게 볼 수 있다. 누구 감상이 맞는지 가리려는 것이 아니다.","scoring_points":["친구의 근거를 묻고 다시 본다고 썼는가","못 본 자리를 알게 된다고 썼는가","맞고 틀림을 가리려는 것이 아니라고 썼는가"]},"explanation":["어디를 보았는지 물어요.","다시 봐요.","작품이 넓어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L05_basic#1','kor',3,2,'u6','L05','g3_2_kor_u6_L05_basic','lesson_basic','K3-2-u6-C14',1,'mc','auto','인물이 무엇을 소중히 여기는지는 어떻게 알 수 있나요?',ARRAY['K3-2-u6-X15']::text[],false,'{"seq":1,"concept":"K3-2-u6-C14","difficulty":1,"kind":"mc","stem":"인물이 무엇을 소중히 여기는지는 어떻게 알 수 있나요?","options":[{"t":"인물이 한 말과 한 행동을 보고 읽어 낸다","correct":true},{"t":"이야기에 적힌 “소중히 여기는 것” 줄을 찾는다","mis":"K3-2-u6-X15"},{"t":"제목만 보고 정한다","mis":"K3-2-u6-X15"},{"t":"인물의 생김새로 짐작한다","mis":"K3-2-u6-X15"}],"explanation":["이야기에 적혀 있지 않아요.","말과 행동에 남아 있어요.","우리가 읽어 내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L05_basic#2','kor',3,2,'u6','L05','g3_2_kor_u6_L05_basic','lesson_basic','K3-2-u6-C15',1,'mc','auto','「같은 자리」에서 나는 아침마다 무엇을 하나요?',ARRAY['K3-2-u6-X11']::text[],false,'{"seq":2,"concept":"K3-2-u6-C15","difficulty":1,"kind":"mc","stem":"「같은 자리」에서 나는 아침마다 무엇을 하나요?","options":[{"t":"교실 뒤 화분에 물을 준다","correct":true},{"t":"사물함을 정리한다","mis":"K3-2-u6-X11"},{"t":"체육복을 갈아입는다","mis":"K3-2-u6-X11"},{"t":"창문을 연다","mis":"K3-2-u6-X11"}],"explanation":["㉮ 첫 줄을 봐요.","화분이 나와요.","물을 줘요."],"asset":{"type":"passage","lines":["㉮ 나는 아침마다 교실 뒤 화분에 물을 준다.","   봄에 두 장이던 잎이 지금은 여섯 장이다. 나는 그 수를 다 세고 있다.","㉯ 짝이 사물함 문을 반쯤 열다가 화분에 걸려 멈췄다.","   체육복을 억지로 빼내다가 팔꿈치를 문에 부딪혔다.","   “이거 좀 옮기면 안 돼? 매번 이래.”"],"title":"이야기 「같은 자리」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L05_basic#3','kor',3,2,'u6','L05','g3_2_kor_u6_L05_basic','lesson_basic','K3-2-u6-C16',1,'ox','auto','「같은 자리」의 두 사람은 둘 다 소중히 여기는 것이 있어서 부딪쳤어요.',ARRAY['K3-2-u6-X16']::text[],false,'{"seq":3,"concept":"K3-2-u6-C16","difficulty":1,"kind":"ox","stem":"「같은 자리」의 두 사람은 둘 다 소중히 여기는 것이 있어서 부딪쳤어요.","answer":"O","reason_options":[{"t":"나는 화분이 잘 자라는 것을, 짝은 사물함을 불편 없이 쓰는 것을 소중히 여겼기 때문에","correct":true},{"t":"둘 가운데 한 사람이 잘못을 했기 때문에","mis":"K3-2-u6-X16"}],"mis":"K3-2-u6-X16","explanation":["둘 다 잘못하지 않았어요.","둘 다 물러설 수 없었어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L05_basic#4','kor',3,2,'u6','L05','g3_2_kor_u6_L05_basic','lesson_basic','K3-2-u6-C17',1,'mc','auto','인물에게 물어볼 만한 질문은 무엇인가요?',ARRAY['K3-2-u6-X17']::text[],false,'{"seq":4,"concept":"K3-2-u6-C17","difficulty":1,"kind":"mc","stem":"인물에게 물어볼 만한 질문은 무엇인가요?","options":[{"t":"“그때 어떤 마음이었나요?”","correct":true},{"t":"“이 학교의 이름이 무엇인가요?”","mis":"K3-2-u6-X17"},{"t":"“이 이야기를 누가 썼나요?”","mis":"K3-2-u6-X17"},{"t":"“이 책은 몇 쪽인가요?”","mis":"K3-2-u6-X17"}],"explanation":["인물이 답할 수 있어야 해요.","마음을 묻는 질문이 좋아요.","답이 이야기 밖에 있으면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L05_basic#5','kor',3,2,'u6','L05','g3_2_kor_u6_L05_basic','lesson_basic','K3-2-u6-C14',2,'match','auto','말과 행동에서 읽어 낸 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u6-C14","difficulty":2,"kind":"match","stem":"말과 행동에서 읽어 낸 것을 알맞게 이으세요.","pairs":[{"l":"잎 수를 다 세는 나","r":"살아 있는 것은 돌보아야 잘 자란다"},{"l":"“매번 이래.”라고 말한 짝","r":"함께 쓰는 곳은 누구나 불편하지 않아야 한다"},{"l":"“창가는 어때?”라고 먼저 말한 짝","r":"둘 다 지킬 수 있는 자리를 찾는 것"}],"mis":"K3-2-u6-X15","explanation":["말과 행동을 다시 읽어요.","거기서 소중한 것이 보여요.","세 짝을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L05_basic#6','kor',3,2,'u6','L05','g3_2_kor_u6_L05_basic','lesson_basic','K3-2-u6-C15',2,'mc','auto','㉰에서 둘이 말이 없어진 까닭은 무엇일까요?',ARRAY['K3-2-u6-X16','K3-2-u6-X11','K3-2-u6-X15']::text[],false,'{"seq":6,"concept":"K3-2-u6-C15","difficulty":2,"kind":"mc","stem":"㉰에서 둘이 말이 없어진 까닭은 무엇일까요?","options":[{"t":"서로 물러설 수 없는 것이 하나씩 있었기 때문에","correct":true},{"t":"둘이 원래 사이가 나빴기 때문에","mis":"K3-2-u6-X16"},{"t":"수업 시간이 시작되었기 때문에","mis":"K3-2-u6-X11"},{"t":"짝이 화분을 싫어했기 때문에","mis":"K3-2-u6-X15"}],"explanation":["한 사람은 볕을 말했어요.","다른 사람은 문을 말했어요.","둘 다 물러설 수 없었어요."],"asset":{"type":"passage","lines":["㉰ “여기가 제일 볕이 잘 드는데.” 나는 그렇게만 말했다.","   짝은 체육복을 안고 돌아섰고, 그날 우리는 더 말하지 않았다.","㉱ 며칠 뒤 화분을 복도로 내놓았더니 얼마 안 가 잎 끝이 노래졌다.","   나는 화분 앞에 쪼그려 앉아 있었다.","   짝이 먼저 말했다. “창가는 어때? 거기도 볕 들잖아.”","   창가에 두니 화분이 들어가고, 사물함 문이 끝까지 열렸다."],"title":"이야기 「같은 자리」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L05_basic#7','kor',3,2,'u6','L05','g3_2_kor_u6_L05_basic','lesson_basic','K3-2-u6-C16',2,'mc','auto','「같은 자리」의 두 사람 가운데 누가 옳았을까요?',ARRAY['K3-2-u6-X16']::text[],false,'{"seq":7,"concept":"K3-2-u6-C16","difficulty":2,"kind":"mc","stem":"「같은 자리」의 두 사람 가운데 누가 옳았을까요?","options":[{"t":"둘 다 소중히 여기는 것이 있었다. 한쪽을 고를 물음이 아니다","correct":true},{"t":"화분을 돌본 쪽이 옳았다","mis":"K3-2-u6-X16"},{"t":"모두가 쓰는 곳을 말한 쪽이 옳았다","mis":"K3-2-u6-X16"},{"t":"먼저 말을 꺼낸 짝이 옳았다","mis":"K3-2-u6-X16"}],"explanation":["한쪽이 옳다고 하면","다른 쪽의 소중한 것은 어디로 갈까요?","둘 다 있었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L05_basic#8','kor',3,2,'u6','L05','g3_2_kor_u6_L05_basic','lesson_basic','K3-2-u6-C17',2,'mc','auto','“팔꿈치를 부딪혔을 때 어떤 마음이었어요?”는 누구에게 물어볼 질문인가요?',ARRAY['K3-2-u6-X11','K3-2-u6-X17']::text[],false,'{"seq":8,"concept":"K3-2-u6-C17","difficulty":2,"kind":"mc","stem":"“팔꿈치를 부딪혔을 때 어떤 마음이었어요?”는 누구에게 물어볼 질문인가요?","options":[{"t":"짝","correct":true},{"t":"나","mis":"K3-2-u6-X11"},{"t":"선생님","mis":"K3-2-u6-X17"},{"t":"이 이야기를 쓴 사람","mis":"K3-2-u6-X17"}],"explanation":["㉯를 다시 봐요.","팔꿈치를 부딪힌 사람이에요.","짝이에요."],"asset":{"type":"passage","lines":["㉮ 나는 아침마다 교실 뒤 화분에 물을 준다.","   봄에 두 장이던 잎이 지금은 여섯 장이다. 나는 그 수를 다 세고 있다.","㉯ 짝이 사물함 문을 반쯤 열다가 화분에 걸려 멈췄다.","   체육복을 억지로 빼내다가 팔꿈치를 문에 부딪혔다.","   “이거 좀 옮기면 안 돼? 매번 이래.”"],"title":"이야기 「같은 자리」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L05_basic#9','kor',3,2,'u6','L05','g3_2_kor_u6_L05_basic','lesson_basic','K3-2-u6-C18',2,'mc','auto','친구와 부딪친 일을 떠올렸을 때 먼저 보면 좋은 것은 무엇인가요?',ARRAY['K3-2-u6-X16','K3-2-u6-X18']::text[],false,'{"seq":9,"concept":"K3-2-u6-C18","difficulty":2,"kind":"mc","stem":"친구와 부딪친 일을 떠올렸을 때 먼저 보면 좋은 것은 무엇인가요?","options":[{"t":"서로 무엇을 소중히 여겼는지","correct":true},{"t":"누가 먼저 잘못했는지","mis":"K3-2-u6-X16"},{"t":"부딪친 일은 덮어 두고 말하지 않기","mis":"K3-2-u6-X18"},{"t":"누구 편이 더 많은지","mis":"K3-2-u6-X16"}],"explanation":["잘잘못부터 가리면","창가 같은 자리는 안 찾아져요.","소중히 여긴 것부터 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L05_basic#10','kor',3,2,'u6','L05','g3_2_kor_u6_L05_basic','lesson_basic','K3-2-u6-C14',3,'error','auto','「같은 자리」를 읽고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u6-X15']::text[],false,'{"seq":10,"concept":"K3-2-u6-C14","difficulty":3,"kind":"error","stem":"「같은 자리」를 읽고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「짝은 화분을 싫어해서 옮기라고 한 거야.」","correct":true,"mis_target":"K3-2-u6-X15"},{"t":"친구 가 — 「잎 수를 다 세는 걸 보면 화분을 아끼는 거야.」","mis":"K3-2-u6-X15"},{"t":"친구 나 — 「팔꿈치를 부딪혀 불편해서 옮기자고 한 거야.」","mis":"K3-2-u6-X15"}],"explanation":["짝이 한 말을 봐요.","“매번 이래.”는 불편하다는 말이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉮ 나는 아침마다 교실 뒤 화분에 물을 준다.","   봄에 두 장이던 잎이 지금은 여섯 장이다. 나는 그 수를 다 세고 있다.","㉯ 짝이 사물함 문을 반쯤 열다가 화분에 걸려 멈췄다.","   체육복을 억지로 빼내다가 팔꿈치를 문에 부딪혔다.","   “이거 좀 옮기면 안 돼? 매번 이래.”"],"title":"이야기 「같은 자리」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L05_challenge#1','kor',3,2,'u6','L05','g3_2_kor_u6_L05_challenge','lesson_challenge','K3-2-u6-C15',2,'sa','auto','「같은 자리」에서 두 사람이 화분을 두기로 한 곳은 어디인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u6-C15","difficulty":2,"kind":"sa","stem":"「같은 자리」에서 두 사람이 화분을 두기로 한 곳은 어디인가요? 두 글자로 쓰세요.","answer":["창가"],"explanation":["㉱를 봐요.","짝이 먼저 말했어요.","‘창가’예요."],"asset":{"type":"passage","lines":["㉰ “여기가 제일 볕이 잘 드는데.” 나는 그렇게만 말했다.","   짝은 체육복을 안고 돌아섰고, 그날 우리는 더 말하지 않았다.","㉱ 며칠 뒤 화분을 복도로 내놓았더니 얼마 안 가 잎 끝이 노래졌다.","   나는 화분 앞에 쪼그려 앉아 있었다.","   짝이 먼저 말했다. “창가는 어때? 거기도 볕 들잖아.”","   창가에 두니 화분이 들어가고, 사물함 문이 끝까지 열렸다."],"title":"이야기 「같은 자리」 ②"},"mis":"K3-2-u6-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L05_challenge#2','kor',3,2,'u6','L05','g3_2_kor_u6_L05_challenge','lesson_challenge','K3-2-u6-C14',2,'mc','auto','“여기가 제일 볕이 잘 드는데.”라는 말에서 읽어 낼 수 있는 것은 무엇인가요?',ARRAY['K3-2-u6-X15']::text[],false,'{"seq":2,"concept":"K3-2-u6-C14","difficulty":2,"kind":"mc","stem":"“여기가 제일 볕이 잘 드는데.”라는 말에서 읽어 낼 수 있는 것은 무엇인가요?","options":[{"t":"화분이 잘 자라는 것을 소중히 여긴다","correct":true},{"t":"짝을 놀리고 싶어 한다","mis":"K3-2-u6-X15"},{"t":"창가를 싫어한다","mis":"K3-2-u6-X15"},{"t":"볕을 피하고 싶어 한다","mis":"K3-2-u6-X15"}],"explanation":["볕이 왜 중요할까요?","화분이 자라려면 볕이 들어야 해요.","화분을 아끼는 거예요."],"asset":{"type":"passage","lines":["㉰ “여기가 제일 볕이 잘 드는데.” 나는 그렇게만 말했다.","   짝은 체육복을 안고 돌아섰고, 그날 우리는 더 말하지 않았다.","㉱ 며칠 뒤 화분을 복도로 내놓았더니 얼마 안 가 잎 끝이 노래졌다.","   나는 화분 앞에 쪼그려 앉아 있었다.","   짝이 먼저 말했다. “창가는 어때? 거기도 볕 들잖아.”","   창가에 두니 화분이 들어가고, 사물함 문이 끝까지 열렸다."],"title":"이야기 「같은 자리」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L05_challenge#3','kor',3,2,'u6','L05','g3_2_kor_u6_L05_challenge','lesson_challenge','K3-2-u6-C16',3,'mc','auto','「같은 자리」에서 화분을 복도로 내놓은 뒤 잎 끝이 노래진 일은 무엇을 보여 줄까요?',ARRAY['K3-2-u6-X16','K3-2-u6-X11']::text[],false,'{"seq":3,"concept":"K3-2-u6-C16","difficulty":3,"kind":"mc","stem":"「같은 자리」에서 화분을 복도로 내놓은 뒤 잎 끝이 노래진 일은 무엇을 보여 줄까요?","options":[{"t":"한쪽만 물러서면 다른 쪽이 소중히 여긴 것이 다친다","correct":true},{"t":"처음부터 화분을 돌본 쪽이 잘못이었다","mis":"K3-2-u6-X16"},{"t":"짝의 말이 틀렸다는 것이 밝혀졌다","mis":"K3-2-u6-X16"},{"t":"화분은 어디에 두어도 잘 자란다","mis":"K3-2-u6-X11"}],"explanation":["내가 물러섰어요.","그러자 화분이 시들었어요.","한쪽만 물러서면 안 돼요."],"asset":{"type":"passage","lines":["㉰ “여기가 제일 볕이 잘 드는데.” 나는 그렇게만 말했다.","   짝은 체육복을 안고 돌아섰고, 그날 우리는 더 말하지 않았다.","㉱ 며칠 뒤 화분을 복도로 내놓았더니 얼마 안 가 잎 끝이 노래졌다.","   나는 화분 앞에 쪼그려 앉아 있었다.","   짝이 먼저 말했다. “창가는 어때? 거기도 볕 들잖아.”","   창가에 두니 화분이 들어가고, 사물함 문이 끝까지 열렸다."],"title":"이야기 「같은 자리」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L05_challenge#4','kor',3,2,'u6','L05','g3_2_kor_u6_L05_challenge','lesson_challenge','K3-2-u6-C16',3,'ox','auto','두 인물이 부딪치는 이야기에서는 한쪽이 반드시 잘못한 것이에요.',ARRAY['K3-2-u6-X16']::text[],false,'{"seq":4,"concept":"K3-2-u6-C16","difficulty":3,"kind":"ox","stem":"두 인물이 부딪치는 이야기에서는 한쪽이 반드시 잘못한 것이에요.","answer":"X","reason_options":[{"t":"둘 다 소중히 여기는 것이 있어 물러설 수 없어서 부딪칠 수도 있기 때문에","correct":true},{"t":"부딪쳤다는 것은 누군가 잘못했다는 뜻이기 때문에","mis":"K3-2-u6-X16"}],"mis":"K3-2-u6-X16","explanation":["「같은 자리」를 떠올려요.","둘 다 잘못하지 않았어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L05_challenge#5','kor',3,2,'u6','L05','g3_2_kor_u6_L05_challenge','lesson_challenge','K3-2-u6-C17',3,'error','auto','인물에게 물어볼 질문을 만들었어요. 알맞지 않은 질문을 만든 친구는 누구인가요?',ARRAY['K3-2-u6-X17']::text[],false,'{"seq":5,"concept":"K3-2-u6-C17","difficulty":3,"kind":"error","stem":"인물에게 물어볼 질문을 만들었어요. 알맞지 않은 질문을 만든 친구는 누구인가요?","options":[{"t":"친구 나 — 「화분은 어느 가게에서 샀나요?」","correct":true,"mis_target":"K3-2-u6-X17"},{"t":"친구 가 — 「잎 수를 왜 세고 있었어요?」","mis":"K3-2-u6-X17"},{"t":"친구 다 — 「창가를 먼저 말한 까닭이 무엇이었어요?」","mis":"K3-2-u6-X17"}],"explanation":["답이 이야기 안에 있나요?","가게 이야기는 없어요.","친구 나가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L05_challenge#6','kor',3,2,'u6','L05','g3_2_kor_u6_L05_challenge','lesson_challenge','K3-2-u6-C18',3,'mc','auto','모둠에서 그림 그리기 자리를 두고 친구와 부딪쳤어요. 「같은 자리」에서 배운 대로 한 것은 무엇인가요?',ARRAY['K3-2-u6-X16','K3-2-u6-X18']::text[],false,'{"seq":6,"concept":"K3-2-u6-C18","difficulty":3,"kind":"mc","stem":"모둠에서 그림 그리기 자리를 두고 친구와 부딪쳤어요. 「같은 자리」에서 배운 대로 한 것은 무엇인가요?","options":[{"t":"서로 무엇을 소중히 여기는지 말해 보고 둘 다 지킬 수 있는 길을 찾는다","correct":true},{"t":"누가 먼저 앉았는지 따져 잘못한 쪽을 정한다","mis":"K3-2-u6-X16"},{"t":"불편해도 아무 말 없이 참는다","mis":"K3-2-u6-X18"},{"t":"선생님께 누가 옳은지만 정해 달라고 한다","mis":"K3-2-u6-X16"}],"explanation":["잘잘못을 먼저 가리지 않아요.","덮어 두지도 않아요.","창가 같은 길을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L05_challenge#7','kor',3,2,'u6','L05','g3_2_kor_u6_L05_challenge','lesson_challenge','K3-2-u6-C15',3,'mc','auto','「같은 자리」에서 창가를 먼저 말한 사람과 그 말에서 알 수 있는 것을 바르게 짝지은 것은 무엇인가요?',ARRAY['K3-2-u6-X11','K3-2-u6-X15']::text[],false,'{"seq":7,"concept":"K3-2-u6-C15","difficulty":3,"kind":"mc","stem":"「같은 자리」에서 창가를 먼저 말한 사람과 그 말에서 알 수 있는 것을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"짝 — 화분을 아끼는 내 마음도 함께 생각해 주었다","correct":true},{"t":"나 — 짝의 불편을 몰랐다","mis":"K3-2-u6-X11"},{"t":"짝 — 화분이 싫어 멀리 치우고 싶었다","mis":"K3-2-u6-X15"},{"t":"선생님 — 자리를 정해 주었다","mis":"K3-2-u6-X11"}],"explanation":["“짝이 먼저 말했다.”예요.","창가에도 볕이 들어요.","내 마음도 생각했어요."],"asset":{"type":"passage","lines":["㉰ “여기가 제일 볕이 잘 드는데.” 나는 그렇게만 말했다.","   짝은 체육복을 안고 돌아섰고, 그날 우리는 더 말하지 않았다.","㉱ 며칠 뒤 화분을 복도로 내놓았더니 얼마 안 가 잎 끝이 노래졌다.","   나는 화분 앞에 쪼그려 앉아 있었다.","   짝이 먼저 말했다. “창가는 어때? 거기도 볕 들잖아.”","   창가에 두니 화분이 들어가고, 사물함 문이 끝까지 열렸다."],"title":"이야기 「같은 자리」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L05_challenge#8','kor',3,2,'u6','L05','g3_2_kor_u6_L05_challenge','lesson_challenge','K3-2-u6-C17',4,'mc','auto','“화분 앞에 쪼그려 앉아 있을 때 어떤 마음이었어요?”라는 질문에 인물이 되어 가장 알맞게 답한 것은 무엇인가요?',ARRAY['K3-2-u6-X17','K3-2-u6-X16','K3-2-u6-X15']::text[],false,'{"seq":8,"concept":"K3-2-u6-C17","difficulty":4,"kind":"mc","stem":"“화분 앞에 쪼그려 앉아 있을 때 어떤 마음이었어요?”라는 질문에 인물이 되어 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"“잎이 노래져서 속상했고, 짝도 화분도 다 괜찮을 자리가 없을까 생각했어요.”","correct":true},{"t":"“이 이야기는 몇 쪽짜리예요.”","mis":"K3-2-u6-X17"},{"t":"“짝이 다 잘못했으니 화가 났어요.”","mis":"K3-2-u6-X16"},{"t":"“아무 생각도 없었어요.”","mis":"K3-2-u6-X15"}],"explanation":["인물이 되어 답해요.","쪼그려 앉은 행동을 떠올려요.","마음과 까닭을 말해요."],"asset":{"type":"passage","lines":["㉰ “여기가 제일 볕이 잘 드는데.” 나는 그렇게만 말했다.","   짝은 체육복을 안고 돌아섰고, 그날 우리는 더 말하지 않았다.","㉱ 며칠 뒤 화분을 복도로 내놓았더니 얼마 안 가 잎 끝이 노래졌다.","   나는 화분 앞에 쪼그려 앉아 있었다.","   짝이 먼저 말했다. “창가는 어때? 거기도 볕 들잖아.”","   창가에 두니 화분이 들어가고, 사물함 문이 끝까지 열렸다."],"title":"이야기 「같은 자리」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L05_challenge#9','kor',3,2,'u6','L05','g3_2_kor_u6_L05_challenge','lesson_challenge','K3-2-u6-C16',4,'essay','teacher','「같은 자리」의 두 사람이 각각 무엇을 소중히 여겼는지 말과 행동을 근거로 쓰고, 「누가 옳았을까?」라는 물음에 어떻게 답할지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u6-C16","difficulty":4,"kind":"essay","stem":"「같은 자리」의 두 사람이 각각 무엇을 소중히 여겼는지 말과 행동을 근거로 쓰고, 「누가 옳았을까?」라는 물음에 어떻게 답할지 쓰세요.","answer_guide":{"answer":"예: 나는 잎 수를 다 세고 “여기가 제일 볕이 잘 드는데.”라고 말한 것으로 보아 화분이 잘 자라는 것을 소중히 여겼다. 짝은 팔꿈치를 부딪히고 “매번 이래.”라고 한 것으로 보아 함께 쓰는 사물함을 불편 없이 쓰는 것을 소중히 여겼다. 둘 다 소중히 여기는 것이 있었으므로 한쪽만 옳다고 고를 물음이 아니다.","scoring_points":["나의 소중한 것을 말·행동 근거와 함께 썼는가","짝의 소중한 것을 말·행동 근거와 함께 썼는가","한쪽을 고를 물음이 아니라고 썼는가"]},"explanation":["말과 행동이 근거예요.","둘 다 써요.","한쪽을 고르지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L05_challenge#10','kor',3,2,'u6','L05','g3_2_kor_u6_L05_challenge','lesson_challenge','K3-2-u6-C18',4,'essay','teacher','친구와 부딪친 일을 하나 떠올려(지어내도 돼요) 서로 무엇을 소중히 여겼는지 쓰고, 「같은 자리」의 창가처럼 둘 다 지킬 수 있는 길을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u6-C18","difficulty":4,"kind":"essay","stem":"친구와 부딪친 일을 하나 떠올려(지어내도 돼요) 서로 무엇을 소중히 여겼는지 쓰고, 「같은 자리」의 창가처럼 둘 다 지킬 수 있는 길을 쓰세요.","answer_guide":{"answer":"예: 모둠 발표 순서를 두고 나는 빨리 끝내는 것을, 친구는 연습할 시간을 소중히 여겨 부딪쳤다. 잘잘못을 가리기보다 서로 소중히 여긴 것을 말해 보니, 친구가 연습할 수 있게 우리 모둠이 두 번째로 하기로 정할 수 있었다.","scoring_points":["부딪친 일을 썼는가","서로 소중히 여긴 것을 썼는가","둘 다 지킬 수 있는 길을 썼는가"]},"explanation":["잘잘못보다","소중히 여긴 것을 먼저 봐요.","둘 다 지킬 길을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L07_basic#1','kor',3,2,'u6','L07','g3_2_kor_u6_L07_basic','lesson_basic','K3-2-u6-C19',1,'mc','auto','내 생각을 나타낸 문장은 무엇인가요?',ARRAY['K3-2-u6-X19']::text[],false,'{"seq":1,"concept":"K3-2-u6-C19","difficulty":1,"kind":"mc","stem":"내 생각을 나타낸 문장은 무엇인가요?","options":[{"t":"자리를 함께 정하면 좋겠다","correct":true},{"t":"화분에 잎이 여섯 장 있다","mis":"K3-2-u6-X19"},{"t":"짝이 체육복을 꺼냈다","mis":"K3-2-u6-X19"},{"t":"화분이 사물함 문에 걸렸다","mis":"K3-2-u6-X19"}],"explanation":["본 대로 적은 문장이 있어요.","“좋겠다”가 붙은 문장도 있어요.","그것이 내 생각이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L07_basic#2','kor',3,2,'u6','L07','g3_2_kor_u6_L07_basic','lesson_basic','K3-2-u6-C20',1,'mc','auto','의견을 제시하는 글의 세 부분을 바르게 모은 것은 무엇인가요?',ARRAY['K3-2-u6-X21','K3-2-u6-X20']::text[],false,'{"seq":2,"concept":"K3-2-u6-C20","difficulty":1,"kind":"mc","stem":"의견을 제시하는 글의 세 부분을 바르게 모은 것은 무엇인가요?","options":[{"t":"문제 상황 · 의견 · 이유","correct":true},{"t":"제목 · 줄거리 · 느낌","mis":"K3-2-u6-X21"},{"t":"의견 · 의견 · 의견","mis":"K3-2-u6-X20"},{"t":"문제 상황 · 점수 · 이름","mis":"K3-2-u6-X21"}],"explanation":["무엇이 불편한지 써요.","어떻게 하자는지 써요.","왜 그런지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L07_basic#3','kor',3,2,'u6','L07','g3_2_kor_u6_L07_basic','lesson_basic','K3-2-u6-C20',1,'ox','auto','의견을 제시하는 글에는 의견과 그렇게 생각한 이유가 함께 들어가야 해요.',ARRAY['K3-2-u6-X20']::text[],false,'{"seq":3,"concept":"K3-2-u6-C20","difficulty":1,"kind":"ox","stem":"의견을 제시하는 글에는 의견과 그렇게 생각한 이유가 함께 들어가야 해요.","answer":"O","reason_options":[{"t":"“이렇게 하자.”만 있으면 읽는 사람이 “왜?” 하고 되묻게 되기 때문에","correct":true},{"t":"의견만 크게 쓰면 읽는 사람이 다 알아듣기 때문에","mis":"K3-2-u6-X20"}],"mis":"K3-2-u6-X20","explanation":["이유는 의견을 받쳐 주는 기둥이에요.","함께 가야 해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L07_basic#4','kor',3,2,'u6','L07','g3_2_kor_u6_L07_basic','lesson_basic','K3-2-u6-C21',1,'mc','auto','글 ①에서 글쓴이의 의견은 무엇인가요?',ARRAY['K3-2-u6-X21','K3-2-u6-X19']::text[],false,'{"seq":4,"concept":"K3-2-u6-C21","difficulty":1,"kind":"mc","stem":"글 ①에서 글쓴이의 의견은 무엇인가요?","options":[{"t":"학기 초에 물건 자리를 다 함께 정하자","correct":true},{"t":"물건 자리 때문에 불편한 일이 자주 생긴다","mis":"K3-2-u6-X21"},{"t":"한 사람이 정하면 그 사람 눈에만 편하다","mis":"K3-2-u6-X21"},{"t":"화분 자리로 부딪치는 이야기를 읽었다","mis":"K3-2-u6-X19"}],"explanation":["“좋겠다”가 붙은 줄을 찾아요.","3번 줄이에요.","어떻게 하자는 말이 의견이에요."],"asset":{"type":"passage","lines":["1 화분 자리를 두고 두 사람이 부딪치는 이야기를 읽었다.","2 우리 교실에도 물건이 놓인 자리 때문에 불편한 일이 자주 생긴다.","3 그래서 학기 초에 물건 자리를 다 함께 정하면 좋겠다.","4 왜냐하면 한 사람이 정하면 그 사람 눈에만 편한 자리가 되기 때문이다.","5 또 함께 정하면 불편한 곳을 미리 말할 수 있기 때문이다."],"title":"글 ① 「자리를 함께 정하자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L07_basic#5','kor',3,2,'u6','L07','g3_2_kor_u6_L07_basic','lesson_basic','K3-2-u6-C21',2,'match','auto','글 ①의 줄과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u6-C21","difficulty":2,"kind":"match","stem":"글 ①의 줄과 하는 일을 알맞게 이으세요.","pairs":[{"l":"2번 줄","r":"문제 상황"},{"l":"3번 줄","r":"의견"},{"l":"4번 줄","r":"이유"}],"mis":"K3-2-u6-X21","explanation":["무엇이 불편한지 적은 줄","어떻게 하자는 줄","왜 그런지 적은 줄이에요."],"asset":{"type":"passage","lines":["1 화분 자리를 두고 두 사람이 부딪치는 이야기를 읽었다.","2 우리 교실에도 물건이 놓인 자리 때문에 불편한 일이 자주 생긴다.","3 그래서 학기 초에 물건 자리를 다 함께 정하면 좋겠다.","4 왜냐하면 한 사람이 정하면 그 사람 눈에만 편한 자리가 되기 때문이다.","5 또 함께 정하면 불편한 곳을 미리 말할 수 있기 때문이다."],"title":"글 ① 「자리를 함께 정하자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L07_basic#6','kor',3,2,'u6','L07','g3_2_kor_u6_L07_basic','lesson_basic','K3-2-u6-C22',2,'mc','auto','글 ②의 의견을 잘 받쳐 주는 이유는 무엇인가요?',ARRAY['K3-2-u6-X22','K3-2-u6-X23']::text[],false,'{"seq":6,"concept":"K3-2-u6-C22","difficulty":2,"kind":"mc","stem":"글 ②의 의견을 잘 받쳐 주는 이유는 무엇인가요?","options":[{"t":"한 사람이 다 맡으면 시간이 오래 걸리고 힘들다","correct":true},{"t":"우리 반에 책이 많이 있다","mis":"K3-2-u6-X22"},{"t":"내가 정리를 제일 잘한다","mis":"K3-2-u6-X23"},{"t":"학급 문고 책장이 갈색이다","mis":"K3-2-u6-X22"}],"explanation":["“돌아가며 정리하자”에 대어 봐요.","이어지는 것만 받침이 돼요.","나만 잘한다는 것은 받침이 아니에요."],"asset":{"type":"passage","lines":["1 학급 문고에 책이 뒤섞여 있어서 찾는 데 오래 걸린다.","2 나는 요일을 나누어 모둠이 돌아가며 정리하면 좋겠다고 생각한다.","3 첫째, 한 사람이 다 맡으면 시간이 오래 걸리고 힘들기 때문이다.","4 둘째, 자기가 정리한 칸은 어디에 무엇이 있는지 잘 알게 되기 때문이다."],"title":"글 ② 「학급 문고를 우리가 정리하자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L07_basic#7','kor',3,2,'u6','L07','g3_2_kor_u6_L07_basic','lesson_basic','K3-2-u6-C24',2,'mc','auto','“학급 문고 책이 뒤섞여 찾기 어렵다”는 문제를 두고 낼 수 있는 의견은 무엇인가요?',ARRAY['K3-2-u6-X24','K3-2-u6-X31']::text[],false,'{"seq":7,"concept":"K3-2-u6-C24","difficulty":2,"kind":"mc","stem":"“학급 문고 책이 뒤섞여 찾기 어렵다”는 문제를 두고 낼 수 있는 의견은 무엇인가요?","options":[{"t":"칸마다 이름표를 붙여 제자리에 꽂자","correct":true},{"t":"책을 읽지 말자","mis":"K3-2-u6-X24"},{"t":"학급 문고를 없애자","mis":"K3-2-u6-X24"},{"t":"책이 뒤섞이는 것은 어쩔 수 없다","mis":"K3-2-u6-X31"}],"explanation":["문제를 풀어야 해요.","책을 안 읽는 건 푸는 게 아니에요.","이름표도 하나의 길이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L07_basic#8','kor',3,2,'u6','L07','g3_2_kor_u6_L07_basic','lesson_basic','K3-2-u6-C25',2,'mc','auto','의견을 제시하는 글을 쓸 때 가장 먼저 할 일은 무엇인가요?',ARRAY['K3-2-u6-X26','K3-2-u6-X25']::text[],false,'{"seq":8,"concept":"K3-2-u6-C25","difficulty":2,"kind":"mc","stem":"의견을 제시하는 글을 쓸 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"무엇이 불편한지, 문제 상황을 먼저 찾는다","correct":true},{"t":"고운 말로 길게 쓰는 일부터 생각한다","mis":"K3-2-u6-X26"},{"t":"반 친구들이 좋아할 말부터 생각한다","mis":"K3-2-u6-X26"},{"t":"이유를 먼저 다섯 개 적는다","mis":"K3-2-u6-X25"}],"explanation":["고칠 일을 모르면","무엇에 대한 의견인지 몰라요.","문제 상황부터예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L07_basic#9','kor',3,2,'u6','L07','g3_2_kor_u6_L07_basic','lesson_basic','K3-2-u6-C19',2,'blank','auto','“어떤 일이나 대상에 대한 생각”을 (　)이라고 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u6-X19','K3-2-u6-X06']::text[],false,'{"seq":9,"concept":"K3-2-u6-C19","difficulty":2,"kind":"blank","stem":"“어떤 일이나 대상에 대한 생각”을 (　)이라고 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"의견","correct":true},{"t":"사실","mis":"K3-2-u6-X19"},{"t":"줄거리","mis":"K3-2-u6-X06"},{"t":"제목","mis":"K3-2-u6-X19"}],"explanation":["있었던 일은 사실이에요.","그것을 두고 한 생각이에요.","‘의견’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L07_basic#10','kor',3,2,'u6','L07','g3_2_kor_u6_L07_basic','lesson_basic','K3-2-u6-C23',3,'error','auto','글 ②의 의견과 이유를 재 보았어요. 잘못 잰 친구는 누구인가요?',ARRAY['K3-2-u6-X25','K3-2-u6-X23','K3-2-u6-X22']::text[],false,'{"seq":10,"concept":"K3-2-u6-C23","difficulty":3,"kind":"error","stem":"글 ②의 의견과 이유를 재 보았어요. 잘못 잰 친구는 누구인가요?","options":[{"t":"친구 다 — 「이유가 둘이지만 둘 다 같은 말이야.」","correct":true,"mis_target":"K3-2-u6-X25"},{"t":"친구 가 — 「문제 상황에 어울리는 의견이야.」","mis":"K3-2-u6-X23"},{"t":"친구 나 — 「이유 둘이 의견을 받쳐 줘.」","mis":"K3-2-u6-X22"}],"explanation":["첫째는 시간과 힘이에요.","둘째는 어디에 무엇이 있는지 아는 거예요.","겹치지 않아요. 친구 다가 잘못 쟀어요."],"asset":{"type":"passage","lines":["1 학급 문고에 책이 뒤섞여 있어서 찾는 데 오래 걸린다.","2 나는 요일을 나누어 모둠이 돌아가며 정리하면 좋겠다고 생각한다.","3 첫째, 한 사람이 다 맡으면 시간이 오래 걸리고 힘들기 때문이다.","4 둘째, 자기가 정리한 칸은 어디에 무엇이 있는지 잘 알게 되기 때문이다."],"title":"글 ② 「학급 문고를 우리가 정리하자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L07_challenge#1','kor',3,2,'u6','L07','g3_2_kor_u6_L07_challenge','lesson_challenge','K3-2-u6-C20',2,'sa','auto','의견을 제시하는 글의 세 부분은 문제 상황, 의견, 그리고 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u6-C20","difficulty":2,"kind":"sa","stem":"의견을 제시하는 글의 세 부분은 문제 상황, 의견, 그리고 무엇인가요? 두 글자로 쓰세요.","answer":["이유"],"explanation":["의견을 받쳐 줘요.","“왜냐하면”으로 시작해요.","‘이유’예요."],"mis":"K3-2-u6-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L07_challenge#2','kor',3,2,'u6','L07','g3_2_kor_u6_L07_challenge','lesson_challenge','K3-2-u6-C22',2,'mc','auto','글 ①의 의견을 받쳐 주는 이유로 알맞지 않은 것은 무엇인가요?',ARRAY['K3-2-u6-X22']::text[],false,'{"seq":2,"concept":"K3-2-u6-C22","difficulty":2,"kind":"mc","stem":"글 ①의 의견을 받쳐 주는 이유로 알맞지 않은 것은 무엇인가요?","options":[{"t":"우리 교실 화분에는 잎이 여섯 장 있기 때문이다","correct":true},{"t":"한 사람이 정하면 그 사람 눈에만 편하기 때문이다","mis":"K3-2-u6-X22"},{"t":"함께 정하면 불편한 곳을 미리 말할 수 있기 때문이다","mis":"K3-2-u6-X22"},{"t":"모두가 정한 자리는 서로 지키기 쉽기 때문이다","mis":"K3-2-u6-X22"}],"explanation":["“다 함께 정하자”에 대어 봐요.","잎 수는 자리 정하기와 상관없어요.","그것이 답이에요."],"asset":{"type":"passage","lines":["1 화분 자리를 두고 두 사람이 부딪치는 이야기를 읽었다.","2 우리 교실에도 물건이 놓인 자리 때문에 불편한 일이 자주 생긴다.","3 그래서 학기 초에 물건 자리를 다 함께 정하면 좋겠다.","4 왜냐하면 한 사람이 정하면 그 사람 눈에만 편한 자리가 되기 때문이다.","5 또 함께 정하면 불편한 곳을 미리 말할 수 있기 때문이다."],"title":"글 ① 「자리를 함께 정하자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L07_challenge#3','kor',3,2,'u6','L07','g3_2_kor_u6_L07_challenge','lesson_challenge','K3-2-u6-C24',3,'mc','auto','학급 문고 문제에 두 친구가 다른 의견을 냈어요. 가는 「모둠이 돌아가며 정리하자」, 나는 「칸마다 이름표를 붙이자」예요. 어떻게 보면 될까요?',ARRAY['K3-2-u6-X24']::text[],false,'{"seq":3,"concept":"K3-2-u6-C24","difficulty":3,"kind":"mc","stem":"학급 문고 문제에 두 친구가 다른 의견을 냈어요. 가는 「모둠이 돌아가며 정리하자」, 나는 「칸마다 이름표를 붙이자」예요. 어떻게 보면 될까요?","options":[{"t":"의견이 달라도 이유가 받쳐 주면 둘 다 낼 수 있다","correct":true},{"t":"먼저 나온 가의 의견만 맞다","mis":"K3-2-u6-X24"},{"t":"둘 다 안 되고 정해진 답이 따로 있다","mis":"K3-2-u6-X24"},{"t":"의견이 다르면 둘 다 쓸 수 없다","mis":"K3-2-u6-X24"}],"explanation":["한 문제에 길이 여럿이에요.","어느 의견인지로 재지 않아요.","이유가 받쳐 주는지로 재요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L07_challenge#4','kor',3,2,'u6','L07','g3_2_kor_u6_L07_challenge','lesson_challenge','K3-2-u6-C23',3,'ox','auto','이유를 여러 가지 쓸 때는 같은 이유를 말만 바꾸어 되풀이해도 돼요.',ARRAY['K3-2-u6-X25']::text[],false,'{"seq":4,"concept":"K3-2-u6-C23","difficulty":3,"kind":"ox","stem":"이유를 여러 가지 쓸 때는 같은 이유를 말만 바꾸어 되풀이해도 돼요.","answer":"X","reason_options":[{"t":"이유가 겹치면 여러 가지를 쓴 것이 아니라서 의견을 더 받쳐 주지 못하기 때문에","correct":true},{"t":"이유는 개수가 많을수록 좋은 글이기 때문에","mis":"K3-2-u6-X25"}],"mis":"K3-2-u6-X25","explanation":["겹치지 않아야 해요.","말만 바꾸면 하나예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L07_challenge#5','kor',3,2,'u6','L07','g3_2_kor_u6_L07_challenge','lesson_challenge','K3-2-u6-C22',3,'error','auto','글 ②에 이유를 하나 더 붙이려고 해요. 의견을 받쳐 주지 못하는 이유를 고른 친구는 누구인가요?',ARRAY['K3-2-u6-X23','K3-2-u6-X22']::text[],false,'{"seq":5,"concept":"K3-2-u6-C22","difficulty":3,"kind":"error","stem":"글 ②에 이유를 하나 더 붙이려고 해요. 의견을 받쳐 주지 못하는 이유를 고른 친구는 누구인가요?","options":[{"t":"친구 가 — 「내가 우리 반에서 정리를 제일 잘하기 때문이다.」","correct":true,"mis_target":"K3-2-u6-X23"},{"t":"친구 나 — 「모두가 책을 빨리 찾게 되기 때문이다.」","mis":"K3-2-u6-X22"},{"t":"친구 다 — 「책을 소중히 다루는 마음이 생기기 때문이다.」","mis":"K3-2-u6-X22"}],"explanation":["나만 잘한다는 것은 받침이 아니에요.","의견대로 하면 좋아질 일이어야 해요.","친구 가가 잘못 골랐어요."],"asset":{"type":"passage","lines":["1 학급 문고에 책이 뒤섞여 있어서 찾는 데 오래 걸린다.","2 나는 요일을 나누어 모둠이 돌아가며 정리하면 좋겠다고 생각한다.","3 첫째, 한 사람이 다 맡으면 시간이 오래 걸리고 힘들기 때문이다.","4 둘째, 자기가 정리한 칸은 어디에 무엇이 있는지 잘 알게 되기 때문이다."],"title":"글 ② 「학급 문고를 우리가 정리하자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L07_challenge#6','kor',3,2,'u6','L07','g3_2_kor_u6_L07_challenge','lesson_challenge','K3-2-u6-C19',3,'mc','auto','사실과 의견을 바르게 가른 것은 무엇인가요?',ARRAY['K3-2-u6-X19']::text[],false,'{"seq":6,"concept":"K3-2-u6-C19","difficulty":3,"kind":"mc","stem":"사실과 의견을 바르게 가른 것은 무엇인가요?","options":[{"t":"“책이 뒤섞여 있다”는 사실, “칸마다 이름표를 붙이자”는 의견","correct":true},{"t":"두 문장 모두 의견","mis":"K3-2-u6-X19"},{"t":"두 문장 모두 사실","mis":"K3-2-u6-X19"},{"t":"“책이 뒤섞여 있다”는 의견, “이름표를 붙이자”는 사실","mis":"K3-2-u6-X19"}],"explanation":["본 대로 적은 것은 사실이에요.","“하자”는 생각이에요.","하나씩 갈라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L07_challenge#7','kor',3,2,'u6','L07','g3_2_kor_u6_L07_challenge','lesson_challenge','K3-2-u6-C25',3,'mc','auto','의견 글을 쓰려는 친구가 “고운 말로 길게 써야지.”라고만 생각해요. 일러 줄 말로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X26','K3-2-u6-X20']::text[],false,'{"seq":7,"concept":"K3-2-u6-C25","difficulty":3,"kind":"mc","stem":"의견 글을 쓰려는 친구가 “고운 말로 길게 써야지.”라고만 생각해요. 일러 줄 말로 알맞은 것은 무엇인가요?","options":[{"t":"“무엇이 불편한지부터 찾아야 무엇에 대한 의견인지 알 수 있어.”","correct":true},{"t":"“반 친구들이 좋아할 말을 먼저 골라.”","mis":"K3-2-u6-X26"},{"t":"“이유는 없어도 되니 의견만 크게 써.”","mis":"K3-2-u6-X20"},{"t":"“글은 길수록 좋은 글이야.”","mis":"K3-2-u6-X26"}],"explanation":["말보다 먼저 할 일이 있어요.","무엇이 불편한지 찾아요.","문제 상황부터예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L07_challenge#8','kor',3,2,'u6','L07','g3_2_kor_u6_L07_challenge','lesson_challenge','K3-2-u6-C23',4,'mc','auto','의견과 이유를 재는 네 가지에 들지 않는 것은 무엇인가요?',ARRAY['K3-2-u6-X23','K3-2-u6-X25']::text[],false,'{"seq":8,"concept":"K3-2-u6-C23","difficulty":4,"kind":"mc","stem":"의견과 이유를 재는 네 가지에 들지 않는 것은 무엇인가요?","options":[{"t":"글이 다른 친구 글보다 긴가","correct":true},{"t":"문제 상황에 어울리는 의견인가","mis":"K3-2-u6-X23"},{"t":"의견을 뒷받침하는 이유인가","mis":"K3-2-u6-X23"},{"t":"이유가 겹치지 않고 여러 가지인가","mis":"K3-2-u6-X25"}],"explanation":["어울림·뒷받침·여러 가지·도움이에요.","길이는 들지 않아요.","그것이 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L07_challenge#9','kor',3,2,'u6','L07','g3_2_kor_u6_L07_challenge','lesson_challenge','K3-2-u6-C24',4,'essay','teacher','같은 문제를 두고 친구가 나와 다른 의견을 냈을 때 그 의견을 어떻게 재야 하는지 쓰고, 학급 문고 문제에서 글 ②와 다른 의견을 하나 써서 이유를 붙이세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u6-C24","difficulty":4,"kind":"essay","stem":"같은 문제를 두고 친구가 나와 다른 의견을 냈을 때 그 의견을 어떻게 재야 하는지 쓰고, 학급 문고 문제에서 글 ②와 다른 의견을 하나 써서 이유를 붙이세요.","answer_guide":{"answer":"예: 내 의견과 다르다고 틀린 것이 아니라 이유가 의견을 받쳐 주는지로 재야 한다. 다른 의견: 빌린 책을 적는 종이를 책장 옆에 두자. 왜냐하면 누가 어떤 책을 가져갔는지 알 수 있어 책이 제자리로 돌아오기 쉽기 때문이다.","scoring_points":["이유가 받쳐 주는지로 잰다고 썼는가","글 ②와 다른 의견을 썼는가","의견을 받쳐 주는 이유를 붙였는가"]},"explanation":["다르다고 틀린 게 아니에요.","이유로 재요.","다른 길을 하나 더 내 봐요."],"asset":{"type":"passage","lines":["1 학급 문고에 책이 뒤섞여 있어서 찾는 데 오래 걸린다.","2 나는 요일을 나누어 모둠이 돌아가며 정리하면 좋겠다고 생각한다.","3 첫째, 한 사람이 다 맡으면 시간이 오래 걸리고 힘들기 때문이다.","4 둘째, 자기가 정리한 칸은 어디에 무엇이 있는지 잘 알게 되기 때문이다."],"title":"글 ② 「학급 문고를 우리가 정리하자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L07_challenge#10','kor',3,2,'u6','L07','g3_2_kor_u6_L07_challenge','lesson_challenge','K3-2-u6-C20',4,'essay','teacher','글 ①을 세 부분으로 나누어 각각 몇 번 줄인지 쓰고, 의견만 있고 이유가 없으면 어떤 일이 생기는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u6-C20","difficulty":4,"kind":"essay","stem":"글 ①을 세 부분으로 나누어 각각 몇 번 줄인지 쓰고, 의견만 있고 이유가 없으면 어떤 일이 생기는지 쓰세요.","answer_guide":{"answer":"예: 문제 상황은 2번 줄, 의견은 3번 줄, 이유는 4번과 5번 줄이다. 이유가 없으면 읽는 사람이 “왜?” 하고 되묻게 되고 의견에 고개를 끄덕이기 어렵다. 이유는 의견을 받쳐 주는 기둥이다.","scoring_points":["문제 상황 줄을 바르게 썼는가","의견과 이유 줄을 바르게 썼는가","이유가 없을 때 생길 일을 썼는가"]},"explanation":["세 부분으로 나눠요.","줄 번호를 짚어요.","이유는 기둥이에요."],"asset":{"type":"passage","lines":["1 화분 자리를 두고 두 사람이 부딪치는 이야기를 읽었다.","2 우리 교실에도 물건이 놓인 자리 때문에 불편한 일이 자주 생긴다.","3 그래서 학기 초에 물건 자리를 다 함께 정하면 좋겠다.","4 왜냐하면 한 사람이 정하면 그 사람 눈에만 편한 자리가 되기 때문이다.","5 또 함께 정하면 불편한 곳을 미리 말할 수 있기 때문이다."],"title":"글 ① 「자리를 함께 정하자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L09_basic#1','kor',3,2,'u6','L09','g3_2_kor_u6_L09_basic','lesson_basic','K3-2-u6-C26',1,'mc','auto','글을 고쳐 쓸 때 살펴볼 것은 무엇인가요?',ARRAY['K3-2-u6-X27']::text[],false,'{"seq":1,"concept":"K3-2-u6-C26","difficulty":1,"kind":"mc","stem":"글을 고쳐 쓸 때 살펴볼 것은 무엇인가요?","options":[{"t":"이유가 의견을 받쳐 주는가","correct":true},{"t":"글이 남보다 긴가","mis":"K3-2-u6-X27"},{"t":"글씨가 예쁜가","mis":"K3-2-u6-X27"},{"t":"공책이 깨끗한가","mis":"K3-2-u6-X27"}],"explanation":["길이를 보는 게 아니에요.","글씨 모양도 아니에요.","이유와 의견을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L09_basic#2','kor',3,2,'u6','L09','g3_2_kor_u6_L09_basic','lesson_basic','K3-2-u6-C27',1,'mc','auto','「교실 창문을 자주 열자」에서 고쳐 써야 할 줄은 몇 번인가요?',ARRAY['K3-2-u6-X22']::text[],false,'{"seq":2,"concept":"K3-2-u6-C27","difficulty":1,"kind":"mc","stem":"「교실 창문을 자주 열자」에서 고쳐 써야 할 줄은 몇 번인가요?","options":[{"t":"4번 줄","correct":true},{"t":"1번 줄","mis":"K3-2-u6-X22"},{"t":"3번 줄","mis":"K3-2-u6-X22"},{"t":"5번 줄","mis":"K3-2-u6-X22"}],"explanation":["지워도 의견이 흔들리지 않는 줄이에요.","창문을 잘 연다는 것은 받침이 아니에요.","4번 줄이에요."],"asset":{"type":"passage","lines":["1 교실 공기가 답답할 때가 많다.","2 그래서 쉬는 시간마다 창문을 열면 좋겠다.","3 첫째, 공기가 바뀌면 머리가 맑아져 다음 시간에 집중하기 쉽기 때문이다.","4 둘째, 내가 우리 반에서 창문을 제일 잘 열기 때문이다.","5 쉬는 시간마다 창문을 열어 맑은 공기로 바꾸었으면 좋겠다."],"title":"글 「교실 창문을 자주 열자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L09_basic#3','kor',3,2,'u6','L09','g3_2_kor_u6_L09_basic','lesson_basic','K3-2-u6-C28',1,'ox','auto','고칠 곳이 있는 글은 못 쓴 글이에요.',ARRAY['K3-2-u6-X29']::text[],false,'{"seq":3,"concept":"K3-2-u6-C28","difficulty":1,"kind":"ox","stem":"고칠 곳이 있는 글은 못 쓴 글이에요.","answer":"X","reason_options":[{"t":"고칠 곳이 보였다는 것은 내 글을 다시 읽었다는 뜻이고, 글은 고쳐 가며 좋아지기 때문에","correct":true},{"t":"잘 쓴 글은 처음부터 고칠 곳이 없기 때문에","mis":"K3-2-u6-X29"}],"mis":"K3-2-u6-X29","explanation":["고칠 곳이 보이면 다시 읽은 거예요.","글은 고쳐 가며 좋아져요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L09_basic#4','kor',3,2,'u6','L09','g3_2_kor_u6_L09_basic','lesson_basic','K3-2-u6-C29',1,'mc','auto','친구 글을 읽고 말해 줄 때 먼저 할 일은 무엇인가요?',ARRAY['K3-2-u6-X30']::text[],false,'{"seq":4,"concept":"K3-2-u6-C29","difficulty":1,"kind":"mc","stem":"친구 글을 읽고 말해 줄 때 먼저 할 일은 무엇인가요?","options":[{"t":"잘된 곳을 한 가지 말한다","correct":true},{"t":"틀린 곳을 모두 찾아 말한다","mis":"K3-2-u6-X30"},{"t":"점수를 매겨 알려 준다","mis":"K3-2-u6-X30"},{"t":"아무 말도 하지 않는다","mis":"K3-2-u6-X30"}],"explanation":["흠 찾기가 아니에요.","점수를 매기는 자리도 아니에요.","잘된 곳부터예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L09_basic#5','kor',3,2,'u6','L09','g3_2_kor_u6_L09_basic','lesson_basic','K3-2-u6-C27',2,'mc','auto','4번 줄을 어떻게 고치면 좋을까요?',ARRAY['K3-2-u6-X28','K3-2-u6-X25']::text[],false,'{"seq":5,"concept":"K3-2-u6-C27","difficulty":2,"kind":"mc","stem":"4번 줄을 어떻게 고치면 좋을까요?","options":[{"t":"의견을 받쳐 주는 다른 이유로 바꾼다","correct":true},{"t":"그 줄을 지우고 글을 짧게 끝낸다","mis":"K3-2-u6-X28"},{"t":"그대로 두고 이유를 더 붙인다","mis":"K3-2-u6-X28"},{"t":"3번 줄과 같은 말로 바꾼다","mis":"K3-2-u6-X25"}],"explanation":["지우기만 하면 이유가 하나예요.","그대로 두면 안 돼요.","받쳐 주는 이유로 채워요."],"asset":{"type":"passage","lines":["1 교실 공기가 답답할 때가 많다.","2 그래서 쉬는 시간마다 창문을 열면 좋겠다.","3 첫째, 공기가 바뀌면 머리가 맑아져 다음 시간에 집중하기 쉽기 때문이다.","4 둘째, 내가 우리 반에서 창문을 제일 잘 열기 때문이다.","5 쉬는 시간마다 창문을 열어 맑은 공기로 바꾸었으면 좋겠다."],"title":"글 「교실 창문을 자주 열자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L09_basic#6','kor',3,2,'u6','L09','g3_2_kor_u6_L09_basic','lesson_basic','K3-2-u6-C27',2,'mc','auto','4번 줄 대신 넣을 이유로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X22','K3-2-u6-X23','K3-2-u6-X25']::text[],false,'{"seq":6,"concept":"K3-2-u6-C27","difficulty":2,"kind":"mc","stem":"4번 줄 대신 넣을 이유로 알맞은 것은 무엇인가요?","options":[{"t":"둘째, 맑은 공기를 마시면 졸음이 덜 오기 때문이다","correct":true},{"t":"둘째, 창문이 교실에 네 개 있기 때문이다","mis":"K3-2-u6-X22"},{"t":"둘째, 내가 창문 열기를 좋아하기 때문이다","mis":"K3-2-u6-X23"},{"t":"둘째, 공기가 바뀌면 머리가 맑아지기 때문이다","mis":"K3-2-u6-X25"}],"explanation":["창문을 열자는 의견과 이어져야 해요.","3번 줄과 겹치면 안 돼요.","졸음이 덜 오는 것이 알맞아요."],"asset":{"type":"passage","lines":["1 교실 공기가 답답할 때가 많다.","2 그래서 쉬는 시간마다 창문을 열면 좋겠다.","3 첫째, 공기가 바뀌면 머리가 맑아져 다음 시간에 집중하기 쉽기 때문이다.","4 둘째, 내가 우리 반에서 창문을 제일 잘 열기 때문이다.","5 쉬는 시간마다 창문을 열어 맑은 공기로 바꾸었으면 좋겠다."],"title":"글 「교실 창문을 자주 열자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L09_basic#7','kor',3,2,'u6','L09','g3_2_kor_u6_L09_basic','lesson_basic','K3-2-u6-C28',2,'mc','auto','글을 쓴 뒤에 고쳐 쓰면 무엇이 좋을까요?',ARRAY['K3-2-u6-X29','K3-2-u6-X30','K3-2-u6-X27']::text[],false,'{"seq":7,"concept":"K3-2-u6-C28","difficulty":2,"kind":"mc","stem":"글을 쓴 뒤에 고쳐 쓰면 무엇이 좋을까요?","options":[{"t":"내 생각이 읽는 사람에게 더 잘 전해진다","correct":true},{"t":"고칠 곳이 없어야 잘 쓴 글이 되기 때문에","mis":"K3-2-u6-X29"},{"t":"친구 글의 흠을 찾아 알려 줄 수 있어서","mis":"K3-2-u6-X30"},{"t":"글이 더 길어져서","mis":"K3-2-u6-X27"}],"explanation":["흠을 없애는 일이 아니에요.","전하려던 것을 더 잘 전해요.","그것이 좋은 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L09_basic#8','kor',3,2,'u6','L09','g3_2_kor_u6_L09_basic','lesson_basic','K3-2-u6-C26',2,'mc','auto','뜻이 통하는지와 함께 고쳐 쓸 때 살펴볼 것으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X27']::text[],false,'{"seq":8,"concept":"K3-2-u6-C26","difficulty":2,"kind":"mc","stem":"뜻이 통하는지와 함께 고쳐 쓸 때 살펴볼 것으로 알맞은 것은 무엇인가요?","options":[{"t":"띄어쓰기와 맞춤법이 맞는가","correct":true},{"t":"글이 남보다 긴가","mis":"K3-2-u6-X27"},{"t":"글씨가 예쁜가","mis":"K3-2-u6-X27"},{"t":"어려운 낱말을 많이 썼는가","mis":"K3-2-u6-X27"}],"explanation":["읽기 쉬운지도 고쳐 쓸 거리예요.","띄어쓰기와 맞춤법을 봐요.","길이나 글씨 모양이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L09_basic#9','kor',3,2,'u6','L09','g3_2_kor_u6_L09_basic','lesson_basic','K3-2-u6-C29',2,'blank','auto','친구 글에 말해 줄 때 “고칠 곳은 (　) 말한다.” 빈칸에 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X30']::text[],false,'{"seq":9,"concept":"K3-2-u6-C29","difficulty":2,"kind":"blank","stem":"친구 글에 말해 줄 때 “고칠 곳은 (　) 말한다.” 빈칸에 알맞은 것은 무엇인가요?","options":[{"t":"어디인지 짚어","correct":true},{"t":"모두 찾아 한꺼번에","mis":"K3-2-u6-X30"},{"t":"점수로 바꾸어","mis":"K3-2-u6-X30"},{"t":"말하지 않고 넘어가며","mis":"K3-2-u6-X30"}],"explanation":["잘된 곳을 먼저 말해요.","고칠 곳은 콕 짚어요.","까닭도 짧게 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L09_basic#10','kor',3,2,'u6','L09','g3_2_kor_u6_L09_basic','lesson_basic','K3-2-u6-C28',3,'error','auto','고쳐 쓰기를 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u6-X29']::text[],false,'{"seq":10,"concept":"K3-2-u6-C28","difficulty":3,"kind":"error","stem":"고쳐 쓰기를 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「내 글에 밑줄이 많으니 나는 글을 못 쓰는 거야.」","correct":true,"mis_target":"K3-2-u6-X29"},{"t":"친구 가 — 「밑줄 친 곳은 다시 읽었다는 표시야.」","mis":"K3-2-u6-X29"},{"t":"친구 다 — 「고쳐 쓰면 내 생각이 더 잘 전해져.」","mis":"K3-2-u6-X29"}],"explanation":["밑줄은 다시 읽은 흔적이에요.","못 쓴 글이라는 뜻이 아니에요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L09_challenge#1','kor',3,2,'u6','L09','g3_2_kor_u6_L09_challenge','lesson_challenge','K3-2-u6-C27',2,'sa','auto','「교실 창문을 자주 열자」에서 의견과 이어지지 않는 이유가 있는 줄은 몇 번인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u6-C27","difficulty":2,"kind":"sa","stem":"「교실 창문을 자주 열자」에서 의견과 이어지지 않는 이유가 있는 줄은 몇 번인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["“둘째”로 시작하는 줄이에요.","창문을 잘 연다는 이야기예요.","4번이에요."],"asset":{"type":"passage","lines":["1 교실 공기가 답답할 때가 많다.","2 그래서 쉬는 시간마다 창문을 열면 좋겠다.","3 첫째, 공기가 바뀌면 머리가 맑아져 다음 시간에 집중하기 쉽기 때문이다.","4 둘째, 내가 우리 반에서 창문을 제일 잘 열기 때문이다.","5 쉬는 시간마다 창문을 열어 맑은 공기로 바꾸었으면 좋겠다."],"title":"글 「교실 창문을 자주 열자」"},"mis":"K3-2-u6-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L09_challenge#2','kor',3,2,'u6','L09','g3_2_kor_u6_L09_challenge','lesson_challenge','K3-2-u6-C26',2,'mc','auto','고쳐 쓸 때 살펴볼 것을 바르게 모은 것은 무엇인가요?',ARRAY['K3-2-u6-X27']::text[],false,'{"seq":2,"concept":"K3-2-u6-C26","difficulty":2,"kind":"mc","stem":"고쳐 쓸 때 살펴볼 것을 바르게 모은 것은 무엇인가요?","options":[{"t":"어울리는 의견 · 받쳐 주는 이유 · 어색한 곳 · 띄어쓰기와 맞춤법","correct":true},{"t":"글의 길이 · 글씨 모양","mis":"K3-2-u6-X27"},{"t":"어울리는 의견 한 가지만","mis":"K3-2-u6-X27"},{"t":"맞춤법 한 가지만","mis":"K3-2-u6-X27"}],"explanation":["내용도 봐요.","읽기 쉬운지도 봐요.","네 가지를 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L09_challenge#3','kor',3,2,'u6','L09','g3_2_kor_u6_L09_challenge','lesson_challenge','K3-2-u6-C27',3,'mc','auto','4번 줄이 고쳐 쓸 곳인 까닭은 무엇인가요?',ARRAY['K3-2-u6-X27','K3-2-u6-X23']::text[],false,'{"seq":3,"concept":"K3-2-u6-C27","difficulty":3,"kind":"mc","stem":"4번 줄이 고쳐 쓸 곳인 까닭은 무엇인가요?","options":[{"t":"창문을 열자는 의견과 이어지지 않아서","correct":true},{"t":"4번 줄이 너무 짧아서","mis":"K3-2-u6-X27"},{"t":"“둘째”라는 말을 써서","mis":"K3-2-u6-X27"},{"t":"글쓴이가 자기 이야기를 해서","mis":"K3-2-u6-X23"}],"explanation":["짧아서가 아니에요.","의견과 이어지는지 봐요.","창문을 열자는 것과 이어지지 않아요."],"asset":{"type":"passage","lines":["1 교실 공기가 답답할 때가 많다.","2 그래서 쉬는 시간마다 창문을 열면 좋겠다.","3 첫째, 공기가 바뀌면 머리가 맑아져 다음 시간에 집중하기 쉽기 때문이다.","4 둘째, 내가 우리 반에서 창문을 제일 잘 열기 때문이다.","5 쉬는 시간마다 창문을 열어 맑은 공기로 바꾸었으면 좋겠다."],"title":"글 「교실 창문을 자주 열자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L09_challenge#4','kor',3,2,'u6','L09','g3_2_kor_u6_L09_challenge','lesson_challenge','K3-2-u6-C27',3,'ox','auto','의견과 이어지지 않는 이유는 지우기만 하면 고쳐 쓰기가 끝나요.',ARRAY['K3-2-u6-X28']::text[],false,'{"seq":4,"concept":"K3-2-u6-C27","difficulty":3,"kind":"ox","stem":"의견과 이어지지 않는 이유는 지우기만 하면 고쳐 쓰기가 끝나요.","answer":"X","reason_options":[{"t":"지우기만 하면 이유가 하나밖에 남지 않으니 의견을 받쳐 주는 다른 이유로 채워야 하기 때문에","correct":true},{"t":"이유는 하나만 있어도 충분하기 때문에","mis":"K3-2-u6-X28"}],"mis":"K3-2-u6-X28","explanation":["지우면 이유가 하나 남아요.","다른 이유로 채워요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L09_challenge#5','kor',3,2,'u6','L09','g3_2_kor_u6_L09_challenge','lesson_challenge','K3-2-u6-C29',3,'error','auto','친구 글에 말해 주었어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K3-2-u6-X30']::text[],false,'{"seq":5,"concept":"K3-2-u6-C29","difficulty":3,"kind":"error","stem":"친구 글에 말해 주었어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「틀린 데가 많네. 다시 써.」","correct":true,"mis_target":"K3-2-u6-X30"},{"t":"친구 가 — 「첫째 이유가 의견을 잘 받쳐 줘서 좋아.」","mis":"K3-2-u6-X30"},{"t":"친구 나 — 「4번 줄은 창문 이야기와 이어지지 않는 것 같아.」","mis":"K3-2-u6-X30"}],"explanation":["잘된 곳이 없어요.","어디인지, 왜인지도 없어요.","친구 다가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L09_challenge#6','kor',3,2,'u6','L09','g3_2_kor_u6_L09_challenge','lesson_challenge','K3-2-u6-C28',3,'mc','auto','「고쳐 쓰기는 글을 다 쓴 뒤 흠을 없애는 일이다.」라는 말을 알맞게 고친 것은 무엇인가요?',ARRAY['K3-2-u6-X29','K3-2-u6-X30','K3-2-u6-X27']::text[],false,'{"seq":6,"concept":"K3-2-u6-C28","difficulty":3,"kind":"mc","stem":"「고쳐 쓰기는 글을 다 쓴 뒤 흠을 없애는 일이다.」라는 말을 알맞게 고친 것은 무엇인가요?","options":[{"t":"고쳐 쓰기는 전하려던 생각을 더 잘 전하려고 쓰는 동안 언제든 할 수 있는 일이다","correct":true},{"t":"고쳐 쓰기는 흠이 하나도 없을 때까지 계속 지우는 일이다","mis":"K3-2-u6-X29"},{"t":"고쳐 쓰기는 친구 글의 흠을 찾는 일이다","mis":"K3-2-u6-X30"},{"t":"고쳐 쓰기는 글씨를 다시 예쁘게 쓰는 일이다","mis":"K3-2-u6-X27"}],"explanation":["흠을 없애는 게 목표가 아니에요.","더 잘 전하는 게 목표예요.","언제든 고칠 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L09_challenge#7','kor',3,2,'u6','L09','g3_2_kor_u6_L09_challenge','lesson_challenge','K3-2-u6-C26',3,'mc','auto','“쉬는 시간마다 창문을열면좋겠다.”를 고쳐 쓸 때 살펴볼 것은 무엇인가요?',ARRAY['K3-2-u6-X27']::text[],false,'{"seq":7,"concept":"K3-2-u6-C26","difficulty":3,"kind":"mc","stem":"“쉬는 시간마다 창문을열면좋겠다.”를 고쳐 쓸 때 살펴볼 것은 무엇인가요?","options":[{"t":"띄어쓰기","correct":true},{"t":"이유가 의견을 받쳐 주는가","mis":"K3-2-u6-X27"},{"t":"문제 상황에 어울리는 의견인가","mis":"K3-2-u6-X27"},{"t":"글이 남보다 긴가","mis":"K3-2-u6-X27"}],"explanation":["뜻은 통해요.","붙여 쓴 곳이 있어요.","띄어쓰기를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L09_challenge#8','kor',3,2,'u6','L09','g3_2_kor_u6_L09_challenge','lesson_challenge','K3-2-u6-C29',4,'mc','auto','짝의 「교실 창문을 자주 열자」를 읽고 적어 줄 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X30','K3-2-u6-X29']::text[],false,'{"seq":8,"concept":"K3-2-u6-C29","difficulty":4,"kind":"mc","stem":"짝의 「교실 창문을 자주 열자」를 읽고 적어 줄 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“문제 상황이 또렷해서 좋아. 4번 줄은 의견과 이어지지 않으니 다른 이유로 바꾸면 좋겠어.”","correct":true},{"t":"“글을 다 다시 써야 해.”","mis":"K3-2-u6-X30"},{"t":"“완벽해. 고칠 곳이 하나도 없어.”","mis":"K3-2-u6-X29"},{"t":"“4번 줄이 이상해.”","mis":"K3-2-u6-X30"}],"explanation":["잘된 곳을 먼저 말해요.","고칠 곳을 짚어요.","까닭을 붙여요."],"asset":{"type":"passage","lines":["1 교실 공기가 답답할 때가 많다.","2 그래서 쉬는 시간마다 창문을 열면 좋겠다.","3 첫째, 공기가 바뀌면 머리가 맑아져 다음 시간에 집중하기 쉽기 때문이다.","4 둘째, 내가 우리 반에서 창문을 제일 잘 열기 때문이다.","5 쉬는 시간마다 창문을 열어 맑은 공기로 바꾸었으면 좋겠다."],"title":"글 「교실 창문을 자주 열자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L09_challenge#9','kor',3,2,'u6','L09','g3_2_kor_u6_L09_challenge','lesson_challenge','K3-2-u6-C27',4,'essay','teacher','「교실 창문을 자주 열자」의 4번 줄이 왜 고쳐 쓸 곳인지 쓰고, 의견을 받쳐 주는 이유로 바꾸어 다시 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u6-C27","difficulty":4,"kind":"essay","stem":"「교실 창문을 자주 열자」의 4번 줄이 왜 고쳐 쓸 곳인지 쓰고, 의견을 받쳐 주는 이유로 바꾸어 다시 쓰세요.","answer_guide":{"answer":"예: 4번 줄은 글쓴이가 창문을 잘 연다는 이야기여서 쉬는 시간마다 창문을 열자는 의견과 이어지지 않는다. “둘째, 맑은 공기를 마시면 졸음이 덜 와 수업을 잘 들을 수 있기 때문이다.”처럼 고쳐 쓸 수 있다.","scoring_points":["고칠 까닭을 썼는가","의견과 이어지는 이유로 바꾸어 썼는가","3번 줄과 겹치지 않게 썼는가"]},"explanation":["왜 고칠지 써요.","받쳐 주는 이유로 바꿔요.","겹치지 않게요."],"asset":{"type":"passage","lines":["1 교실 공기가 답답할 때가 많다.","2 그래서 쉬는 시간마다 창문을 열면 좋겠다.","3 첫째, 공기가 바뀌면 머리가 맑아져 다음 시간에 집중하기 쉽기 때문이다.","4 둘째, 내가 우리 반에서 창문을 제일 잘 열기 때문이다.","5 쉬는 시간마다 창문을 열어 맑은 공기로 바꾸었으면 좋겠다."],"title":"글 「교실 창문을 자주 열자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L09_challenge#10','kor',3,2,'u6','L09','g3_2_kor_u6_L09_challenge','lesson_challenge','K3-2-u6-C28',4,'essay','teacher','내 글에 고칠 곳이 여러 군데 보여 속상한 친구에게 해 줄 말을 쓰고, 고쳐 쓰기가 왜 좋은지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u6-C28","difficulty":4,"kind":"essay","stem":"내 글에 고칠 곳이 여러 군데 보여 속상한 친구에게 해 줄 말을 쓰고, 고쳐 쓰기가 왜 좋은지 쓰세요.","answer_guide":{"answer":"예: “고칠 곳이 보인다는 건 네가 글을 다시 꼼꼼히 읽었다는 뜻이야.”라고 말해 주겠다. 글은 처음부터 잘 쓰는 것이 아니라 고쳐 가며 좋아진다. 고쳐 쓰면 내 생각이 읽는 사람에게 더 잘 전해진다.","scoring_points":["위로하는 말을 썼는가","글은 고쳐 가며 좋아진다고 썼는가","고쳐 쓰면 생각이 더 잘 전해진다고 썼는가"]},"explanation":["다시 읽은 거예요.","글은 고쳐 가며 좋아져요.","더 잘 전해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L10_basic#1','kor',3,2,'u6','L10','g3_2_kor_u6_L10_basic','lesson_basic','K3-2-u6-C30',1,'mc','auto','의견을 제시하는 글로 다룰 만한 문제는 무엇인가요?',ARRAY['K3-2-u6-X31','K3-2-u6-X32']::text[],false,'{"seq":1,"concept":"K3-2-u6-C30","difficulty":1,"kind":"mc","stem":"의견을 제시하는 글로 다룰 만한 문제는 무엇인가요?","options":[{"t":"우산꽂이가 뒤엉켜 제 우산을 찾기 어렵다","correct":true},{"t":"어제 비가 온 것","mis":"K3-2-u6-X31"},{"t":"알림장을 늦게 쓰는 친구의 이름","mis":"K3-2-u6-X32"},{"t":"작년 운동회 날의 날씨","mis":"K3-2-u6-X31"}],"explanation":["우리 힘으로 바꿀 수 있나요?","누군가를 탓하는 일은 아닌가요?","우산꽂이는 함께 바꿀 수 있어요."],"asset":{"type":"passage","lines":["비 온 날 우산꽂이가 뒤엉켜 제 우산을 찾기 어렵다.","책상 밑에 지우개 가루가 쌓여 청소 시간이 길어진다.","알림장을 늦게 써서 쉬는 시간이 줄어든다."],"title":"교실에서 있었던 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L10_basic#2','kor',3,2,'u6','L10','g3_2_kor_u6_L10_basic','lesson_basic','K3-2-u6-C33',1,'mc','auto','의견을 제시하는 글의 뼈대를 차례대로 늘어놓은 것은 무엇인가요?',ARRAY['K3-2-u6-X21','K3-2-u6-X20']::text[],false,'{"seq":2,"concept":"K3-2-u6-C33","difficulty":1,"kind":"mc","stem":"의견을 제시하는 글의 뼈대를 차례대로 늘어놓은 것은 무엇인가요?","options":[{"t":"문제 상황 → 의견 → 이유 → 맺음","correct":true},{"t":"맺음 → 이유 → 의견 → 문제 상황","mis":"K3-2-u6-X21"},{"t":"의견 → 맺음 → 문제 상황","mis":"K3-2-u6-X21"},{"t":"이유 → 이유 → 이유","mis":"K3-2-u6-X20"}],"explanation":["무엇이 불편한지부터예요.","그다음 의견과 이유예요.","맺음으로 끝내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L10_basic#3','kor',3,2,'u6','L10','g3_2_kor_u6_L10_basic','lesson_basic','K3-2-u6-C31',1,'ox','auto','글을 쓰기 전에 누가 읽을지 정하면 쓸 말도 정해져요.',ARRAY['K3-2-u6-X33']::text[],false,'{"seq":3,"concept":"K3-2-u6-C31","difficulty":1,"kind":"ox","stem":"글을 쓰기 전에 누가 읽을지 정하면 쓸 말도 정해져요.","answer":"O","reason_options":[{"t":"읽을 사람이 이미 아는 일은 짧게 넘기고 함께 할 일을 자세히 적을 수 있기 때문에","correct":true},{"t":"읽을 사람이 누구든 글은 똑같이 쓰기 때문에","mis":"K3-2-u6-X33"}],"mis":"K3-2-u6-X33","explanation":["읽을 사람이 정해지면","쓸 말도 정해져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L10_basic#4','kor',3,2,'u6','L10','g3_2_kor_u6_L10_basic','lesson_basic','K3-2-u6-C32',1,'mc','auto','이유가 잘 떠오르지 않을 때 먼저 적어 볼 것은 무엇인가요?',ARRAY['K3-2-u6-X23','K3-2-u6-X32','K3-2-u6-X26']::text[],false,'{"seq":4,"concept":"K3-2-u6-C32","difficulty":1,"kind":"mc","stem":"이유가 잘 떠오르지 않을 때 먼저 적어 볼 것은 무엇인가요?","options":[{"t":"내 의견대로 하면 무엇이 좋아질지","correct":true},{"t":"내가 무엇을 제일 잘하는지","mis":"K3-2-u6-X23"},{"t":"누가 잘못했는지","mis":"K3-2-u6-X32"},{"t":"글을 얼마나 길게 쓸지","mis":"K3-2-u6-X26"}],"explanation":["가운데에 의견을 써요.","좋아질 일을 뻗어 적어요.","그것이 이유가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L10_basic#5','kor',3,2,'u6','L10','g3_2_kor_u6_L10_basic','lesson_basic','K3-2-u6-C32',2,'mc','auto','“우산꽂이에 반 번호 칸을 붙이자”를 받쳐 주는 이유는 무엇인가요?',ARRAY['K3-2-u6-X22','K3-2-u6-X23']::text[],false,'{"seq":5,"concept":"K3-2-u6-C32","difficulty":2,"kind":"mc","stem":"“우산꽂이에 반 번호 칸을 붙이자”를 받쳐 주는 이유는 무엇인가요?","options":[{"t":"남의 우산을 잘못 가져가는 일이 줄어든다","correct":true},{"t":"우리 반에 우산이 많이 있다","mis":"K3-2-u6-X22"},{"t":"내가 우산을 제일 빨리 찾는다","mis":"K3-2-u6-X23"},{"t":"우산은 비 올 때 쓴다","mis":"K3-2-u6-X22"}],"explanation":["칸을 붙이면 무엇이 좋아지나요?","잘못 가져가는 일이 줄어요.","그것이 이유예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L10_basic#6','kor',3,2,'u6','L10','g3_2_kor_u6_L10_basic','lesson_basic','K3-2-u6-C33',2,'match','auto','각 문장이 뼈대의 어느 자리인지 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K3-2-u6-C33","difficulty":2,"kind":"match","stem":"각 문장이 뼈대의 어느 자리인지 이으세요.","pairs":[{"l":"번호 칸을 붙이자","r":"의견"},{"l":"왜냐하면 바로 찾을 수 있기 때문이다","r":"이유"},{"l":"다 같이 해 보자","r":"맺음"}],"mis":"K3-2-u6-X21","explanation":["“하자”로 끝나는 줄은 의견이에요.","“왜냐하면”은 이유예요.","함께 해 보자는 말은 맺음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L10_basic#7','kor',3,2,'u6','L10','g3_2_kor_u6_L10_basic','lesson_basic','K3-2-u6-C31',2,'mc','auto','읽을 사람이 우리 반 친구들이라면 무엇이 달라질까요?',ARRAY['K3-2-u6-X33']::text[],false,'{"seq":7,"concept":"K3-2-u6-C31","difficulty":2,"kind":"mc","stem":"읽을 사람이 우리 반 친구들이라면 무엇이 달라질까요?","options":[{"t":"이미 아는 일은 짧게 넘기고 함께 할 일을 자세히 적는다","correct":true},{"t":"우리 교실이 어디에 있는지부터 자세히 적는다","mis":"K3-2-u6-X33"},{"t":"아무도 모르게 짧게만 적는다","mis":"K3-2-u6-X33"},{"t":"읽을 사람과 상관없이 똑같이 쓴다","mis":"K3-2-u6-X33"}],"explanation":["우리 반 친구들은 그 불편을 겪어 봤어요.","길게 쓸 필요가 없는 것이 있어요.","함께 할 일을 자세히 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L10_basic#8','kor',3,2,'u6','L10','g3_2_kor_u6_L10_basic','lesson_basic','K3-2-u6-C34',2,'mc','auto','「점검표로 재 볼 글」은 점검표의 어느 곳에서 걸릴까요?',ARRAY['K3-2-u6-X22','K3-2-u6-X27','K3-2-u6-X21']::text[],false,'{"seq":8,"concept":"K3-2-u6-C34","difficulty":2,"kind":"mc","stem":"「점검표로 재 볼 글」은 점검표의 어느 곳에서 걸릴까요?","options":[{"t":"이유가 의견을 받쳐 주지 못한다","correct":true},{"t":"문제를 풀 수 있는 의견이 아니다","mis":"K3-2-u6-X22"},{"t":"맞춤법이 틀렸다","mis":"K3-2-u6-X27"},{"t":"문제 상황이 없다","mis":"K3-2-u6-X21"}],"explanation":["쓰레받기를 두자는 의견이에요.","“조용해진다”는 이어지지 않아요.","이유에서 걸려요."],"asset":{"type":"passage","lines":["책상 밑에 지우개 가루가 쌓인다.","쓰레받기를 모둠마다 두자.","왜냐하면 교실이 조용해지기 때문이다."],"title":"점검표로 재 볼 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L10_basic#9','kor',3,2,'u6','L10','g3_2_kor_u6_L10_basic','lesson_basic','K3-2-u6-C34',2,'mc','auto','다 쓴 글을 재는 점검표에 들어가는 것은 무엇인가요?',ARRAY['K3-2-u6-X27','K3-2-u6-X32']::text[],false,'{"seq":9,"concept":"K3-2-u6-C34","difficulty":2,"kind":"mc","stem":"다 쓴 글을 재는 점검표에 들어가는 것은 무엇인가요?","options":[{"t":"문제를 풀 수 있는 의견을 썼는가","correct":true},{"t":"글을 남보다 길게 썼는가","mis":"K3-2-u6-X27"},{"t":"친구 이름을 넣었는가","mis":"K3-2-u6-X32"},{"t":"어려운 낱말을 많이 썼는가","mis":"K3-2-u6-X27"}],"explanation":["의견·이유를 봐요.","어색한 곳·맞춤법도 봐요.","길이나 이름은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L10_basic#10','kor',3,2,'u6','L10','g3_2_kor_u6_L10_basic','lesson_basic','K3-2-u6-C30',3,'error','auto','다룰 문제를 골랐어요. 알맞지 않게 고른 친구는 누구인가요?',ARRAY['K3-2-u6-X32','K3-2-u6-X31']::text[],false,'{"seq":10,"concept":"K3-2-u6-C30","difficulty":3,"kind":"error","stem":"다룰 문제를 골랐어요. 알맞지 않게 고른 친구는 누구인가요?","options":[{"t":"친구 나 — 「알림장을 늦게 쓰는 친구 이름을 적어 알리자.」","correct":true,"mis_target":"K3-2-u6-X32"},{"t":"친구 가 — 「지우개 가루가 쌓이는 일을 다루자.」","mis":"K3-2-u6-X32"},{"t":"친구 다 — 「알림장 쓰는 시간이 길어지는 일을 다루자.」","mis":"K3-2-u6-X31"}],"explanation":["이름을 적으면 탓하는 글이 돼요.","함께 바꿀 일을 골라요.","친구 나가 알맞지 않아요."],"asset":{"type":"passage","lines":["비 온 날 우산꽂이가 뒤엉켜 제 우산을 찾기 어렵다.","책상 밑에 지우개 가루가 쌓여 청소 시간이 길어진다.","알림장을 늦게 써서 쉬는 시간이 줄어든다."],"title":"교실에서 있었던 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L10_challenge#1','kor',3,2,'u6','L10','g3_2_kor_u6_L10_challenge','lesson_challenge','K3-2-u6-C33',2,'sa','auto','의견을 제시하는 글의 뼈대에서 「함께 해 보자는 말」이 들어가는 자리를 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u6-C33","difficulty":2,"kind":"sa","stem":"의견을 제시하는 글의 뼈대에서 「함께 해 보자는 말」이 들어가는 자리를 두 글자로 쓰세요.","answer":["맺음"],"explanation":["글의 끝이에요.","함께 해 보자는 말이에요.","‘맺음’이에요."],"mis":"K3-2-u6-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L10_challenge#2','kor',3,2,'u6','L10','g3_2_kor_u6_L10_challenge','lesson_challenge','K3-2-u6-C30',2,'mc','auto','문제 상황으로 「알림장을 늦게 쓰는 친구 이름」을 고르면 글이 어떻게 될까요?',ARRAY['K3-2-u6-X32','K3-2-u6-X20','K3-2-u6-X33']::text[],false,'{"seq":2,"concept":"K3-2-u6-C30","difficulty":2,"kind":"mc","stem":"문제 상황으로 「알림장을 늦게 쓰는 친구 이름」을 고르면 글이 어떻게 될까요?","options":[{"t":"함께 바꿀 일이 아니라 누군가를 탓하는 글이 된다","correct":true},{"t":"문제가 또렷해져 더 좋은 글이 된다","mis":"K3-2-u6-X32"},{"t":"이유를 쓰지 않아도 되는 글이 된다","mis":"K3-2-u6-X20"},{"t":"읽을 사람이 없는 글이 된다","mis":"K3-2-u6-X33"}],"explanation":["이름을 적으면","그 친구를 탓하게 돼요.","의견 글이 아니게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L10_challenge#3','kor',3,2,'u6','L10','g3_2_kor_u6_L10_challenge','lesson_challenge','K3-2-u6-C24',3,'mc','auto','같은 문제를 두고 쓴 ㉮와 ㉯ 가운데 어느 쪽이 낼 수 있는 글일까요?',ARRAY['K3-2-u6-X24']::text[],false,'{"seq":3,"concept":"K3-2-u6-C24","difficulty":3,"kind":"mc","stem":"같은 문제를 두고 쓴 ㉮와 ㉯ 가운데 어느 쪽이 낼 수 있는 글일까요?","options":[{"t":"둘 다 낼 수 있다. 이유가 의견을 받쳐 준다","correct":true},{"t":"㉮가 먼저 나왔으니 ㉮만 맞는 글이다","mis":"K3-2-u6-X24"},{"t":"둘 다 안 되고 정해진 답이 따로 있다","mis":"K3-2-u6-X24"},{"t":"의견이 서로 다르니 둘 다 고쳐 써야 한다","mis":"K3-2-u6-X24"}],"explanation":["의견은 달라요.","둘 다 이유가 받쳐 줘요.","둘 다 낼 수 있어요."],"asset":{"type":"passage","lines":["문제 상황 — 우산꽂이가 뒤엉켜 제 우산을 찾기 어렵다.","㉮ 반 번호 칸을 붙이자.","   제 우산을 바로 찾고, 남의 우산을 잘못 가져가는 일도 줄기 때문이다.","㉯ 우산에 이름표를 달자.","   이름이 보여 바로 알아보고, 잃어버려도 돌아올 수 있기 때문이다."],"title":"같은 문제를 두고 쓴 두 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L10_challenge#4','kor',3,2,'u6','L10','g3_2_kor_u6_L10_challenge','lesson_challenge','K3-2-u6-C34',3,'ox','auto','점검표로 내 글을 재는 것은 틀린 곳을 찾아 점수를 깎으려는 거예요.',ARRAY['K3-2-u6-X29']::text[],false,'{"seq":4,"concept":"K3-2-u6-C34","difficulty":3,"kind":"ox","stem":"점검표로 내 글을 재는 것은 틀린 곳을 찾아 점수를 깎으려는 거예요.","answer":"X","reason_options":[{"t":"내 글이 의견과 이유를 잘 전하는지 재 보고 더 좋게 고치려는 것이기 때문에","correct":true},{"t":"점검표에 걸린 곳이 있으면 못 쓴 글이기 때문에","mis":"K3-2-u6-X29"}],"mis":"K3-2-u6-X29","explanation":["점수를 깎는 게 아니에요.","고쳐 쓰려고 재요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L10_challenge#5','kor',3,2,'u6','L10','g3_2_kor_u6_L10_challenge','lesson_challenge','K3-2-u6-C32',3,'error','auto','“모둠마다 쓰레받기를 두자”의 이유를 모았어요. 의견을 받쳐 주지 못하는 이유를 낸 친구는 누구인가요?',ARRAY['K3-2-u6-X22']::text[],false,'{"seq":5,"concept":"K3-2-u6-C32","difficulty":3,"kind":"error","stem":"“모둠마다 쓰레받기를 두자”의 이유를 모았어요. 의견을 받쳐 주지 못하는 이유를 낸 친구는 누구인가요?","options":[{"t":"친구 다 — 「쓰레받기는 플라스틱으로 만들기 때문이다.」","correct":true,"mis_target":"K3-2-u6-X22"},{"t":"친구 가 — 「청소 시간이 짧아지기 때문이다.」","mis":"K3-2-u6-X22"},{"t":"친구 나 — 「책상 밑이 깨끗해져 발이 편하기 때문이다.」","mis":"K3-2-u6-X22"}],"explanation":["쓰레받기를 두면 무엇이 좋아지나요?","재료 이야기는 상관없어요.","친구 다가 잘못 냈어요."],"asset":{"type":"passage","lines":["책상 밑에 지우개 가루가 쌓인다.","쓰레받기를 모둠마다 두자.","왜냐하면 교실이 조용해지기 때문이다."],"title":"점검표로 재 볼 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L10_challenge#6','kor',3,2,'u6','L10','g3_2_kor_u6_L10_challenge','lesson_challenge','K3-2-u6-C31',3,'mc','auto','같은 의견을 다른 반 친구들이 읽을 글로 쓴다면 무엇을 더 자세히 적어야 할까요?',ARRAY['K3-2-u6-X33','K3-2-u6-X32']::text[],false,'{"seq":6,"concept":"K3-2-u6-C31","difficulty":3,"kind":"mc","stem":"같은 의견을 다른 반 친구들이 읽을 글로 쓴다면 무엇을 더 자세히 적어야 할까요?","options":[{"t":"우리 반에서 어떤 불편이 있었는지","correct":true},{"t":"내가 좋아하는 색","mis":"K3-2-u6-X33"},{"t":"우리 반 친구들의 이름","mis":"K3-2-u6-X32"},{"t":"달라질 것이 없다","mis":"K3-2-u6-X33"}],"explanation":["다른 반은 우리 사정을 몰라요.","불편을 자세히 알려야 해요.","읽을 사람에 따라 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L10_challenge#7','kor',3,2,'u6','L10','g3_2_kor_u6_L10_challenge','lesson_challenge','K3-2-u6-C34',3,'mc','auto','「점검표로 재 볼 글」을 재고 고친 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X28','K3-2-u6-X22','K3-2-u6-X27']::text[],false,'{"seq":7,"concept":"K3-2-u6-C34","difficulty":3,"kind":"mc","stem":"「점검표로 재 볼 글」을 재고 고친 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“왜냐하면 바닥을 바로 쓸 수 있어 청소 시간이 짧아지기 때문이다.”로 바꾼다","correct":true},{"t":"“왜냐하면” 줄을 지우고 그대로 둔다","mis":"K3-2-u6-X28"},{"t":"의견을 “지우개를 쓰지 말자”로 바꾼다","mis":"K3-2-u6-X22"},{"t":"맞춤법만 다시 확인한다","mis":"K3-2-u6-X27"}],"explanation":["걸린 곳은 이유예요.","받쳐 주는 이유로 바꿔요.","청소 시간과 이어져요."],"asset":{"type":"passage","lines":["책상 밑에 지우개 가루가 쌓인다.","쓰레받기를 모둠마다 두자.","왜냐하면 교실이 조용해지기 때문이다."],"title":"점검표로 재 볼 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L10_challenge#8','kor',3,2,'u6','L10','g3_2_kor_u6_L10_challenge','lesson_challenge','K3-2-u6-C30',4,'mc','auto','의견을 제시하는 글로 다루기 알맞은 것끼리 모은 것은 무엇인가요? (㉠ 우산꽂이가 뒤엉킨다 ㉡ 어제 비가 왔다 ㉢ 알림장 쓰는 시간이 길어진다 ㉣ 알림장을 늦게 쓰는 친구 이름)',ARRAY['K3-2-u6-X31','K3-2-u6-X32']::text[],false,'{"seq":8,"concept":"K3-2-u6-C30","difficulty":4,"kind":"mc","stem":"의견을 제시하는 글로 다루기 알맞은 것끼리 모은 것은 무엇인가요? (㉠ 우산꽂이가 뒤엉킨다 ㉡ 어제 비가 왔다 ㉢ 알림장 쓰는 시간이 길어진다 ㉣ 알림장을 늦게 쓰는 친구 이름)","options":[{"t":"㉠, ㉢","correct":true},{"t":"㉠, ㉡","mis":"K3-2-u6-X31"},{"t":"㉢, ㉣","mis":"K3-2-u6-X32"},{"t":"㉡, ㉣","mis":"K3-2-u6-X31"}],"explanation":["㉡은 어쩔 수 없는 일이에요.","㉣은 탓하는 일이에요.","㉠과 ㉢이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L10_challenge#9','kor',3,2,'u6','L10','g3_2_kor_u6_L10_challenge','lesson_challenge','K3-2-u6-C24',4,'essay','teacher','㉮와 ㉯는 의견이 서로 달라요. 둘 다 낼 수 있는 글인지 쓰고, 무엇으로 재었는지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u6-C24","difficulty":4,"kind":"essay","stem":"㉮와 ㉯는 의견이 서로 달라요. 둘 다 낼 수 있는 글인지 쓰고, 무엇으로 재었는지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 둘 다 낼 수 있는 글이다. ㉮는 반 번호 칸을, ㉯는 이름표를 말해 의견은 다르지만, ㉮는 제 우산을 바로 찾고 잘못 가져가는 일이 준다는 이유로, ㉯는 이름이 보여 알아보고 잃어버려도 돌아온다는 이유로 의견을 받쳐 준다. 의견이 다른 것과 틀린 것은 다르고, 이유가 받쳐 주는지로 잰다.","scoring_points":["둘 다 낼 수 있다고 썼는가","두 글의 이유를 각각 짚었는가","이유가 받쳐 주는지로 잰다고 썼는가"]},"explanation":["의견이 달라요.","이유를 봐요.","둘 다 받쳐 줘요."],"asset":{"type":"passage","lines":["문제 상황 — 우산꽂이가 뒤엉켜 제 우산을 찾기 어렵다.","㉮ 반 번호 칸을 붙이자.","   제 우산을 바로 찾고, 남의 우산을 잘못 가져가는 일도 줄기 때문이다.","㉯ 우산에 이름표를 달자.","   이름이 보여 바로 알아보고, 잃어버려도 돌아올 수 있기 때문이다."],"title":"같은 문제를 두고 쓴 두 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L10_challenge#10','kor',3,2,'u6','L10','g3_2_kor_u6_L10_challenge','lesson_challenge','K3-2-u6-C33',4,'essay','teacher','「지우개 가루가 쌓여 청소 시간이 길어진다」를 문제 상황으로 삼아, 뼈대(문제 상황 · 의견 · 이유 두 가지 · 맺음)에 맞추어 짧은 글을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u6-C33","difficulty":4,"kind":"essay","stem":"「지우개 가루가 쌓여 청소 시간이 길어진다」를 문제 상황으로 삼아, 뼈대(문제 상황 · 의견 · 이유 두 가지 · 맺음)에 맞추어 짧은 글을 쓰세요.","answer_guide":{"answer":"예: 책상 밑에 지우개 가루가 쌓여 청소 시간이 길어진다. 그래서 수업이 끝날 때마다 자기 자리 밑을 한 번씩 쓸면 좋겠다. 왜냐하면 조금씩 치우면 금방 끝나기 때문이다. 또 청소 시간이 짧아져 쉬는 시간이 늘기 때문이다. 다 같이 해 보자.","scoring_points":["문제 상황과 의견을 썼는가","의견을 받쳐 주는 이유 두 가지를 겹치지 않게 썼는가","맺음을 썼는가"]},"explanation":["문제 상황부터예요.","이유는 두 가지예요.","맺음으로 끝내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L12_basic#1','kor',3,2,'u6','L12','g3_2_kor_u6_L12_basic','lesson_basic','K3-2-u6-C35',1,'mc','auto','손 팻말에 들어가야 할 것은 무엇인가요?',ARRAY['K3-2-u6-X32','K3-2-u6-X34','K3-2-u6-X35']::text[],false,'{"seq":1,"concept":"K3-2-u6-C35","difficulty":1,"kind":"mc","stem":"손 팻말에 들어가야 할 것은 무엇인가요?","options":[{"t":"내 의견과 그렇게 생각한 이유","correct":true},{"t":"잘 지키지 않는 친구 이름","mis":"K3-2-u6-X32"},{"t":"“하지 마!” 한마디만 크게","mis":"K3-2-u6-X34"},{"t":"이유만 길게 여러 줄","mis":"K3-2-u6-X35"}],"explanation":["글에서 세운 것을 그대로 옮겨요.","의견과 이유가 함께 가요.","탓하는 이름은 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L12_basic#2','kor',3,2,'u6','L12','g3_2_kor_u6_L12_basic','lesson_basic','K3-2-u6-C38',1,'mc','auto','바르게 쓴 것은 무엇인가요?',ARRAY['K3-2-u6-X38']::text[],false,'{"seq":2,"concept":"K3-2-u6-C38","difficulty":1,"kind":"mc","stem":"바르게 쓴 것은 무엇인가요?","options":[{"t":"금방 갈게.","correct":true},{"t":"금방 갈께.","mis":"K3-2-u6-X38"},{"t":"일찍 일어날껄.","mis":"K3-2-u6-X38"},{"t":"내가 도와줄께.","mis":"K3-2-u6-X38"}],"explanation":["[갈께]로 소리 나요.","쓸 때는 그대로 써요.","‘갈게’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L12_basic#3','kor',3,2,'u6','L12','g3_2_kor_u6_L12_basic','lesson_basic','K3-2-u6-C39',1,'ox','auto','“무엇을 먹을까?”처럼 묻는 말은 ‘-ㄹ가’가 아니라 ‘-ㄹ까’로 써요.',ARRAY['K3-2-u6-X39']::text[],false,'{"seq":3,"concept":"K3-2-u6-C39","difficulty":1,"kind":"ox","stem":"“무엇을 먹을까?”처럼 묻는 말은 ‘-ㄹ가’가 아니라 ‘-ㄹ까’로 써요.","answer":"O","reason_options":[{"t":"묻는 말에서는 소리 나는 대로 쓰기 때문에","correct":true},{"t":"약속하는 말처럼 소리와 글자가 달라야 하기 때문에","mis":"K3-2-u6-X39"}],"mis":"K3-2-u6-X39","explanation":["물음표가 붙는 말이에요.","소리 나는 대로 써요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L12_basic#4','kor',3,2,'u6','L12','g3_2_kor_u6_L12_basic','lesson_basic','K3-2-u6-C41',1,'mc','auto','ㅟ가 든 낱말을 바르게 쓴 것은 무엇인가요?',ARRAY['K3-2-u6-X41']::text[],false,'{"seq":4,"concept":"K3-2-u6-C41","difficulty":1,"kind":"mc","stem":"ㅟ가 든 낱말을 바르게 쓴 것은 무엇인가요?","options":[{"t":"바퀴","correct":true},{"t":"바쿼","mis":"K3-2-u6-X41"},{"t":"바퀘","mis":"K3-2-u6-X41"},{"t":"바켜","mis":"K3-2-u6-X41"}],"explanation":["ㅜ 옆에 ㅣ가 붙어요.","ㅟ예요.","‘바퀴’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L12_basic#5','kor',3,2,'u6','L12','g3_2_kor_u6_L12_basic','lesson_basic','K3-2-u6-C37',2,'mc','auto','한 줄 평으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X37','K3-2-u6-X06','K3-2-u6-X07']::text[],false,'{"seq":5,"concept":"K3-2-u6-C37","difficulty":2,"kind":"mc","stem":"한 줄 평으로 알맞은 것은 무엇인가요?","options":[{"t":"“마지막에 돌아서는 장면에서 오래 마음이 남았다.”","correct":true},{"t":"“백 점 만점에 구십 점.”","mis":"K3-2-u6-X37"},{"t":"“주인공이 집을 나갔다가 다시 돌아온다.”","mis":"K3-2-u6-X06"},{"t":"“그냥 재미있다.”","mis":"K3-2-u6-X07"}],"explanation":["점수만 있어도 모자라요.","줄거리만 있어도 모자라요.","느낀 곳과 마음을 함께 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L12_basic#6','kor',3,2,'u6','L12','g3_2_kor_u6_L12_basic','lesson_basic','K3-2-u6-C35',2,'mc','auto','잘 만든 손 팻말은 무엇인가요?',ARRAY['K3-2-u6-X34','K3-2-u6-X35','K3-2-u6-X32']::text[],false,'{"seq":6,"concept":"K3-2-u6-C35","difficulty":2,"kind":"mc","stem":"잘 만든 손 팻말은 무엇인가요?","options":[{"t":"“조용히 이야기해요. 옆 모둠이 잘 들리지 않아요.”","correct":true},{"t":"“떠들지 마!”","mis":"K3-2-u6-X34"},{"t":"“시끄러우면 옆 모둠이 안 들리고 생각도 안 되고 머리도 아프고 …”","mis":"K3-2-u6-X35"},{"t":"“떠드는 사람 이름을 적겠음”","mis":"K3-2-u6-X32"}],"explanation":["“하지 마”만 있으면 명령이에요.","이유만 길면 무엇을 하자는지 안 보여요.","의견과 이유가 함께예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L12_basic#7','kor',3,2,'u6','L12','g3_2_kor_u6_L12_basic','lesson_basic','K3-2-u6-C36',2,'mc','auto','“만약 이랬더라면?” 놀이에서 바꿔 보기 좋은 자리는 어디인가요?',ARRAY['K3-2-u6-X36']::text[],false,'{"seq":7,"concept":"K3-2-u6-C36","difficulty":2,"kind":"mc","stem":"“만약 이랬더라면?” 놀이에서 바꿔 보기 좋은 자리는 어디인가요?","options":[{"t":"내가 마음이 움직인 장면","correct":true},{"t":"작품의 제목","mis":"K3-2-u6-X36"},{"t":"작품이 몇 분짜리인지","mis":"K3-2-u6-X36"},{"t":"작품을 만든 나라","mis":"K3-2-u6-X36"}],"explanation":["아무 데나 바꾸면 감상이 안 남아요.","마음이 움직인 곳을 바꿔요.","왜 그랬는지 더 잘 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L12_basic#8','kor',3,2,'u6','L12','g3_2_kor_u6_L12_basic','lesson_basic','K3-2-u6-C40',2,'match','auto','앞 낱말 다음에 이어질 낱말을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u6-C40","difficulty":2,"kind":"match","stem":"앞 낱말 다음에 이어질 낱말을 알맞게 이으세요.","pairs":[{"l":"의견","r":"견학"},{"l":"나무","r":"무릎"},{"l":"사과","r":"과일"}],"mis":"K3-2-u6-X40","explanation":["앞 낱말의 끝 글자를 짚어요.","그 글자로 시작하는 낱말이에요.","세 짝을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L12_basic#9','kor',3,2,'u6','L12','g3_2_kor_u6_L12_basic','lesson_basic','K3-2-u6-C39',2,'mc','auto','바르게 쓴 것을 고르세요.',ARRAY['K3-2-u6-X39','K3-2-u6-X38']::text[],false,'{"seq":9,"concept":"K3-2-u6-C39","difficulty":2,"kind":"mc","stem":"바르게 쓴 것을 고르세요.","options":[{"t":"어디로 갈까?","correct":true},{"t":"어디로 갈가?","mis":"K3-2-u6-X39"},{"t":"내가 도와줄께.","mis":"K3-2-u6-X38"},{"t":"무엇을 먹을가?","mis":"K3-2-u6-X39"}],"explanation":["묻는 말은 소리 나는 대로예요.","약속하는 말은 그대로예요.","‘갈까?’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L12_basic#10','kor',3,2,'u6','L12','g3_2_kor_u6_L12_basic','lesson_basic','K3-2-u6-C38',3,'error','auto','맞춤법을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u6-X38','K3-2-u6-X39']::text[],false,'{"seq":10,"concept":"K3-2-u6-C38","difficulty":3,"kind":"error","stem":"맞춤법을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「[갈께]로 소리 나니까 ‘갈께’로 써야 해.」","correct":true,"mis_target":"K3-2-u6-X38"},{"t":"친구 가 — 「약속하는 말은 소리가 세져도 ‘갈게’로 써.」","mis":"K3-2-u6-X38"},{"t":"친구 나 — 「묻는 말 ‘먹을까?’는 소리 나는 대로 써.」","mis":"K3-2-u6-X39"}],"explanation":["약속하는 말은 그대로 써요.","묻는 말만 소리대로예요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
