INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L12_challenge#2','kor',3,2,'u6','L12','g3_2_kor_u6_L12_challenge','lesson_challenge','K3-2-u6-C40',2,'mc','auto','‘기차’ 다음에 이어질 낱말은 무엇인가요?',ARRAY['K3-2-u6-X40']::text[],false,'{"seq":2,"concept":"K3-2-u6-C40","difficulty":2,"kind":"mc","stem":"‘기차’ 다음에 이어질 낱말은 무엇인가요?","options":[{"t":"차표","correct":true},{"t":"기린","mis":"K3-2-u6-X40"},{"t":"표지","mis":"K3-2-u6-X40"},{"t":"자석","mis":"K3-2-u6-X40"}],"explanation":["끝 글자는 ‘차’예요.","‘차’로 시작하는 낱말이에요.","‘차표’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L12_challenge#3','kor',3,2,'u6','L12','g3_2_kor_u6_L12_challenge','lesson_challenge','K3-2-u6-C36',3,'mc','auto','「같은 자리」로 “만약 이랬더라면?” 놀이를 한다면 바꿔 보기 좋은 것은 무엇인가요?',ARRAY['K3-2-u6-X36']::text[],false,'{"seq":3,"concept":"K3-2-u6-C36","difficulty":3,"kind":"mc","stem":"「같은 자리」로 “만약 이랬더라면?” 놀이를 한다면 바꿔 보기 좋은 것은 무엇인가요?","options":[{"t":"㉰에서 내가 그렇게만 말하지 않고 짝에게 다른 말을 했더라면","correct":true},{"t":"이야기의 제목을 「화분」으로 바꾸기","mis":"K3-2-u6-X36"},{"t":"잎 수를 여섯 장에서 열 장으로 바꾸기","mis":"K3-2-u6-X36"},{"t":"이야기의 글씨 크기를 바꾸기","mis":"K3-2-u6-X36"}],"explanation":["마음이 움직인 장면을 골라요.","말이나 행동을 바꿔요.","그다음을 상상해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L12_challenge#4','kor',3,2,'u6','L12','g3_2_kor_u6_L12_challenge','lesson_challenge','K3-2-u6-C37',3,'ox','auto','“백 점 만점에 구십 점.”도 내 마음을 담았으니 좋은 한 줄 평이에요.',ARRAY['K3-2-u6-X37']::text[],false,'{"seq":4,"concept":"K3-2-u6-C37","difficulty":3,"kind":"ox","stem":"“백 점 만점에 구십 점.”도 내 마음을 담았으니 좋은 한 줄 평이에요.","answer":"X","reason_options":[{"t":"점수만으로는 어느 곳에서 어떤 마음이 들었는지 친구가 따라올 수 없기 때문에","correct":true},{"t":"한 줄 평은 작품에 점수를 매기는 것이기 때문에","mis":"K3-2-u6-X37"}],"mis":"K3-2-u6-X37","explanation":["점수로는 마음이 안 보여요.","느낀 곳과 마음을 담아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L12_challenge#5','kor',3,2,'u6','L12','g3_2_kor_u6_L12_challenge','lesson_challenge','K3-2-u6-C35',3,'error','auto','팻말을 만들며 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u6-X34','K3-2-u6-X35']::text[],false,'{"seq":5,"concept":"K3-2-u6-C35","difficulty":3,"kind":"error","stem":"팻말을 만들며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「“하지 마!”라고 크게만 쓰면 다들 지킬 거야.」","correct":true,"mis_target":"K3-2-u6-X34"},{"t":"친구 가 — 「의견 아래에 이유를 한 줄로 적자.」","mis":"K3-2-u6-X34"},{"t":"친구 다 — 「멀리서도 보이게 의견은 크게 쓰자.」","mis":"K3-2-u6-X35"}],"explanation":["“하지 마!”만 있으면 명령이에요.","이유가 함께 가요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
