INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L12_challenge#7','kor',3,2,'u6','L12','g3_2_kor_u6_L12_challenge','lesson_challenge','K3-2-u6-C37',3,'mc','auto','친구들이 붙인 한 줄 평 옆에 붙임딱지를 붙이는 까닭은 무엇인가요?',ARRAY['K3-2-u6-X37','K3-2-u6-X06','K3-2-u6-X03']::text[],false,'{"seq":7,"concept":"K3-2-u6-C37","difficulty":3,"kind":"mc","stem":"친구들이 붙인 한 줄 평 옆에 붙임딱지를 붙이는 까닭은 무엇인가요?","options":[{"t":"그 작품을 보고 같은 마음이 들었다는 것을 알리려고","correct":true},{"t":"가장 높은 점수를 준 평을 고르려고","mis":"K3-2-u6-X37"},{"t":"줄거리를 가장 잘 옮긴 평을 고르려고","mis":"K3-2-u6-X06"},{"t":"틀린 평을 표시하려고","mis":"K3-2-u6-X03"}],"explanation":["점수를 고르는 게 아니에요.","같은 마음을 나누는 거예요.","그래서 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L12_challenge#8','kor',3,2,'u6','L12','g3_2_kor_u6_L12_challenge','lesson_challenge','K3-2-u6-C38',4,'mc','auto','약속하는 말과 묻는 말을 모두 바르게 쓴 것은 무엇인가요?',ARRAY['K3-2-u6-X38','K3-2-u6-X39']::text[],false,'{"seq":8,"concept":"K3-2-u6-C38","difficulty":4,"kind":"mc","stem":"약속하는 말과 묻는 말을 모두 바르게 쓴 것은 무엇인가요?","options":[{"t":"“내가 먼저 갈게. 같이 먹을까?”","correct":true},{"t":"“내가 먼저 갈께. 같이 먹을까?”","mis":"K3-2-u6-X38"},{"t":"“내가 먼저 갈게. 같이 먹을가?”","mis":"K3-2-u6-X39"},{"t":"“내가 먼저 갈께. 같이 먹을가?”","mis":"K3-2-u6-X38"}],"explanation":["약속하는 말은 그대로예요.","묻는 말은 소리대로예요.","둘 다 맞은 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L12_challenge#9','kor',3,2,'u6','L12','g3_2_kor_u6_L12_challenge','lesson_challenge','K3-2-u6-C35',4,'essay','teacher','우리 교실에 바라는 일을 하나 골라 손 팻말 문구를 쓰세요. 의견과 이유가 함께 드러나게 쓰고, 왜 이유를 함께 써야 하는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u6-C35","difficulty":4,"kind":"essay","stem":"우리 교실에 바라는 일을 하나 골라 손 팻말 문구를 쓰세요. 의견과 이유가 함께 드러나게 쓰고, 왜 이유를 함께 써야 하는지 쓰세요.","answer_guide":{"answer":"예: “실내화는 신발장에 줄 맞춰! 그래야 내 것을 바로 찾아요.” 의견만 크게 쓰면 명령처럼 느껴지지만, 이유를 함께 쓰면 읽는 사람이 고개를 끄덕이고 함께 지키고 싶어지기 때문이다.","scoring_points":["팻말에 의견을 썼는가","팻말에 이유를 함께 썼는가","이유를 함께 써야 하는 까닭을 썼는가"]},"explanation":["의견을 크게 써요.","이유를 한 줄 붙여요.","명령이 되지 않게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_L12_challenge#10','kor',3,2,'u6','L12','g3_2_kor_u6_L12_challenge','lesson_challenge','K3-2-u6-C37',4,'essay','teacher','내가 본 작품(이야기·만화 영화·드라마 무엇이든)으로 한 줄 평을 쓰고, 그 한 줄 평에 무엇을 담았는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u6-C37","difficulty":4,"kind":"essay","stem":"내가 본 작품(이야기·만화 영화·드라마 무엇이든)으로 한 줄 평을 쓰고, 그 한 줄 평에 무엇을 담았는지 쓰세요.","answer_guide":{"answer":"예: 「두고 온 우산」 — “쪽지 한 줄에서 모르는 사람의 마음이 오래 남았다.” 마음이 움직인 곳(쪽지)과 그때 든 마음(오래 남음)을 함께 담았다. 점수나 줄거리만 쓰지 않았다.","scoring_points":["한 줄 평을 썼는가","느낀 곳을 담았는가","그때 든 마음을 담았는가"]},"explanation":["느낀 곳을 담아요.","마음을 담아요.","한 줄로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_a#1','kor',3,2,'u6','','g3_2_kor_u6_review_a','unit_review','K3-2-u6-C2',1,'mc','auto','「종이배」를 읽고 감상한다는 것은 무엇을 하는 일인가요?',ARRAY['K3-2-u6-X01','K3-2-u6-X02','K3-2-u6-X04']::text[],false,'{"seq":1,"concept":"K3-2-u6-C2","difficulty":1,"kind":"mc","stem":"「종이배」를 읽고 감상한다는 것은 무엇을 하는 일인가요?","options":[{"t":"마음이 움직인 곳을 찾고 무엇을 보고 그랬는지 말하는 일","correct":true},{"t":"줄거리를 처음부터 끝까지 외우는 일","mis":"K3-2-u6-X01"},{"t":"이야기에 점수를 매기는 일","mis":"K3-2-u6-X02"},{"t":"동생이 몇 살인지 알아내는 일","mis":"K3-2-u6-X04"}],"explanation":["외우는 일이 아니에요.","점수도 아니에요.","마음이 움직인 곳과 까닭이에요."],"asset":{"type":"passage","lines":["1 비가 그친 뒤 운동장 구석에 물웅덩이가 생겼다.","2 동생이 종이배를 띄웠는데 바람에 그만 뒤집혔다. 동생 입술이 삐죽 나왔다.","3 나는 아무 말 없이 공책 한 장을 뜯어 배를 다시 접었다.","4 이번에는 배 바닥에 지우개를 하나 올려 두었다.","5 배는 기우뚱하더니 똑바로 섰다. 동생이 손뼉을 치며 깡충 뛰었다.","6 집에 오는 길에 동생이 내 손을 꼭 잡았다. 아무 말도 하지 않았다."],"title":"이야기 「종이배」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_a#2','kor',3,2,'u6','','g3_2_kor_u6_review_a','unit_review','K3-2-u6-C4',1,'mc','auto','「종이배」를 읽고 ㉮는 배가 뒤집히는 곳에서, ㉯는 손을 잡는 곳에서 마음이 움직였어요. 어떻게 된 걸까요?',ARRAY['K3-2-u6-X03','K3-2-u6-X04','K3-2-u6-X05']::text[],false,'{"seq":2,"concept":"K3-2-u6-C4","difficulty":1,"kind":"mc","stem":"「종이배」를 읽고 ㉮는 배가 뒤집히는 곳에서, ㉯는 손을 잡는 곳에서 마음이 움직였어요. 어떻게 된 걸까요?","options":[{"t":"둘 다 제 감상이다. 어디를 보고 그랬는지 말하면 된다","correct":true},{"t":"둘 가운데 하나는 틀린 감상이다","mis":"K3-2-u6-X03"},{"t":"감상은 아무렇게나 말해도 되는 것이다","mis":"K3-2-u6-X04"},{"t":"㉯만 이야기를 제대로 읽었다","mis":"K3-2-u6-X05"}],"explanation":["느낀 곳이 달라요.","둘 다 이야기 안의 곳이에요.","둘 다 제 감상이에요."],"asset":{"type":"speech","turns":[{"who":"㉮","text":"배가 바람에 뒤집히는 데서 웃음이 났어."},{"who":"㉯","text":"동생이 말없이 손을 꼭 잡는 곳이 뭉클했어."},{"who":"㉰","text":"지우개를 올리니 배가 서는 게 신기했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_a#3','kor',3,2,'u6','','g3_2_kor_u6_review_a','unit_review','K3-2-u6-C6',1,'mc','auto','「종이배」의 감상을 말한 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X06','K3-2-u6-X07','K3-2-u6-X02']::text[],false,'{"seq":3,"concept":"K3-2-u6-C6","difficulty":1,"kind":"mc","stem":"「종이배」의 감상을 말한 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“동생이 말없이 손을 꼭 잡는 곳에서 마음이 따뜻해졌어.”","correct":true},{"t":"“동생이 배를 띄웠는데 뒤집혀서 다시 접었대.”","mis":"K3-2-u6-X06"},{"t":"“그냥 좋았어.”","mis":"K3-2-u6-X07"},{"t":"“구십 점짜리 이야기야.”","mis":"K3-2-u6-X02"}],"explanation":["줄거리만 옮기면 모자라요.","느낌만 던져도 모자라요.","장면과 마음을 이어요."],"asset":{"type":"passage","lines":["1 비가 그친 뒤 운동장 구석에 물웅덩이가 생겼다.","2 동생이 종이배를 띄웠는데 바람에 그만 뒤집혔다. 동생 입술이 삐죽 나왔다.","3 나는 아무 말 없이 공책 한 장을 뜯어 배를 다시 접었다.","4 이번에는 배 바닥에 지우개를 하나 올려 두었다.","5 배는 기우뚱하더니 똑바로 섰다. 동생이 손뼉을 치며 깡충 뛰었다.","6 집에 오는 길에 동생이 내 손을 꼭 잡았다. 아무 말도 하지 않았다."],"title":"이야기 「종이배」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_a#4','kor',3,2,'u6','','g3_2_kor_u6_review_a','unit_review','K3-2-u6-C8',1,'mc','auto','「종이배」 2번 줄에서 동생의 마음을 알려 주는 것은 무엇인가요?',ARRAY['K3-2-u6-X09']::text[],false,'{"seq":4,"concept":"K3-2-u6-C8","difficulty":1,"kind":"mc","stem":"「종이배」 2번 줄에서 동생의 마음을 알려 주는 것은 무엇인가요?","options":[{"t":"입술이 삐죽 나왔다","correct":true},{"t":"물웅덩이가 생겼다","mis":"K3-2-u6-X09"},{"t":"비가 그쳤다","mis":"K3-2-u6-X09"},{"t":"운동장 구석이었다","mis":"K3-2-u6-X09"}],"explanation":["얼굴을 봐요.","입술 모양이 말해 줘요.","‘입술이 삐죽’이에요."],"asset":{"type":"passage","lines":["1 비가 그친 뒤 운동장 구석에 물웅덩이가 생겼다.","2 동생이 종이배를 띄웠는데 바람에 그만 뒤집혔다. 동생 입술이 삐죽 나왔다.","3 나는 아무 말 없이 공책 한 장을 뜯어 배를 다시 접었다.","4 이번에는 배 바닥에 지우개를 하나 올려 두었다.","5 배는 기우뚱하더니 똑바로 섰다. 동생이 손뼉을 치며 깡충 뛰었다.","6 집에 오는 길에 동생이 내 손을 꼭 잡았다. 아무 말도 하지 않았다."],"title":"이야기 「종이배」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_a#5','kor',3,2,'u6','','g3_2_kor_u6_review_a','unit_review','K3-2-u6-C14',1,'mc','auto','「한 통의 물감」에서 나는 무엇을 소중히 여겼나요?',ARRAY['K3-2-u6-X15','K3-2-u6-X16']::text[],false,'{"seq":5,"concept":"K3-2-u6-C14","difficulty":1,"kind":"mc","stem":"「한 통의 물감」에서 나는 무엇을 소중히 여겼나요?","options":[{"t":"함께 쓰는 물감을 다른 모둠과 나누어 쓰는 것","correct":true},{"t":"하늘을 크게 그리는 것","mis":"K3-2-u6-X15"},{"t":"짝을 이기는 것","mis":"K3-2-u6-X16"},{"t":"붓을 깨끗이 씻는 것","mis":"K3-2-u6-X15"}],"explanation":["2번 줄을 봐요.","다른 모둠도 빌려 쓸 거라서 아꼈어요.","나누어 쓰는 거예요."],"asset":{"type":"passage","lines":["1 우리 모둠에는 하늘색 물감이 한 통뿐이었다.","2 나는 다른 모둠도 빌려 쓸 거라서 물감을 조금씩만 짜서 아껴 칠했다.","3 짝은 하늘을 크게 그리고 싶어 물감을 듬뿍 짜려다가 내 눈치를 보았다.","4 “이러면 하늘이 얼룩덜룩해지잖아.” 짝이 붓을 내려놓았다.","5 잠시 뒤 짝이 말했다. “흰색을 섞으면 양이 늘지 않을까?”","6 우리는 섞은 물감으로 하늘을 넓게 칠했고, 남은 통은 옆 모둠에 건넸다."],"title":"이야기 「한 통의 물감」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_a#6','kor',3,2,'u6','','g3_2_kor_u6_review_a','unit_review','K3-2-u6-C19',1,'mc','auto','「모둠마다 준비물 바구니를 두자」에서 글쓴이의 의견이 담긴 줄은 몇 번인가요?',ARRAY['K3-2-u6-X19','K3-2-u6-X21']::text[],false,'{"seq":6,"concept":"K3-2-u6-C19","difficulty":1,"kind":"mc","stem":"「모둠마다 준비물 바구니를 두자」에서 글쓴이의 의견이 담긴 줄은 몇 번인가요?","options":[{"t":"2번 줄","correct":true},{"t":"1번 줄","mis":"K3-2-u6-X19"},{"t":"3번 줄","mis":"K3-2-u6-X21"},{"t":"4번 줄","mis":"K3-2-u6-X21"}],"explanation":["“좋겠다”가 붙은 줄이에요.","1번은 있었던 일이에요.","2번 줄이에요."],"asset":{"type":"passage","lines":["1 모둠 활동을 할 때마다 가위와 풀을 빌리러 돌아다니느라 시간이 걸린다.","2 그래서 모둠마다 준비물 바구니를 두면 좋겠다.","3 첫째, 돌아다니지 않아도 되어 활동을 바로 시작할 수 있기 때문이다.","4 둘째, 물건마다 돌아갈 자리가 생겨 잃어버리는 일이 줄기 때문이다.","5 모둠 바구니를 함께 마련해 보자."],"title":"글 「모둠마다 준비물 바구니를 두자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_a#7','kor',3,2,'u6','','g3_2_kor_u6_review_a','unit_review','K3-2-u6-C26',1,'mc','auto','「빈 교실의 불을 끄자」를 고쳐 쓸 때 살펴볼 것은 무엇인가요?',ARRAY['K3-2-u6-X27']::text[],false,'{"seq":7,"concept":"K3-2-u6-C26","difficulty":1,"kind":"mc","stem":"「빈 교실의 불을 끄자」를 고쳐 쓸 때 살펴볼 것은 무엇인가요?","options":[{"t":"이유가 의견을 받쳐 주는가","correct":true},{"t":"글씨가 예쁜가","mis":"K3-2-u6-X27"},{"t":"글이 남보다 긴가","mis":"K3-2-u6-X27"},{"t":"교실에 불이 몇 개인가","mis":"K3-2-u6-X27"}],"explanation":["길이나 글씨 모양이 아니에요.","의견과 이유를 봐요.","받쳐 주는지 봐요."],"asset":{"type":"passage","lines":["1 체육 시간에 교실이 비어 있는데도 불이 켜져 있을 때가 많다.","2 그래서 교실을 나갈 때 마지막 사람이 불을 끄면 좋겠다.","3 첫째, 쓰지 않는 전기를 아낄 수 있기 때문이다.","4 둘째, 내가 우리 반에서 스위치에 손이 제일 잘 닿기 때문이다.","5 교실을 나설 때 불 끄는 일을 함께 지켜 보자."],"title":"글 「빈 교실의 불을 끄자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_a#8','kor',3,2,'u6','','g3_2_kor_u6_review_a','unit_review','K3-2-u6-C38',1,'mc','auto','약속하는 말을 바르게 쓴 것은 무엇인가요?',ARRAY['K3-2-u6-X38','K3-2-u6-X39']::text[],false,'{"seq":8,"concept":"K3-2-u6-C38","difficulty":1,"kind":"mc","stem":"약속하는 말을 바르게 쓴 것은 무엇인가요?","options":[{"t":"“이따가 전화할게.”","correct":true},{"t":"“이따가 전화할께.”","mis":"K3-2-u6-X38"},{"t":"“더 일찍 올껄.”","mis":"K3-2-u6-X38"},{"t":"“같이 할가?”","mis":"K3-2-u6-X39"}],"explanation":["[할께]로 소리 나요.","쓸 때는 그대로 써요.","‘할게’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_a#9','kor',3,2,'u6','','g3_2_kor_u6_review_a','unit_review','K3-2-u6-C7',2,'match','auto','「종이배」를 읽은 세 사람의 감상과 그 근거를 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u6-C7","difficulty":2,"kind":"match","stem":"「종이배」를 읽은 세 사람의 감상과 그 근거를 알맞게 이으세요.","pairs":[{"l":"㉮ 웃음이 났다","r":"배가 바람에 뒤집히는 곳"},{"l":"㉯ 뭉클했다","r":"동생이 손을 꼭 잡는 곳"},{"l":"㉰ 신기했다","r":"지우개를 올리니 배가 서는 곳"}],"mis":"K3-2-u6-X04","explanation":["느낌마다 본 곳이 있어요.","이야기 안에서 찾아요.","세 짝을 이어요."],"asset":{"type":"speech","turns":[{"who":"㉮","text":"배가 바람에 뒤집히는 데서 웃음이 났어."},{"who":"㉯","text":"동생이 말없이 손을 꼭 잡는 곳이 뭉클했어."},{"who":"㉰","text":"지우개를 올리니 배가 서는 게 신기했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_a#10','kor',3,2,'u6','','g3_2_kor_u6_review_a','unit_review','K3-2-u6-C11',2,'mc','auto','“나도 동생 물건을 고쳐 준 적이 있어서 마음이 갔어.”는 어떤 감상 방법을 쓴 것인가요?',ARRAY['K3-2-u6-X12','K3-2-u6-X01']::text[],false,'{"seq":10,"concept":"K3-2-u6-C11","difficulty":2,"kind":"mc","stem":"“나도 동생 물건을 고쳐 준 적이 있어서 마음이 갔어.”는 어떤 감상 방법을 쓴 것인가요?","options":[{"t":"인물의 일을 내 일과 이어 보기","correct":true},{"t":"표정과 말투에 주의하기","mis":"K3-2-u6-X12"},{"t":"장면을 눈앞에 그리며 상상하기","mis":"K3-2-u6-X12"},{"t":"줄거리를 외우기","mis":"K3-2-u6-X01"}],"explanation":["“나도 … 적이 있어”예요.","내 일을 떠올렸어요.","내 일과 이어 보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_a#11','kor',3,2,'u6','','g3_2_kor_u6_review_a','unit_review','K3-2-u6-C17',2,'mc','auto','「한 통의 물감」의 짝에게 물어볼 만한 질문은 무엇인가요?',ARRAY['K3-2-u6-X17']::text[],false,'{"seq":11,"concept":"K3-2-u6-C17","difficulty":2,"kind":"mc","stem":"「한 통의 물감」의 짝에게 물어볼 만한 질문은 무엇인가요?","options":[{"t":"“붓을 내려놓을 때 어떤 마음이었어요?”","correct":true},{"t":"“이 학교는 어디에 있나요?”","mis":"K3-2-u6-X17"},{"t":"“물감은 얼마였나요?”","mis":"K3-2-u6-X17"},{"t":"“이 이야기는 누가 썼나요?”","mis":"K3-2-u6-X17"}],"explanation":["인물이 답할 수 있어야 해요.","마음을 묻는 질문이에요.","이야기 밖의 답은 안 돼요."],"asset":{"type":"passage","lines":["1 우리 모둠에는 하늘색 물감이 한 통뿐이었다.","2 나는 다른 모둠도 빌려 쓸 거라서 물감을 조금씩만 짜서 아껴 칠했다.","3 짝은 하늘을 크게 그리고 싶어 물감을 듬뿍 짜려다가 내 눈치를 보았다.","4 “이러면 하늘이 얼룩덜룩해지잖아.” 짝이 붓을 내려놓았다.","5 잠시 뒤 짝이 말했다. “흰색을 섞으면 양이 늘지 않을까?”","6 우리는 섞은 물감으로 하늘을 넓게 칠했고, 남은 통은 옆 모둠에 건넸다."],"title":"이야기 「한 통의 물감」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_a#12','kor',3,2,'u6','','g3_2_kor_u6_review_a','unit_review','K3-2-u6-C15',2,'mc','auto','「한 통의 물감」에서 짝이 붓을 내려놓은 까닭은 무엇인가요?',ARRAY['K3-2-u6-X11']::text[],false,'{"seq":12,"concept":"K3-2-u6-C15","difficulty":2,"kind":"mc","stem":"「한 통의 물감」에서 짝이 붓을 내려놓은 까닭은 무엇인가요?","options":[{"t":"물감을 조금씩만 쓰면 하늘이 얼룩덜룩해져서","correct":true},{"t":"그림 그리기가 싫어져서","mis":"K3-2-u6-X11"},{"t":"붓이 부러져서","mis":"K3-2-u6-X11"},{"t":"수업이 끝나서","mis":"K3-2-u6-X11"}],"explanation":["4번 줄을 봐요.","“얼룩덜룩해지잖아.”","그래서 내려놓았어요."],"asset":{"type":"passage","lines":["1 우리 모둠에는 하늘색 물감이 한 통뿐이었다.","2 나는 다른 모둠도 빌려 쓸 거라서 물감을 조금씩만 짜서 아껴 칠했다.","3 짝은 하늘을 크게 그리고 싶어 물감을 듬뿍 짜려다가 내 눈치를 보았다.","4 “이러면 하늘이 얼룩덜룩해지잖아.” 짝이 붓을 내려놓았다.","5 잠시 뒤 짝이 말했다. “흰색을 섞으면 양이 늘지 않을까?”","6 우리는 섞은 물감으로 하늘을 넓게 칠했고, 남은 통은 옆 모둠에 건넸다."],"title":"이야기 「한 통의 물감」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_a#13','kor',3,2,'u6','','g3_2_kor_u6_review_a','unit_review','K3-2-u6-C21',2,'match','auto','「모둠마다 준비물 바구니를 두자」의 줄과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"K3-2-u6-C21","difficulty":2,"kind":"match","stem":"「모둠마다 준비물 바구니를 두자」의 줄과 하는 일을 알맞게 이으세요.","pairs":[{"l":"1번 줄","r":"문제 상황"},{"l":"2번 줄","r":"의견"},{"l":"3번 줄","r":"이유"}],"mis":"K3-2-u6-X21","explanation":["불편한 일을 적은 줄","어떻게 하자는 줄","왜 그런지 적은 줄이에요."],"asset":{"type":"passage","lines":["1 모둠 활동을 할 때마다 가위와 풀을 빌리러 돌아다니느라 시간이 걸린다.","2 그래서 모둠마다 준비물 바구니를 두면 좋겠다.","3 첫째, 돌아다니지 않아도 되어 활동을 바로 시작할 수 있기 때문이다.","4 둘째, 물건마다 돌아갈 자리가 생겨 잃어버리는 일이 줄기 때문이다.","5 모둠 바구니를 함께 마련해 보자."],"title":"글 「모둠마다 준비물 바구니를 두자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_a#14','kor',3,2,'u6','','g3_2_kor_u6_review_a','unit_review','K3-2-u6-C25',2,'mc','auto','「모둠마다 준비물 바구니를 두자」를 쓴 친구가 맨 처음에 했을 일로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X26','K3-2-u6-X25']::text[],false,'{"seq":14,"concept":"K3-2-u6-C25","difficulty":2,"kind":"mc","stem":"「모둠마다 준비물 바구니를 두자」를 쓴 친구가 맨 처음에 했을 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"모둠 활동 때 무엇이 불편한지 찾았다","correct":true},{"t":"고운 말을 길게 골랐다","mis":"K3-2-u6-X26"},{"t":"반 친구들이 좋아할 말을 골랐다","mis":"K3-2-u6-X26"},{"t":"이유를 다섯 개 먼저 적었다","mis":"K3-2-u6-X25"}],"explanation":["문제 상황이 먼저예요.","1번 줄이 그것이에요.","불편한 일부터 찾았어요."],"asset":{"type":"passage","lines":["1 모둠 활동을 할 때마다 가위와 풀을 빌리러 돌아다니느라 시간이 걸린다.","2 그래서 모둠마다 준비물 바구니를 두면 좋겠다.","3 첫째, 돌아다니지 않아도 되어 활동을 바로 시작할 수 있기 때문이다.","4 둘째, 물건마다 돌아갈 자리가 생겨 잃어버리는 일이 줄기 때문이다.","5 모둠 바구니를 함께 마련해 보자."],"title":"글 「모둠마다 준비물 바구니를 두자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_a#15','kor',3,2,'u6','','g3_2_kor_u6_review_a','unit_review','K3-2-u6-C31',2,'mc','auto','「모둠마다 준비물 바구니를 두자」를 다른 반 친구들도 읽는다면 더 자세히 쓸 것은 무엇인가요?',ARRAY['K3-2-u6-X32','K3-2-u6-X33']::text[],false,'{"seq":15,"concept":"K3-2-u6-C31","difficulty":2,"kind":"mc","stem":"「모둠마다 준비물 바구니를 두자」를 다른 반 친구들도 읽는다면 더 자세히 쓸 것은 무엇인가요?","options":[{"t":"우리 반 모둠 활동 때 어떤 불편이 있었는지","correct":true},{"t":"우리 반 친구들 이름","mis":"K3-2-u6-X32"},{"t":"내가 좋아하는 색","mis":"K3-2-u6-X33"},{"t":"바꿀 것이 없다","mis":"K3-2-u6-X33"}],"explanation":["다른 반은 우리 사정을 몰라요.","불편을 자세히 알려요.","읽을 사람에 따라 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_a#16','kor',3,2,'u6','','g3_2_kor_u6_review_a','unit_review','K3-2-u6-C35',2,'mc','auto','신발장에 붙일 팻말로 잘 만든 것은 무엇인가요?',ARRAY['K3-2-u6-X34','K3-2-u6-X35','K3-2-u6-X32']::text[],false,'{"seq":16,"concept":"K3-2-u6-C35","difficulty":2,"kind":"mc","stem":"신발장에 붙일 팻말로 잘 만든 것은 무엇인가요?","options":[{"t":"“실내화는 줄 맞춰 넣어요. 내 것을 바로 찾을 수 있어요.”","correct":true},{"t":"“아무렇게나 넣지 마!”","mis":"K3-2-u6-X34"},{"t":"“아무렇게나 두면 찾기 어렵고 늦고 넘어지고 …”","mis":"K3-2-u6-X35"},{"t":"“아무렇게나 둔 사람 이름 적음”","mis":"K3-2-u6-X32"}],"explanation":["명령만 있으면 안 돼요.","이유만 길어도 안 돼요.","의견과 이유가 함께예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_a#17','kor',3,2,'u6','','g3_2_kor_u6_review_a','unit_review','K3-2-u6-C4',3,'mc','auto','단원을 시작할 때와 마칠 때 같은 물음 「같은 작품을 보고 친구와 다르게 느꼈어요. 어떻게 된 걸까요?」를 받았어요. 알맞은 답은 무엇인가요?',ARRAY['K3-2-u6-X03','K3-2-u6-X04']::text[],false,'{"seq":17,"concept":"K3-2-u6-C4","difficulty":3,"kind":"mc","stem":"단원을 시작할 때와 마칠 때 같은 물음 「같은 작품을 보고 친구와 다르게 느꼈어요. 어떻게 된 걸까요?」를 받았어요. 알맞은 답은 무엇인가요?","options":[{"t":"둘 다 제 감상이다. 어디를 보고 그랬는지 말하면 된다","correct":true},{"t":"둘 가운데 하나는 틀린 감상이다","mis":"K3-2-u6-X03"},{"t":"감상은 아무렇게나 말해도 되는 것이다","mis":"K3-2-u6-X04"},{"t":"선생님이 고른 감상이 정답이다","mis":"K3-2-u6-X03"}],"explanation":["처음과 같은 물음이에요.","같은 답이에요.","둘 다 제 감상이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_a#18','kor',3,2,'u6','','g3_2_kor_u6_review_a','unit_review','K3-2-u6-C24',3,'mc','auto','㉮ 바구니 글과 ㉯ 당번 글은 같은 문제에 다른 의견을 냈어요. 어떻게 보면 될까요?',ARRAY['K3-2-u6-X24']::text[],false,'{"seq":18,"concept":"K3-2-u6-C24","difficulty":3,"kind":"mc","stem":"㉮ 바구니 글과 ㉯ 당번 글은 같은 문제에 다른 의견을 냈어요. 어떻게 보면 될까요?","options":[{"t":"이유가 의견을 받쳐 주는지 보면 둘 다 낼 수 있는 글이다","correct":true},{"t":"먼저 쓴 ㉮만 맞는 글이다","mis":"K3-2-u6-X24"},{"t":"둘 다 안 되고 정해진 답이 따로 있다","mis":"K3-2-u6-X24"},{"t":"의견이 다르니 손을 들어 하나를 틀렸다고 정한다","mis":"K3-2-u6-X24"}],"explanation":["의견은 달라요.","이유로 재요.","둘 다 낼 수 있어요."],"asset":{"type":"passage","lines":["문제 — 모둠 활동 때마다 준비물을 빌리러 돌아다닌다.","㉮ 모둠마다 준비물 바구니를 두자.","   바로 시작할 수 있고, 물건마다 돌아갈 자리가 생기기 때문이다.","㉯ 모둠마다 준비물 당번을 정해 활동 전에 한꺼번에 받아 오자.","   한 사람이 챙기니 빠뜨리는 것이 없고, 줄을 서지 않아도 되기 때문이다."],"title":"같은 문제를 두고 쓴 두 글 ㉮ 바구니 · ㉯ 당번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_a#19','kor',3,2,'u6','','g3_2_kor_u6_review_a','unit_review','K3-2-u6-C27',3,'mc','auto','「빈 교실의 불을 끄자」의 4번 줄을 고친 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X28','K3-2-u6-X25','K3-2-u6-X23']::text[],false,'{"seq":19,"concept":"K3-2-u6-C27","difficulty":3,"kind":"mc","stem":"「빈 교실의 불을 끄자」의 4번 줄을 고친 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"둘째, 불 끄는 일을 함께 하면 교실을 아끼는 마음이 생기기 때문이다","correct":true},{"t":"4번 줄을 지우고 이유를 하나만 남긴다","mis":"K3-2-u6-X28"},{"t":"둘째, 전기를 아낄 수 있기 때문이다","mis":"K3-2-u6-X25"},{"t":"둘째, 내가 불을 가장 빨리 끄기 때문이다","mis":"K3-2-u6-X23"}],"explanation":["지우기만 하면 이유가 하나예요.","3번 줄과 겹치면 안 돼요.","받쳐 주는 다른 이유로 바꿔요."],"asset":{"type":"passage","lines":["1 체육 시간에 교실이 비어 있는데도 불이 켜져 있을 때가 많다.","2 그래서 교실을 나갈 때 마지막 사람이 불을 끄면 좋겠다.","3 첫째, 쓰지 않는 전기를 아낄 수 있기 때문이다.","4 둘째, 내가 우리 반에서 스위치에 손이 제일 잘 닿기 때문이다.","5 교실을 나설 때 불 끄는 일을 함께 지켜 보자."],"title":"글 「빈 교실의 불을 끄자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_a#20','kor',3,2,'u6','','g3_2_kor_u6_review_a','unit_review','K3-2-u6-C16',3,'mc','auto','「한 통의 물감」에서 짝이 “흰색을 섞으면 양이 늘지 않을까?”라고 말한 것에서 알 수 있는 것은 무엇인가요?',ARRAY['K3-2-u6-X16','K3-2-u6-X15']::text[],false,'{"seq":20,"concept":"K3-2-u6-C16","difficulty":3,"kind":"mc","stem":"「한 통의 물감」에서 짝이 “흰색을 섞으면 양이 늘지 않을까?”라고 말한 것에서 알 수 있는 것은 무엇인가요?","options":[{"t":"나누어 쓰려는 내 마음과 넓게 칠하려는 자기 마음을 함께 지킬 길을 찾았다","correct":true},{"t":"결국 내가 옳다는 것을 인정했다","mis":"K3-2-u6-X16"},{"t":"물감을 혼자 다 쓰려고 꾀를 냈다","mis":"K3-2-u6-X15"},{"t":"그림 그리기를 그만두려고 했다","mis":"K3-2-u6-X15"}],"explanation":["양이 늘면 넓게 칠할 수 있어요.","남은 통도 나눌 수 있어요.","둘 다 지키는 길이에요."],"asset":{"type":"passage","lines":["1 우리 모둠에는 하늘색 물감이 한 통뿐이었다.","2 나는 다른 모둠도 빌려 쓸 거라서 물감을 조금씩만 짜서 아껴 칠했다.","3 짝은 하늘을 크게 그리고 싶어 물감을 듬뿍 짜려다가 내 눈치를 보았다.","4 “이러면 하늘이 얼룩덜룩해지잖아.” 짝이 붓을 내려놓았다.","5 잠시 뒤 짝이 말했다. “흰색을 섞으면 양이 늘지 않을까?”","6 우리는 섞은 물감으로 하늘을 넓게 칠했고, 남은 통은 옆 모둠에 건넸다."],"title":"이야기 「한 통의 물감」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_a#21','kor',3,2,'u6','','g3_2_kor_u6_review_a','unit_review','K3-2-u6-C34',3,'mc','auto','「빈 교실의 불을 끄자」는 점검표의 어느 곳에서 걸릴까요?',ARRAY['K3-2-u6-X22','K3-2-u6-X27','K3-2-u6-X21']::text[],false,'{"seq":21,"concept":"K3-2-u6-C34","difficulty":3,"kind":"mc","stem":"「빈 교실의 불을 끄자」는 점검표의 어느 곳에서 걸릴까요?","options":[{"t":"의견을 받쳐 주는 이유를 썼는가","correct":true},{"t":"문제를 풀 수 있는 의견을 썼는가","mis":"K3-2-u6-X22"},{"t":"띄어쓰기와 맞춤법은 맞는가","mis":"K3-2-u6-X27"},{"t":"문제 상황이 있는가","mis":"K3-2-u6-X21"}],"explanation":["의견은 문제를 풀 수 있어요.","4번 줄 이유가 걸려요.","이유에서 걸려요."],"asset":{"type":"passage","lines":["1 체육 시간에 교실이 비어 있는데도 불이 켜져 있을 때가 많다.","2 그래서 교실을 나갈 때 마지막 사람이 불을 끄면 좋겠다.","3 첫째, 쓰지 않는 전기를 아낄 수 있기 때문이다.","4 둘째, 내가 우리 반에서 스위치에 손이 제일 잘 닿기 때문이다.","5 교실을 나설 때 불 끄는 일을 함께 지켜 보자."],"title":"글 「빈 교실의 불을 끄자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_a#22','kor',3,2,'u6','','g3_2_kor_u6_review_a','unit_review','K3-2-u6-C9',3,'mc','auto','「종이배」 6번 줄의 “동생이 내 손을 꼭 잡았다. 아무 말도 하지 않았다.”에서 짐작할 수 있는 동생의 마음은 무엇인가요?',ARRAY['K3-2-u6-X10']::text[],false,'{"seq":22,"concept":"K3-2-u6-C9","difficulty":3,"kind":"mc","stem":"「종이배」 6번 줄의 “동생이 내 손을 꼭 잡았다. 아무 말도 하지 않았다.”에서 짐작할 수 있는 동생의 마음은 무엇인가요?","options":[{"t":"고맙고 든든한 마음","correct":true},{"t":"화가 나서 말을 하기 싫었다","mis":"K3-2-u6-X10"},{"t":"손이 추워서 잡았다","mis":"K3-2-u6-X10"},{"t":"집에 가기 싫었다","mis":"K3-2-u6-X10"}],"explanation":["앞에서 배를 고쳐 주었어요.","말 대신 손을 잡았어요.","고마운 마음이에요."],"asset":{"type":"passage","lines":["1 비가 그친 뒤 운동장 구석에 물웅덩이가 생겼다.","2 동생이 종이배를 띄웠는데 바람에 그만 뒤집혔다. 동생 입술이 삐죽 나왔다.","3 나는 아무 말 없이 공책 한 장을 뜯어 배를 다시 접었다.","4 이번에는 배 바닥에 지우개를 하나 올려 두었다.","5 배는 기우뚱하더니 똑바로 섰다. 동생이 손뼉을 치며 깡충 뛰었다.","6 집에 오는 길에 동생이 내 손을 꼭 잡았다. 아무 말도 하지 않았다."],"title":"이야기 「종이배」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_a#23','kor',3,2,'u6','','g3_2_kor_u6_review_a','unit_review','K3-2-u6-C6',4,'mc','auto','「종이배」 감상으로 가장 알맞게 말한 것은 무엇인가요?',ARRAY['K3-2-u6-X06','K3-2-u6-X07','K3-2-u6-X13']::text[],false,'{"seq":23,"concept":"K3-2-u6-C6","difficulty":4,"kind":"mc","stem":"「종이배」 감상으로 가장 알맞게 말한 것은 무엇인가요?","options":[{"t":"“아무 말 없이 배를 다시 접는 곳에서, 말보다 행동이 더 따뜻할 수 있다는 걸 느꼈어.”","correct":true},{"t":"“동생이 배를 띄웠는데 뒤집혀서 다시 접고 지우개를 올렸대.”","mis":"K3-2-u6-X06"},{"t":"“엄청 엄청 좋았어. 최고야.”","mis":"K3-2-u6-X07"},{"t":"“이 이야기의 감동은 마지막 줄 하나뿐이야.”","mis":"K3-2-u6-X13"}],"explanation":["장면이 있어요.","마음이 있어요.","둘을 이었어요."],"asset":{"type":"passage","lines":["1 비가 그친 뒤 운동장 구석에 물웅덩이가 생겼다.","2 동생이 종이배를 띄웠는데 바람에 그만 뒤집혔다. 동생 입술이 삐죽 나왔다.","3 나는 아무 말 없이 공책 한 장을 뜯어 배를 다시 접었다.","4 이번에는 배 바닥에 지우개를 하나 올려 두었다.","5 배는 기우뚱하더니 똑바로 섰다. 동생이 손뼉을 치며 깡충 뛰었다.","6 집에 오는 길에 동생이 내 손을 꼭 잡았다. 아무 말도 하지 않았다."],"title":"이야기 「종이배」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_a#24','kor',3,2,'u6','','g3_2_kor_u6_review_a','unit_review','K3-2-u6-C7',4,'essay','teacher','「종이배」에서 마음이 움직인 곳을 하나 골라 「어느 장면에서 + 어떤 마음」으로 감상을 쓰고, 그렇게 느낀 근거를 이야기에서 찾아 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u6-C7","difficulty":4,"kind":"essay","stem":"「종이배」에서 마음이 움직인 곳을 하나 골라 「어느 장면에서 + 어떤 마음」으로 감상을 쓰고, 그렇게 느낀 근거를 이야기에서 찾아 쓰세요.","answer_guide":{"answer":"예: 동생이 말없이 내 손을 꼭 잡는 장면에서 마음이 뭉클했다. 6번 줄에서 동생은 아무 말도 하지 않았지만, 앞에서 내가 배를 다시 접어 준 일이 고마워 손을 잡은 것 같았기 때문이다. (고른 장면은 사람마다 다를 수 있다.)","scoring_points":["이야기 속 장면을 골랐는가","그때 든 마음을 썼는가","이야기에서 근거를 찾아 썼는가"]},"explanation":["장면을 골라요.","마음을 써요.","근거를 찾아요."],"asset":{"type":"passage","lines":["1 비가 그친 뒤 운동장 구석에 물웅덩이가 생겼다.","2 동생이 종이배를 띄웠는데 바람에 그만 뒤집혔다. 동생 입술이 삐죽 나왔다.","3 나는 아무 말 없이 공책 한 장을 뜯어 배를 다시 접었다.","4 이번에는 배 바닥에 지우개를 하나 올려 두었다.","5 배는 기우뚱하더니 똑바로 섰다. 동생이 손뼉을 치며 깡충 뛰었다.","6 집에 오는 길에 동생이 내 손을 꼭 잡았다. 아무 말도 하지 않았다."],"title":"이야기 「종이배」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_a#25','kor',3,2,'u6','','g3_2_kor_u6_review_a','unit_review','K3-2-u6-C20',4,'essay','teacher','우리 교실의 문제 상황을 하나 골라(이 단원에 나온 것 말고), 문제 상황 · 의견 · 이유 두 가지 · 맺음이 드러나게 짧은 의견 글을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u6-C20","difficulty":4,"kind":"essay","stem":"우리 교실의 문제 상황을 하나 골라(이 단원에 나온 것 말고), 문제 상황 · 의견 · 이유 두 가지 · 맺음이 드러나게 짧은 의견 글을 쓰세요.","answer_guide":{"answer":"예: 비 온 날 교실 바닥이 젖어 미끄럽다. 그래서 교실 문 앞에 발판을 깔면 좋겠다. 첫째, 신발 바닥의 물기가 닦여 넘어지는 일이 줄기 때문이다. 둘째, 청소할 때 바닥을 닦기 쉬워지기 때문이다. 다 같이 발판을 밟고 들어오자.","scoring_points":["문제 상황을 썼는가","의견과 겹치지 않는 이유 두 가지를 썼는가","맺음을 썼는가"]},"explanation":["불편한 일부터 찾아요.","이유는 두 가지예요.","맺음으로 끝내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_b#1','kor',3,2,'u6','','g3_2_kor_u6_review_b','unit_review','K3-2-u6-C1',1,'mc','auto','이 단원에서 한 두 가지 일을 바르게 말한 것은 무엇인가요?',ARRAY['K3-2-u6-X01','K3-2-u6-X20','K3-2-u6-X03']::text[],false,'{"seq":1,"concept":"K3-2-u6-C1","difficulty":1,"kind":"mc","stem":"이 단원에서 한 두 가지 일을 바르게 말한 것은 무엇인가요?","options":[{"t":"작품을 감상하며 받아들이는 일과 의견을 글로 내놓는 일","correct":true},{"t":"작품 줄거리를 외우는 일과 점수를 매기는 일","mis":"K3-2-u6-X01"},{"t":"의견만 크게 쓰는 일과 친구 글의 흠을 찾는 일","mis":"K3-2-u6-X20"},{"t":"작품을 보는 일과 남의 감상을 고쳐 주는 일","mis":"K3-2-u6-X03"}],"explanation":["받아들이는 일이 하나예요.","내놓는 일이 하나예요.","감상하기와 의견 글 쓰기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_b#2','kor',3,2,'u6','','g3_2_kor_u6_review_b','unit_review','K3-2-u6-C5',1,'ox','auto','같은 작품을 보고 사람마다 다른 곳에서 마음이 움직이는 것은 저마다 겪은 일과 처지가 다르기 때문이에요.',ARRAY['K3-2-u6-X05']::text[],false,'{"seq":2,"concept":"K3-2-u6-C5","difficulty":1,"kind":"ox","stem":"같은 작품을 보고 사람마다 다른 곳에서 마음이 움직이는 것은 저마다 겪은 일과 처지가 다르기 때문이에요.","answer":"O","reason_options":[{"t":"동생을 돌봐 본 사람과 종이배를 접어 본 사람은 눈이 가는 곳이 다를 수 있기 때문에","correct":true},{"t":"사람마다 다르게 느끼는 것은 누군가 잘못 읽었기 때문에","mis":"K3-2-u6-X05"}],"mis":"K3-2-u6-X05","explanation":["겪은 일이 달라요.","처지도 달라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_b#3','kor',3,2,'u6','','g3_2_kor_u6_review_b','unit_review','K3-2-u6-C6',1,'blank','auto','“지우개를 올리니 배가 서는 (　)에서 신기했어.” 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u6-X02','K3-2-u6-X06','K3-2-u6-X36']::text[],false,'{"seq":3,"concept":"K3-2-u6-C6","difficulty":1,"kind":"blank","stem":"“지우개를 올리니 배가 서는 (　)에서 신기했어.” 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"장면","correct":true},{"t":"점수","mis":"K3-2-u6-X02"},{"t":"줄거리","mis":"K3-2-u6-X06"},{"t":"제목","mis":"K3-2-u6-X36"}],"explanation":["어디에서 느꼈는지 말해요.","그 자리를 가리키는 말이에요.","‘장면’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_b#4','kor',3,2,'u6','','g3_2_kor_u6_review_b','unit_review','K3-2-u6-C9',1,'mc','auto','「종이배」 5번 줄의 “동생이 손뼉을 치며 깡충 뛰었다”에서 짐작할 수 있는 마음은 무엇인가요?',ARRAY['K3-2-u6-X10']::text[],false,'{"seq":4,"concept":"K3-2-u6-C9","difficulty":1,"kind":"mc","stem":"「종이배」 5번 줄의 “동생이 손뼉을 치며 깡충 뛰었다”에서 짐작할 수 있는 마음은 무엇인가요?","options":[{"t":"배가 서서 무척 기뻤다","correct":true},{"t":"손이 시려 손뼉을 쳤다","mis":"K3-2-u6-X10"},{"t":"배가 다시 뒤집힐까 봐 화가 났다","mis":"K3-2-u6-X10"},{"t":"운동을 하고 싶었다","mis":"K3-2-u6-X10"}],"explanation":["바로 앞에서 배가 섰어요.","손뼉과 깡충은 기쁨이에요.","기뻤던 거예요."],"asset":{"type":"passage","lines":["1 비가 그친 뒤 운동장 구석에 물웅덩이가 생겼다.","2 동생이 종이배를 띄웠는데 바람에 그만 뒤집혔다. 동생 입술이 삐죽 나왔다.","3 나는 아무 말 없이 공책 한 장을 뜯어 배를 다시 접었다.","4 이번에는 배 바닥에 지우개를 하나 올려 두었다.","5 배는 기우뚱하더니 똑바로 섰다. 동생이 손뼉을 치며 깡충 뛰었다.","6 집에 오는 길에 동생이 내 손을 꼭 잡았다. 아무 말도 하지 않았다."],"title":"이야기 「종이배」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_b#5','kor',3,2,'u6','','g3_2_kor_u6_review_b','unit_review','K3-2-u6-C14',1,'mc','auto','「한 통의 물감」에서 짝이 소중히 여긴 것은 무엇인가요?',ARRAY['K3-2-u6-X15','K3-2-u6-X16']::text[],false,'{"seq":5,"concept":"K3-2-u6-C14","difficulty":1,"kind":"mc","stem":"「한 통의 물감」에서 짝이 소중히 여긴 것은 무엇인가요?","options":[{"t":"마음먹은 대로 하늘을 넓게 그리는 것","correct":true},{"t":"물감을 아껴 다른 모둠에 건네는 것","mis":"K3-2-u6-X15"},{"t":"나를 이기는 것","mis":"K3-2-u6-X16"},{"t":"붓을 내려놓는 것","mis":"K3-2-u6-X15"}],"explanation":["3·4번 줄을 봐요.","하늘을 크게 그리고 싶었어요.","넓게 그리는 거예요."],"asset":{"type":"passage","lines":["1 우리 모둠에는 하늘색 물감이 한 통뿐이었다.","2 나는 다른 모둠도 빌려 쓸 거라서 물감을 조금씩만 짜서 아껴 칠했다.","3 짝은 하늘을 크게 그리고 싶어 물감을 듬뿍 짜려다가 내 눈치를 보았다.","4 “이러면 하늘이 얼룩덜룩해지잖아.” 짝이 붓을 내려놓았다.","5 잠시 뒤 짝이 말했다. “흰색을 섞으면 양이 늘지 않을까?”","6 우리는 섞은 물감으로 하늘을 넓게 칠했고, 남은 통은 옆 모둠에 건넸다."],"title":"이야기 「한 통의 물감」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_b#6','kor',3,2,'u6','','g3_2_kor_u6_review_b','unit_review','K3-2-u6-C20',1,'mc','auto','「모둠마다 준비물 바구니를 두자」에서 문제 상황을 쓴 줄은 몇 번인가요?',ARRAY['K3-2-u6-X21']::text[],false,'{"seq":6,"concept":"K3-2-u6-C20","difficulty":1,"kind":"mc","stem":"「모둠마다 준비물 바구니를 두자」에서 문제 상황을 쓴 줄은 몇 번인가요?","options":[{"t":"1번 줄","correct":true},{"t":"2번 줄","mis":"K3-2-u6-X21"},{"t":"3번 줄","mis":"K3-2-u6-X21"},{"t":"5번 줄","mis":"K3-2-u6-X21"}],"explanation":["무엇이 불편한지 쓴 줄이에요.","돌아다니느라 시간이 걸려요.","1번 줄이에요."],"asset":{"type":"passage","lines":["1 모둠 활동을 할 때마다 가위와 풀을 빌리러 돌아다니느라 시간이 걸린다.","2 그래서 모둠마다 준비물 바구니를 두면 좋겠다.","3 첫째, 돌아다니지 않아도 되어 활동을 바로 시작할 수 있기 때문이다.","4 둘째, 물건마다 돌아갈 자리가 생겨 잃어버리는 일이 줄기 때문이다.","5 모둠 바구니를 함께 마련해 보자."],"title":"글 「모둠마다 준비물 바구니를 두자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_b#7','kor',3,2,'u6','','g3_2_kor_u6_review_b','unit_review','K3-2-u6-C28',1,'ox','auto','친구가 내 글에서 고칠 곳을 짚어 주면 나는 글을 못 쓴 거예요.',ARRAY['K3-2-u6-X29']::text[],false,'{"seq":7,"concept":"K3-2-u6-C28","difficulty":1,"kind":"ox","stem":"친구가 내 글에서 고칠 곳을 짚어 주면 나는 글을 못 쓴 거예요.","answer":"X","reason_options":[{"t":"고칠 곳을 알면 내 생각을 더 잘 전하도록 고칠 수 있기 때문에","correct":true},{"t":"잘 쓴 글은 고칠 곳이 하나도 없기 때문에","mis":"K3-2-u6-X29"}],"mis":"K3-2-u6-X29","explanation":["고칠 곳은 못 쓴 표시가 아니에요.","더 잘 전할 기회예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_b#8','kor',3,2,'u6','','g3_2_kor_u6_review_b','unit_review','K3-2-u6-C39',1,'mc','auto','물건 둘 곳을 묻는 말을 바르게 쓴 것은 무엇인가요?',ARRAY['K3-2-u6-X39','K3-2-u6-X38']::text[],false,'{"seq":8,"concept":"K3-2-u6-C39","difficulty":1,"kind":"mc","stem":"물건 둘 곳을 묻는 말을 바르게 쓴 것은 무엇인가요?","options":[{"t":"“어디에 둘까?”","correct":true},{"t":"“어디에 둘가?”","mis":"K3-2-u6-X39"},{"t":"“어디에 둘께?”","mis":"K3-2-u6-X38"},{"t":"“어디에 둘가요?”","mis":"K3-2-u6-X39"}],"explanation":["물음표가 붙는 말이에요.","소리 나는 대로 써요.","‘둘까?’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_b#9','kor',3,2,'u6','','g3_2_kor_u6_review_b','unit_review','K3-2-u6-C7',2,'mc','auto','㉰의 감상 “지우개를 올리니 배가 서는 게 신기했어.”에서 ㉰가 본 곳은 어디인가요?',ARRAY['K3-2-u6-X04']::text[],false,'{"seq":9,"concept":"K3-2-u6-C7","difficulty":2,"kind":"mc","stem":"㉰의 감상 “지우개를 올리니 배가 서는 게 신기했어.”에서 ㉰가 본 곳은 어디인가요?","options":[{"t":"4·5번 줄","correct":true},{"t":"1번 줄","mis":"K3-2-u6-X04"},{"t":"2번 줄","mis":"K3-2-u6-X04"},{"t":"6번 줄","mis":"K3-2-u6-X04"}],"explanation":["지우개가 나오는 줄을 찾아요.","배가 서는 줄도요.","4·5번 줄이에요."],"asset":{"type":"passage","lines":["1 비가 그친 뒤 운동장 구석에 물웅덩이가 생겼다.","2 동생이 종이배를 띄웠는데 바람에 그만 뒤집혔다. 동생 입술이 삐죽 나왔다.","3 나는 아무 말 없이 공책 한 장을 뜯어 배를 다시 접었다.","4 이번에는 배 바닥에 지우개를 하나 올려 두었다.","5 배는 기우뚱하더니 똑바로 섰다. 동생이 손뼉을 치며 깡충 뛰었다.","6 집에 오는 길에 동생이 내 손을 꼭 잡았다. 아무 말도 하지 않았다."],"title":"이야기 「종이배」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_b#10','kor',3,2,'u6','','g3_2_kor_u6_review_b','unit_review','K3-2-u6-C12',2,'mc','auto','「종이배」에서 재미나 감동을 느낄 수 있는 곳을 바르게 모은 것은 무엇인가요?',ARRAY['K3-2-u6-X13','K3-2-u6-X04']::text[],false,'{"seq":10,"concept":"K3-2-u6-C12","difficulty":2,"kind":"mc","stem":"「종이배」에서 재미나 감동을 느낄 수 있는 곳을 바르게 모은 것은 무엇인가요?","options":[{"t":"배가 뒤집히는 곳 · 지우개를 올리는 곳 · 손을 꼭 잡는 곳","correct":true},{"t":"손을 꼭 잡는 곳 한 곳뿐","mis":"K3-2-u6-X13"},{"t":"배가 뒤집히는 곳 · 동생이 엉엉 우는 곳","mis":"K3-2-u6-X04"},{"t":"이야기를 읽은 사람 수 · 손을 잡는 곳","mis":"K3-2-u6-X04"}],"explanation":["이야기 안의 곳은 여럿이에요.","우는 곳은 없어요.","있는 곳을 모두 모아요."],"asset":{"type":"passage","lines":["1 비가 그친 뒤 운동장 구석에 물웅덩이가 생겼다.","2 동생이 종이배를 띄웠는데 바람에 그만 뒤집혔다. 동생 입술이 삐죽 나왔다.","3 나는 아무 말 없이 공책 한 장을 뜯어 배를 다시 접었다.","4 이번에는 배 바닥에 지우개를 하나 올려 두었다.","5 배는 기우뚱하더니 똑바로 섰다. 동생이 손뼉을 치며 깡충 뛰었다.","6 집에 오는 길에 동생이 내 손을 꼭 잡았다. 아무 말도 하지 않았다."],"title":"이야기 「종이배」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_b#11','kor',3,2,'u6','','g3_2_kor_u6_review_b','unit_review','K3-2-u6-C18',2,'mc','auto','모둠에 하나뿐인 물건을 두고 친구와 부딪쳤을 때 먼저 볼 것은 무엇인가요?',ARRAY['K3-2-u6-X16','K3-2-u6-X18']::text[],false,'{"seq":11,"concept":"K3-2-u6-C18","difficulty":2,"kind":"mc","stem":"모둠에 하나뿐인 물건을 두고 친구와 부딪쳤을 때 먼저 볼 것은 무엇인가요?","options":[{"t":"서로 무엇을 소중히 여기는지","correct":true},{"t":"누가 먼저 잘못했는지","mis":"K3-2-u6-X16"},{"t":"부딪친 일은 덮어 두기","mis":"K3-2-u6-X18"},{"t":"누가 더 힘이 센지","mis":"K3-2-u6-X16"}],"explanation":["잘잘못부터 가리지 않아요.","덮어 두지도 않아요.","소중한 것부터 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_b#12','kor',3,2,'u6','','g3_2_kor_u6_review_b','unit_review','K3-2-u6-C15',2,'mc','auto','「한 통의 물감」에서 두 사람이 찾은 길은 무엇인가요?',ARRAY['K3-2-u6-X11']::text[],false,'{"seq":12,"concept":"K3-2-u6-C15","difficulty":2,"kind":"mc","stem":"「한 통의 물감」에서 두 사람이 찾은 길은 무엇인가요?","options":[{"t":"흰색을 섞어 양을 늘리고, 남은 통은 옆 모둠에 건넨다","correct":true},{"t":"짝이 물감을 다 쓰고 옆 모둠에는 주지 않는다","mis":"K3-2-u6-X11"},{"t":"나 혼자 그림을 다 칠한다","mis":"K3-2-u6-X11"},{"t":"하늘을 그리지 않기로 한다","mis":"K3-2-u6-X11"}],"explanation":["5·6번 줄을 봐요.","흰색을 섞었어요.","남은 통은 건넸어요."],"asset":{"type":"passage","lines":["1 우리 모둠에는 하늘색 물감이 한 통뿐이었다.","2 나는 다른 모둠도 빌려 쓸 거라서 물감을 조금씩만 짜서 아껴 칠했다.","3 짝은 하늘을 크게 그리고 싶어 물감을 듬뿍 짜려다가 내 눈치를 보았다.","4 “이러면 하늘이 얼룩덜룩해지잖아.” 짝이 붓을 내려놓았다.","5 잠시 뒤 짝이 말했다. “흰색을 섞으면 양이 늘지 않을까?”","6 우리는 섞은 물감으로 하늘을 넓게 칠했고, 남은 통은 옆 모둠에 건넸다."],"title":"이야기 「한 통의 물감」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_b#13','kor',3,2,'u6','','g3_2_kor_u6_review_b','unit_review','K3-2-u6-C22',2,'mc','auto','「모둠마다 준비물 바구니를 두자」의 의견을 받쳐 주는 이유로 알맞지 않은 것은 무엇인가요?',ARRAY['K3-2-u6-X22']::text[],false,'{"seq":13,"concept":"K3-2-u6-C22","difficulty":2,"kind":"mc","stem":"「모둠마다 준비물 바구니를 두자」의 의견을 받쳐 주는 이유로 알맞지 않은 것은 무엇인가요?","options":[{"t":"우리 반 바구니는 파란색이기 때문이다","correct":true},{"t":"돌아다니지 않아 활동을 바로 시작할 수 있기 때문이다","mis":"K3-2-u6-X22"},{"t":"물건마다 돌아갈 자리가 생기기 때문이다","mis":"K3-2-u6-X22"},{"t":"빌리러 다니는 동안 시끄러워지는 일이 줄기 때문이다","mis":"K3-2-u6-X22"}],"explanation":["바구니를 두면 무엇이 좋아지나요?","색깔은 상관없어요.","그것이 답이에요."],"asset":{"type":"passage","lines":["1 모둠 활동을 할 때마다 가위와 풀을 빌리러 돌아다니느라 시간이 걸린다.","2 그래서 모둠마다 준비물 바구니를 두면 좋겠다.","3 첫째, 돌아다니지 않아도 되어 활동을 바로 시작할 수 있기 때문이다.","4 둘째, 물건마다 돌아갈 자리가 생겨 잃어버리는 일이 줄기 때문이다.","5 모둠 바구니를 함께 마련해 보자."],"title":"글 「모둠마다 준비물 바구니를 두자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_b#14','kor',3,2,'u6','','g3_2_kor_u6_review_b','unit_review','K3-2-u6-C30',2,'mc','auto','의견을 제시하는 글로 다룰 문제로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X31','K3-2-u6-X32']::text[],false,'{"seq":14,"concept":"K3-2-u6-C30","difficulty":2,"kind":"mc","stem":"의견을 제시하는 글로 다룰 문제로 알맞은 것은 무엇인가요?","options":[{"t":"실내화가 신발장에 아무렇게나 놓여 제 것을 찾기 어렵다","correct":true},{"t":"오늘 아침 날씨가 추웠다","mis":"K3-2-u6-X31"},{"t":"실내화를 아무렇게나 두는 친구 이름","mis":"K3-2-u6-X32"},{"t":"지난해 운동장의 크기","mis":"K3-2-u6-X31"}],"explanation":["어쩔 수 없는 일은 빼요.","탓하는 일도 빼요.","함께 바꿀 일을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_b#15','kor',3,2,'u6','','g3_2_kor_u6_review_b','unit_review','K3-2-u6-C33',2,'mc','auto','「모둠마다 준비물 바구니를 두자」에서 맺음에 해당하는 줄은 몇 번인가요?',ARRAY['K3-2-u6-X21']::text[],false,'{"seq":15,"concept":"K3-2-u6-C33","difficulty":2,"kind":"mc","stem":"「모둠마다 준비물 바구니를 두자」에서 맺음에 해당하는 줄은 몇 번인가요?","options":[{"t":"5번 줄","correct":true},{"t":"1번 줄","mis":"K3-2-u6-X21"},{"t":"2번 줄","mis":"K3-2-u6-X21"},{"t":"4번 줄","mis":"K3-2-u6-X21"}],"explanation":["함께 해 보자는 말이에요.","글의 끝이에요.","5번 줄이에요."],"asset":{"type":"passage","lines":["1 모둠 활동을 할 때마다 가위와 풀을 빌리러 돌아다니느라 시간이 걸린다.","2 그래서 모둠마다 준비물 바구니를 두면 좋겠다.","3 첫째, 돌아다니지 않아도 되어 활동을 바로 시작할 수 있기 때문이다.","4 둘째, 물건마다 돌아갈 자리가 생겨 잃어버리는 일이 줄기 때문이다.","5 모둠 바구니를 함께 마련해 보자."],"title":"글 「모둠마다 준비물 바구니를 두자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_b#16','kor',3,2,'u6','','g3_2_kor_u6_review_b','unit_review','K3-2-u6-C37',2,'mc','auto','「종이배」의 한 줄 평으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X37','K3-2-u6-X06','K3-2-u6-X07']::text[],false,'{"seq":16,"concept":"K3-2-u6-C37","difficulty":2,"kind":"mc","stem":"「종이배」의 한 줄 평으로 알맞은 것은 무엇인가요?","options":[{"t":"“말없이 잡은 손에서 동생 마음이 오래 남았다.”","correct":true},{"t":"“별 다섯 개 가운데 네 개.”","mis":"K3-2-u6-X37"},{"t":"“동생이 종이배를 띄웠다가 다시 띄운다.”","mis":"K3-2-u6-X06"},{"t":"“그냥 좋다.”","mis":"K3-2-u6-X07"}],"explanation":["별 개수로는 마음이 안 보여요.","줄거리만으로도 모자라요.","느낀 곳과 마음을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_b#17','kor',3,2,'u6','','g3_2_kor_u6_review_b','unit_review','K3-2-u6-C12',3,'error','auto','「종이배」 감상을 두고 이야기했어요. 잘못 생각한 친구는 누구인가요?',ARRAY['K3-2-u6-X13','K3-2-u6-X03']::text[],false,'{"seq":17,"concept":"K3-2-u6-C12","difficulty":3,"kind":"error","stem":"「종이배」 감상을 두고 이야기했어요. 잘못 생각한 친구는 누구인가요?","options":[{"t":"친구 가 — 「감동은 손을 잡는 곳 하나뿐이니까 뒤집히는 곳을 고른 건 틀렸어.」","correct":true,"mis_target":"K3-2-u6-X13"},{"t":"친구 나 — 「뒤집히는 곳을 고른 까닭을 들어 보자.」","mis":"K3-2-u6-X03"},{"t":"친구 다 — 「배가 서는 곳도 이야기 안에 있으니 느낄 수 있어.」","mis":"K3-2-u6-X13"}],"explanation":["느낄 자리는 여럿이에요.","정해진 한 곳이 없어요.","친구 가가 잘못 생각했어요."],"asset":{"type":"speech","turns":[{"who":"㉮","text":"배가 바람에 뒤집히는 데서 웃음이 났어."},{"who":"㉯","text":"동생이 말없이 손을 꼭 잡는 곳이 뭉클했어."},{"who":"㉰","text":"지우개를 올리니 배가 서는 게 신기했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_b#18','kor',3,2,'u6','','g3_2_kor_u6_review_b','unit_review','K3-2-u6-C24',3,'error','auto','㉮와 ㉯ 두 글을 읽고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u6-X24']::text[],false,'{"seq":18,"concept":"K3-2-u6-C24","difficulty":3,"kind":"error","stem":"㉮와 ㉯ 두 글을 읽고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「내 의견은 바구니니까 당번 글은 틀렸어.」","correct":true,"mis_target":"K3-2-u6-X24"},{"t":"친구 가 — 「당번 글도 이유가 의견을 받쳐 주네.」","mis":"K3-2-u6-X24"},{"t":"친구 다 — 「둘 다 해 보고 우리 반에 맞는 걸 고르자.」","mis":"K3-2-u6-X24"}],"explanation":["내 의견과 다르다고 틀린 게 아니에요.","이유로 재요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["문제 — 모둠 활동 때마다 준비물을 빌리러 돌아다닌다.","㉮ 모둠마다 준비물 바구니를 두자.","   바로 시작할 수 있고, 물건마다 돌아갈 자리가 생기기 때문이다.","㉯ 모둠마다 준비물 당번을 정해 활동 전에 한꺼번에 받아 오자.","   한 사람이 챙기니 빠뜨리는 것이 없고, 줄을 서지 않아도 되기 때문이다."],"title":"같은 문제를 두고 쓴 두 글 ㉮ 바구니 · ㉯ 당번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_b#19','kor',3,2,'u6','','g3_2_kor_u6_review_b','unit_review','K3-2-u6-C28',3,'error','auto','「빈 교실의 불을 끄자」를 고쳐 쓰며 말했어요. 잘못 생각한 친구는 누구인가요?',ARRAY['K3-2-u6-X29']::text[],false,'{"seq":19,"concept":"K3-2-u6-C28","difficulty":3,"kind":"error","stem":"「빈 교실의 불을 끄자」를 고쳐 쓰며 말했어요. 잘못 생각한 친구는 누구인가요?","options":[{"t":"친구 다 — 「4번 줄을 고쳐야 하니 이 글은 못 쓴 글이야.」","correct":true,"mis_target":"K3-2-u6-X29"},{"t":"친구 가 — 「4번 줄을 찾은 건 글을 다시 읽었다는 뜻이야.」","mis":"K3-2-u6-X29"},{"t":"친구 나 — 「고치면 의견이 더 잘 전해질 거야.」","mis":"K3-2-u6-X29"}],"explanation":["고칠 곳은 못 쓴 표시가 아니에요.","고쳐 가며 좋아져요.","친구 다가 잘못 생각했어요."],"asset":{"type":"passage","lines":["1 체육 시간에 교실이 비어 있는데도 불이 켜져 있을 때가 많다.","2 그래서 교실을 나갈 때 마지막 사람이 불을 끄면 좋겠다.","3 첫째, 쓰지 않는 전기를 아낄 수 있기 때문이다.","4 둘째, 내가 우리 반에서 스위치에 손이 제일 잘 닿기 때문이다.","5 교실을 나설 때 불 끄는 일을 함께 지켜 보자."],"title":"글 「빈 교실의 불을 끄자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_b#20','kor',3,2,'u6','','g3_2_kor_u6_review_b','unit_review','K3-2-u6-C16',3,'error','auto','「한 통의 물감」을 읽고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u6-X16']::text[],false,'{"seq":20,"concept":"K3-2-u6-C16","difficulty":3,"kind":"error","stem":"「한 통의 물감」을 읽고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「물감을 아끼느라 눈치 준 “나”가 잘못했어.」","correct":true,"mis_target":"K3-2-u6-X16"},{"t":"친구 가 — 「둘 다 소중히 여기는 게 있었어.」","mis":"K3-2-u6-X16"},{"t":"친구 다 — 「흰색을 섞어서 둘 다 지켰어.」","mis":"K3-2-u6-X16"}],"explanation":["“나”도 소중한 것이 있었어요.","잘못한 쪽을 고를 물음이 아니에요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["1 우리 모둠에는 하늘색 물감이 한 통뿐이었다.","2 나는 다른 모둠도 빌려 쓸 거라서 물감을 조금씩만 짜서 아껴 칠했다.","3 짝은 하늘을 크게 그리고 싶어 물감을 듬뿍 짜려다가 내 눈치를 보았다.","4 “이러면 하늘이 얼룩덜룩해지잖아.” 짝이 붓을 내려놓았다.","5 잠시 뒤 짝이 말했다. “흰색을 섞으면 양이 늘지 않을까?”","6 우리는 섞은 물감으로 하늘을 넓게 칠했고, 남은 통은 옆 모둠에 건넸다."],"title":"이야기 「한 통의 물감」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_b#21','kor',3,2,'u6','','g3_2_kor_u6_review_b','unit_review','K3-2-u6-C32',3,'mc','auto','「빈 교실의 불을 끄자」의 의견대로 하면 좋아질 일로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X23','K3-2-u6-X22']::text[],false,'{"seq":21,"concept":"K3-2-u6-C32","difficulty":3,"kind":"mc","stem":"「빈 교실의 불을 끄자」의 의견대로 하면 좋아질 일로 알맞은 것은 무엇인가요?","options":[{"t":"쓰지 않는 전기가 줄어든다","correct":true},{"t":"내가 스위치를 제일 잘 누르게 된다","mis":"K3-2-u6-X23"},{"t":"교실 불이 하얀색이 된다","mis":"K3-2-u6-X22"},{"t":"체육 시간이 길어진다","mis":"K3-2-u6-X22"}],"explanation":["불을 끄면 무엇이 좋아지나요?","전기를 아껴요.","그것이 이유가 돼요."],"asset":{"type":"passage","lines":["1 체육 시간에 교실이 비어 있는데도 불이 켜져 있을 때가 많다.","2 그래서 교실을 나갈 때 마지막 사람이 불을 끄면 좋겠다.","3 첫째, 쓰지 않는 전기를 아낄 수 있기 때문이다.","4 둘째, 내가 우리 반에서 스위치에 손이 제일 잘 닿기 때문이다.","5 교실을 나설 때 불 끄는 일을 함께 지켜 보자."],"title":"글 「빈 교실의 불을 끄자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_b#22','kor',3,2,'u6','','g3_2_kor_u6_review_b','unit_review','K3-2-u6-C12',3,'mc','auto','「종이배」를 읽고 가는 「배가 뒤집히는 곳이 웃겼어.」, 나는 「손을 잡는 곳이 뭉클했어.」라고 했어요. 알맞은 생각은 무엇인가요?',ARRAY['K3-2-u6-X13','K3-2-u6-X08','K3-2-u6-X06']::text[],false,'{"seq":22,"concept":"K3-2-u6-C12","difficulty":3,"kind":"mc","stem":"「종이배」를 읽고 가는 「배가 뒤집히는 곳이 웃겼어.」, 나는 「손을 잡는 곳이 뭉클했어.」라고 했어요. 알맞은 생각은 무엇인가요?","options":[{"t":"한 이야기 안에 재미와 감동이 둘 다 있어 둘 다 제 감상이다","correct":true},{"t":"웃긴 곳을 고른 가는 감동을 놓쳤으니 틀렸다","mis":"K3-2-u6-X13"},{"t":"한 작품에는 재미나 감동 하나만 있다","mis":"K3-2-u6-X08"},{"t":"둘 다 줄거리를 말했다","mis":"K3-2-u6-X06"}],"explanation":["웃긴 곳도 있어요.","뭉클한 곳도 있어요.","둘 다 제 감상이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_b#23','kor',3,2,'u6','','g3_2_kor_u6_review_b','unit_review','K3-2-u6-C24',4,'mc','auto','㉮ 바구니 글과 ㉯ 당번 글에 대한 말 가운데 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X24','K3-2-u6-X25','K3-2-u6-X21']::text[],false,'{"seq":23,"concept":"K3-2-u6-C24","difficulty":4,"kind":"mc","stem":"㉮ 바구니 글과 ㉯ 당번 글에 대한 말 가운데 가장 알맞은 것은 무엇인가요?","options":[{"t":"㉮는 바로 시작하고 잃어버리지 않는다는 이유로, ㉯는 빠뜨리지 않고 줄 서지 않는다는 이유로 받쳐 주니 둘 다 낼 수 있다","correct":true},{"t":"㉮가 먼저 나왔으니 ㉯는 틀렸다","mis":"K3-2-u6-X24"},{"t":"㉯는 이유가 하나뿐이니 낼 수 없다","mis":"K3-2-u6-X25"},{"t":"둘 다 문제 상황이 없으니 틀렸다","mis":"K3-2-u6-X21"}],"explanation":["두 글의 이유를 짚어요.","둘 다 받쳐 줘요.","둘 다 낼 수 있어요."],"asset":{"type":"passage","lines":["문제 — 모둠 활동 때마다 준비물을 빌리러 돌아다닌다.","㉮ 모둠마다 준비물 바구니를 두자.","   바로 시작할 수 있고, 물건마다 돌아갈 자리가 생기기 때문이다.","㉯ 모둠마다 준비물 당번을 정해 활동 전에 한꺼번에 받아 오자.","   한 사람이 챙기니 빠뜨리는 것이 없고, 줄을 서지 않아도 되기 때문이다."],"title":"같은 문제를 두고 쓴 두 글 ㉮ 바구니 · ㉯ 당번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_b#24','kor',3,2,'u6','','g3_2_kor_u6_review_b','unit_review','K3-2-u6-C24',4,'essay','teacher','㉮ 바구니 글과 ㉯ 당번 글 가운데 우리 반에 맞는 것을 골라 까닭을 쓰고, 고르지 않은 쪽이 틀린 글이 아닌 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u6-C24","difficulty":4,"kind":"essay","stem":"㉮ 바구니 글과 ㉯ 당번 글 가운데 우리 반에 맞는 것을 골라 까닭을 쓰고, 고르지 않은 쪽이 틀린 글이 아닌 까닭을 쓰세요.","answer_guide":{"answer":"예: 우리 반은 모둠 자리가 자주 바뀌어 당번이 한꺼번에 받아 오는 ㉯가 더 맞다. 하지만 ㉮도 바로 시작할 수 있고 물건이 돌아갈 자리가 생긴다는 이유가 의견을 받쳐 주므로 틀린 글이 아니다. 의견이 다른 것과 틀린 것은 다르다.","scoring_points":["하나를 골라 까닭을 썼는가","고르지 않은 글의 이유를 짚었는가","다른 것과 틀린 것은 다르다고 썼는가"]},"explanation":["하나를 골라도 돼요.","다른 쪽도 이유가 있어요.","다른 것과 틀린 것은 달라요."],"asset":{"type":"passage","lines":["문제 — 모둠 활동 때마다 준비물을 빌리러 돌아다닌다.","㉮ 모둠마다 준비물 바구니를 두자.","   바로 시작할 수 있고, 물건마다 돌아갈 자리가 생기기 때문이다.","㉯ 모둠마다 준비물 당번을 정해 활동 전에 한꺼번에 받아 오자.","   한 사람이 챙기니 빠뜨리는 것이 없고, 줄을 서지 않아도 되기 때문이다."],"title":"같은 문제를 두고 쓴 두 글 ㉮ 바구니 · ㉯ 당번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_b#25','kor',3,2,'u6','','g3_2_kor_u6_review_b','unit_review','K3-2-u6-C18',4,'essay','teacher','친구와 하나뿐인 물건을 두고 부딪친 일을 떠올려(지어내도 돼요), 서로 무엇을 소중히 여겼는지와 둘 다 지킬 수 있는 길을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u6-C18","difficulty":4,"kind":"essay","stem":"친구와 하나뿐인 물건을 두고 부딪친 일을 떠올려(지어내도 돼요), 서로 무엇을 소중히 여겼는지와 둘 다 지킬 수 있는 길을 쓰세요.","answer_guide":{"answer":"예: 모둠에 하나뿐인 돋보기를 두고 나는 개미를 오래 보고 싶었고, 친구는 차례를 지켜 모두 한 번씩 보는 것을 소중히 여겼다. 누가 잘못했는지 따지지 않고 이야기해 보니, 한 사람이 한 번 볼 때 개미 하나씩 찾아 알려 주기로 정할 수 있었다.","scoring_points":["부딪친 일을 썼는가","서로 소중히 여긴 것을 썼는가","둘 다 지킬 수 있는 길을 썼는가"]},"explanation":["잘잘못을 따지지 않아요.","소중한 것을 말해요.","둘 다 지킬 길을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_c#1','kor',3,2,'u6','','g3_2_kor_u6_review_c','unit_review','K3-2-u6-C2',1,'ox','auto','작품을 감상한다는 것은 작품에 몇 점을 줄지 매기는 일이에요.',ARRAY['K3-2-u6-X02']::text[],false,'{"seq":1,"concept":"K3-2-u6-C2","difficulty":1,"kind":"ox","stem":"작품을 감상한다는 것은 작품에 몇 점을 줄지 매기는 일이에요.","answer":"X","reason_options":[{"t":"마음이 움직인 곳을 찾고, 어디를 보고 그랬는지 말하는 일이기 때문에","correct":true},{"t":"좋은 작품과 나쁜 작품을 가르는 것이 감상이기 때문에","mis":"K3-2-u6-X02"}],"mis":"K3-2-u6-X02","explanation":["점수로는 마음이 안 보여요.","마음이 움직인 곳을 찾아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_c#2','kor',3,2,'u6','','g3_2_kor_u6_review_c','unit_review','K3-2-u6-C5',1,'mc','auto','동생이 있는 친구가 「종이배」에서 마음이 더 가는 곳이 다른 친구와 다를 수 있는 까닭은 무엇인가요?',ARRAY['K3-2-u6-X05','K3-2-u6-X04','K3-2-u6-X03']::text[],false,'{"seq":2,"concept":"K3-2-u6-C5","difficulty":1,"kind":"mc","stem":"동생이 있는 친구가 「종이배」에서 마음이 더 가는 곳이 다른 친구와 다를 수 있는 까닭은 무엇인가요?","options":[{"t":"저마다 겪은 일과 처지가 달라 마음이 걸리는 자리가 다르기 때문에","correct":true},{"t":"한 사람만 제대로 읽었기 때문에","mis":"K3-2-u6-X05"},{"t":"감상은 아무 데서나 느껴도 되기 때문에","mis":"K3-2-u6-X04"},{"t":"이야기가 잘못 쓰였기 때문에","mis":"K3-2-u6-X03"}],"explanation":["동생과 지낸 일이 떠올라요.","그래서 눈이 가는 곳이 달라요.","겪은 일과 처지 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_c#3','kor',3,2,'u6','','g3_2_kor_u6_review_c','unit_review','K3-2-u6-C7',1,'mc','auto','“동생이 손을 꼭 잡는 곳이 뭉클했어.”라는 감상의 근거가 된 것은 무엇인가요?',ARRAY['K3-2-u6-X04']::text[],false,'{"seq":3,"concept":"K3-2-u6-C7","difficulty":1,"kind":"mc","stem":"“동생이 손을 꼭 잡는 곳이 뭉클했어.”라는 감상의 근거가 된 것은 무엇인가요?","options":[{"t":"6번 줄 — 집에 오는 길에 동생이 손을 꼭 잡았다","correct":true},{"t":"1번 줄 — 물웅덩이가 생겼다","mis":"K3-2-u6-X04"},{"t":"이 이야기를 읽은 사람 수","mis":"K3-2-u6-X04"},{"t":"이야기의 제목","mis":"K3-2-u6-X04"}],"explanation":["손을 잡는 곳을 찾아요.","6번 줄이에요.","그것이 근거예요."],"asset":{"type":"passage","lines":["1 비가 그친 뒤 운동장 구석에 물웅덩이가 생겼다.","2 동생이 종이배를 띄웠는데 바람에 그만 뒤집혔다. 동생 입술이 삐죽 나왔다.","3 나는 아무 말 없이 공책 한 장을 뜯어 배를 다시 접었다.","4 이번에는 배 바닥에 지우개를 하나 올려 두었다.","5 배는 기우뚱하더니 똑바로 섰다. 동생이 손뼉을 치며 깡충 뛰었다.","6 집에 오는 길에 동생이 내 손을 꼭 잡았다. 아무 말도 하지 않았다."],"title":"이야기 「종이배」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_c#4','kor',3,2,'u6','','g3_2_kor_u6_review_c','unit_review','K3-2-u6-C8',1,'ox','auto','인물이 아무 말을 하지 않으면 그 인물의 마음은 알 수 없어요.',ARRAY['K3-2-u6-X10']::text[],false,'{"seq":4,"concept":"K3-2-u6-C8","difficulty":1,"kind":"ox","stem":"인물이 아무 말을 하지 않으면 그 인물의 마음은 알 수 없어요.","answer":"X","reason_options":[{"t":"표정과 몸짓, 행동에도 마음이 드러나기 때문에","correct":true},{"t":"마음은 말로 한 것만 알 수 있기 때문에","mis":"K3-2-u6-X10"}],"mis":"K3-2-u6-X10","explanation":["몸이 마음을 말해요.","표정·몸짓·행동을 봐요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_c#5','kor',3,2,'u6','','g3_2_kor_u6_review_c','unit_review','K3-2-u6-C16',1,'ox','auto','「한 통의 물감」에서 물감을 아끼려던 나와 넓게 칠하고 싶던 짝 가운데 한쪽은 잘못한 거예요.',ARRAY['K3-2-u6-X16']::text[],false,'{"seq":5,"concept":"K3-2-u6-C16","difficulty":1,"kind":"ox","stem":"「한 통의 물감」에서 물감을 아끼려던 나와 넓게 칠하고 싶던 짝 가운데 한쪽은 잘못한 거예요.","answer":"X","reason_options":[{"t":"둘 다 소중히 여기는 것이 있어 부딪쳤기 때문에","correct":true},{"t":"부딪쳤다는 것은 누군가 잘못했다는 뜻이기 때문에","mis":"K3-2-u6-X16"}],"mis":"K3-2-u6-X16","explanation":["둘 다 잘못하지 않았어요.","둘 다 소중한 것이 있었어요.","그래서 X예요."],"asset":{"type":"passage","lines":["1 우리 모둠에는 하늘색 물감이 한 통뿐이었다.","2 나는 다른 모둠도 빌려 쓸 거라서 물감을 조금씩만 짜서 아껴 칠했다.","3 짝은 하늘을 크게 그리고 싶어 물감을 듬뿍 짜려다가 내 눈치를 보았다.","4 “이러면 하늘이 얼룩덜룩해지잖아.” 짝이 붓을 내려놓았다.","5 잠시 뒤 짝이 말했다. “흰색을 섞으면 양이 늘지 않을까?”","6 우리는 섞은 물감으로 하늘을 넓게 칠했고, 남은 통은 옆 모둠에 건넸다."],"title":"이야기 「한 통의 물감」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_c#6','kor',3,2,'u6','','g3_2_kor_u6_review_c','unit_review','K3-2-u6-C19',1,'ox','auto','“모둠 활동 때마다 가위를 빌리러 돌아다닌다.”는 글쓴이의 의견이에요.',ARRAY['K3-2-u6-X19']::text[],false,'{"seq":6,"concept":"K3-2-u6-C19","difficulty":1,"kind":"ox","stem":"“모둠 활동 때마다 가위를 빌리러 돌아다닌다.”는 글쓴이의 의견이에요.","answer":"X","reason_options":[{"t":"있었던 일을 적은 문장이고, 어떻게 하자는 생각이 아니기 때문에","correct":true},{"t":"글에 나온 문장은 모두 의견이기 때문에","mis":"K3-2-u6-X19"}],"mis":"K3-2-u6-X19","explanation":["본 대로 적은 문장이에요.","“하자”가 없어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_c#7','kor',3,2,'u6','','g3_2_kor_u6_review_c','unit_review','K3-2-u6-C28',1,'mc','auto','고쳐 쓰기를 하는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X29','K3-2-u6-X30','K3-2-u6-X27']::text[],false,'{"seq":7,"concept":"K3-2-u6-C28","difficulty":1,"kind":"mc","stem":"고쳐 쓰기를 하는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"내 생각이 읽는 사람에게 더 잘 전해지도록","correct":true},{"t":"고칠 곳이 없는 글만 잘 쓴 글이라서","mis":"K3-2-u6-X29"},{"t":"친구 글의 흠을 찾아 알려 주려고","mis":"K3-2-u6-X30"},{"t":"글을 더 길게 만들려고","mis":"K3-2-u6-X27"}],"explanation":["흠을 없애는 일이 아니에요.","더 잘 전하는 일이에요.","그것이 까닭이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_c#8','kor',3,2,'u6','','g3_2_kor_u6_review_c','unit_review','K3-2-u6-C40',1,'mc','auto','‘소리’ 다음에 이어질 낱말은 무엇인가요?',ARRAY['K3-2-u6-X40']::text[],false,'{"seq":8,"concept":"K3-2-u6-C40","difficulty":1,"kind":"mc","stem":"‘소리’ 다음에 이어질 낱말은 무엇인가요?","options":[{"t":"리본","correct":true},{"t":"소풍","mis":"K3-2-u6-X40"},{"t":"나리","mis":"K3-2-u6-X40"},{"t":"본보기","mis":"K3-2-u6-X40"}],"explanation":["끝 글자는 ‘리’예요.","‘리’로 시작하는 낱말이에요.","‘리본’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_c#9','kor',3,2,'u6','','g3_2_kor_u6_review_c','unit_review','K3-2-u6-C6',2,'mc','auto','“좋았어.”라고만 말한 친구의 감상을 감상답게 고친 것은 무엇인가요?',ARRAY['K3-2-u6-X07','K3-2-u6-X06','K3-2-u6-X02']::text[],false,'{"seq":9,"concept":"K3-2-u6-C6","difficulty":2,"kind":"mc","stem":"“좋았어.”라고만 말한 친구의 감상을 감상답게 고친 것은 무엇인가요?","options":[{"t":"“배가 똑바로 서는 장면에서 나도 같이 손뼉을 치고 싶었어.”","correct":true},{"t":"“진짜 진짜 좋았어.”","mis":"K3-2-u6-X07"},{"t":"“동생이 배를 띄웠는데 뒤집혔대.”","mis":"K3-2-u6-X06"},{"t":"“이 이야기는 구십 점이야.”","mis":"K3-2-u6-X02"}],"explanation":["어느 장면인지 넣어요.","어떤 마음인지 넣어요.","둘을 이어요."],"asset":{"type":"passage","lines":["1 비가 그친 뒤 운동장 구석에 물웅덩이가 생겼다.","2 동생이 종이배를 띄웠는데 바람에 그만 뒤집혔다. 동생 입술이 삐죽 나왔다.","3 나는 아무 말 없이 공책 한 장을 뜯어 배를 다시 접었다.","4 이번에는 배 바닥에 지우개를 하나 올려 두었다.","5 배는 기우뚱하더니 똑바로 섰다. 동생이 손뼉을 치며 깡충 뛰었다.","6 집에 오는 길에 동생이 내 손을 꼭 잡았다. 아무 말도 하지 않았다."],"title":"이야기 「종이배」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_c#10','kor',3,2,'u6','','g3_2_kor_u6_review_c','unit_review','K3-2-u6-C13',2,'mc','auto','「종이배」 감상을 친구와 나누면 좋은 점은 무엇인가요?',ARRAY['K3-2-u6-X14','K3-2-u6-X02']::text[],false,'{"seq":10,"concept":"K3-2-u6-C13","difficulty":2,"kind":"mc","stem":"「종이배」 감상을 친구와 나누면 좋은 점은 무엇인가요?","options":[{"t":"내가 못 보고 지나친 곳을 알게 된다","correct":true},{"t":"내 감상이 정답인지 확인받는다","mis":"K3-2-u6-X14"},{"t":"친구와 같은 곳을 느꼈는지 맞춰 본다","mis":"K3-2-u6-X14"},{"t":"누구 감상이 더 높은 점수인지 가린다","mis":"K3-2-u6-X02"}],"explanation":["정답을 확인하는 게 아니에요.","못 본 곳을 알게 돼요.","작품이 넓어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_c#11','kor',3,2,'u6','','g3_2_kor_u6_review_c','unit_review','K3-2-u6-C17',2,'error','auto','「한 통의 물감」의 인물에게 물어볼 질문을 만들었어요. 알맞지 않은 질문을 만든 친구는 누구인가요?',ARRAY['K3-2-u6-X17']::text[],false,'{"seq":11,"concept":"K3-2-u6-C17","difficulty":2,"kind":"error","stem":"「한 통의 물감」의 인물에게 물어볼 질문을 만들었어요. 알맞지 않은 질문을 만든 친구는 누구인가요?","options":[{"t":"친구 다 — 「하늘색 물감은 어느 가게에서 샀어요?」","correct":true,"mis_target":"K3-2-u6-X17"},{"t":"친구 가 — 「왜 물감을 조금씩만 짰어요?」","mis":"K3-2-u6-X17"},{"t":"친구 나 — 「흰색을 섞자고 한 까닭은 무엇이었어요?」","mis":"K3-2-u6-X17"}],"explanation":["가게는 이야기에 없어요.","인물이 답할 수 없어요.","친구 다가 알맞지 않아요."],"asset":{"type":"passage","lines":["1 우리 모둠에는 하늘색 물감이 한 통뿐이었다.","2 나는 다른 모둠도 빌려 쓸 거라서 물감을 조금씩만 짜서 아껴 칠했다.","3 짝은 하늘을 크게 그리고 싶어 물감을 듬뿍 짜려다가 내 눈치를 보았다.","4 “이러면 하늘이 얼룩덜룩해지잖아.” 짝이 붓을 내려놓았다.","5 잠시 뒤 짝이 말했다. “흰색을 섞으면 양이 늘지 않을까?”","6 우리는 섞은 물감으로 하늘을 넓게 칠했고, 남은 통은 옆 모둠에 건넸다."],"title":"이야기 「한 통의 물감」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_c#12','kor',3,2,'u6','','g3_2_kor_u6_review_c','unit_review','K3-2-u6-C15',2,'sa','auto','「한 통의 물감」에서 양을 늘리려고 섞은 물감의 색을 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"K3-2-u6-C15","difficulty":2,"kind":"sa","stem":"「한 통의 물감」에서 양을 늘리려고 섞은 물감의 색을 쓰세요.","answer":["흰색","흰"],"explanation":["5번 줄을 봐요.","짝이 말한 색이에요.","‘흰색’이에요."],"asset":{"type":"passage","lines":["1 우리 모둠에는 하늘색 물감이 한 통뿐이었다.","2 나는 다른 모둠도 빌려 쓸 거라서 물감을 조금씩만 짜서 아껴 칠했다.","3 짝은 하늘을 크게 그리고 싶어 물감을 듬뿍 짜려다가 내 눈치를 보았다.","4 “이러면 하늘이 얼룩덜룩해지잖아.” 짝이 붓을 내려놓았다.","5 잠시 뒤 짝이 말했다. “흰색을 섞으면 양이 늘지 않을까?”","6 우리는 섞은 물감으로 하늘을 넓게 칠했고, 남은 통은 옆 모둠에 건넸다."],"title":"이야기 「한 통의 물감」"},"mis":"K3-2-u6-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_c#13','kor',3,2,'u6','','g3_2_kor_u6_review_c','unit_review','K3-2-u6-C22',2,'mc','auto','「모둠마다 준비물 바구니를 두자」에 이유를 하나 더 붙인다면 무엇이 알맞을까요?',ARRAY['K3-2-u6-X23','K3-2-u6-X22','K3-2-u6-X25']::text[],false,'{"seq":13,"concept":"K3-2-u6-C22","difficulty":2,"kind":"mc","stem":"「모둠마다 준비물 바구니를 두자」에 이유를 하나 더 붙인다면 무엇이 알맞을까요?","options":[{"t":"셋째, 모둠 친구들이 함께 물건을 챙기는 습관이 생기기 때문이다","correct":true},{"t":"셋째, 내가 바구니를 제일 잘 고르기 때문이다","mis":"K3-2-u6-X23"},{"t":"셋째, 가위는 날카롭기 때문이다","mis":"K3-2-u6-X22"},{"t":"셋째, 돌아다니지 않아 바로 시작할 수 있기 때문이다","mis":"K3-2-u6-X25"}],"explanation":["의견과 이어져야 해요.","앞 이유와 겹치면 안 돼요.","습관이 생기는 것이 알맞아요."],"asset":{"type":"passage","lines":["1 모둠 활동을 할 때마다 가위와 풀을 빌리러 돌아다니느라 시간이 걸린다.","2 그래서 모둠마다 준비물 바구니를 두면 좋겠다.","3 첫째, 돌아다니지 않아도 되어 활동을 바로 시작할 수 있기 때문이다.","4 둘째, 물건마다 돌아갈 자리가 생겨 잃어버리는 일이 줄기 때문이다.","5 모둠 바구니를 함께 마련해 보자."],"title":"글 「모둠마다 준비물 바구니를 두자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_c#14','kor',3,2,'u6','','g3_2_kor_u6_review_c','unit_review','K3-2-u6-C30',2,'ox','auto','「실내화를 아무렇게나 두는 친구 이름」은 의견을 제시하는 글로 다룰 만한 문제예요.',ARRAY['K3-2-u6-X32']::text[],false,'{"seq":14,"concept":"K3-2-u6-C30","difficulty":2,"kind":"ox","stem":"「실내화를 아무렇게나 두는 친구 이름」은 의견을 제시하는 글로 다룰 만한 문제예요.","answer":"X","reason_options":[{"t":"누군가를 탓하는 일이라 함께 바꿀 문제가 아니기 때문에","correct":true},{"t":"이름을 적어야 문제가 또렷해지기 때문에","mis":"K3-2-u6-X32"}],"mis":"K3-2-u6-X32","explanation":["이름을 적으면 탓하는 글이 돼요.","함께 바꿀 일을 골라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_c#15','kor',3,2,'u6','','g3_2_kor_u6_review_c','unit_review','K3-2-u6-C33',2,'match','auto','「빈 교실의 불을 끄자」의 문장이 뼈대의 어느 자리인지 이으세요.','{}'::text[],false,'{"seq":15,"concept":"K3-2-u6-C33","difficulty":2,"kind":"match","stem":"「빈 교실의 불을 끄자」의 문장이 뼈대의 어느 자리인지 이으세요.","pairs":[{"l":"비어 있는 교실에 불이 켜져 있다","r":"문제 상황"},{"l":"마지막 사람이 불을 끄자","r":"의견"},{"l":"함께 지켜 보자","r":"맺음"}],"mis":"K3-2-u6-X21","explanation":["불편한 일 · 하자 · 함께 해 보자예요.","하나씩 짚어요.","세 짝을 이어요."],"asset":{"type":"passage","lines":["1 체육 시간에 교실이 비어 있는데도 불이 켜져 있을 때가 많다.","2 그래서 교실을 나갈 때 마지막 사람이 불을 끄면 좋겠다.","3 첫째, 쓰지 않는 전기를 아낄 수 있기 때문이다.","4 둘째, 내가 우리 반에서 스위치에 손이 제일 잘 닿기 때문이다.","5 교실을 나설 때 불 끄는 일을 함께 지켜 보자."],"title":"글 「빈 교실의 불을 끄자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_c#16','kor',3,2,'u6','','g3_2_kor_u6_review_c','unit_review','K3-2-u6-C35',2,'ox','auto','“떠들지 마!”처럼 의견만 크게 쓴 팻말이 가장 잘 만든 팻말이에요.',ARRAY['K3-2-u6-X34']::text[],false,'{"seq":16,"concept":"K3-2-u6-C35","difficulty":2,"kind":"ox","stem":"“떠들지 마!”처럼 의견만 크게 쓴 팻말이 가장 잘 만든 팻말이에요.","answer":"X","reason_options":[{"t":"이유가 함께 있어야 읽는 사람이 고개를 끄덕이기 때문에","correct":true},{"t":"팻말은 짧게 명령해야 잘 지키기 때문에","mis":"K3-2-u6-X34"}],"mis":"K3-2-u6-X34","explanation":["명령만 있으면 서운해요.","이유가 함께 가요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_c#17','kor',3,2,'u6','','g3_2_kor_u6_review_c','unit_review','K3-2-u6-C4',3,'mc','auto','「종이배」 감상으로 받아들이기 어려운 것은 무엇인가요?',ARRAY['K3-2-u6-X03']::text[],false,'{"seq":17,"concept":"K3-2-u6-C4","difficulty":3,"kind":"mc","stem":"「종이배」 감상으로 받아들이기 어려운 것은 무엇인가요?","options":[{"t":"“동생이 배를 강물에 띄우는 곳이 멋졌어.”","correct":true},{"t":"“배가 뒤집히는 곳이 웃겼어.”","mis":"K3-2-u6-X03"},{"t":"“손을 잡는 곳이 뭉클했어.”","mis":"K3-2-u6-X03"},{"t":"“배가 서는 곳이 신기했어.”","mis":"K3-2-u6-X03"}],"explanation":["감상은 달라도 돼요.","그래도 이야기 안에 있어야 해요.","강물은 없어요."],"asset":{"type":"passage","lines":["1 비가 그친 뒤 운동장 구석에 물웅덩이가 생겼다.","2 동생이 종이배를 띄웠는데 바람에 그만 뒤집혔다. 동생 입술이 삐죽 나왔다.","3 나는 아무 말 없이 공책 한 장을 뜯어 배를 다시 접었다.","4 이번에는 배 바닥에 지우개를 하나 올려 두었다.","5 배는 기우뚱하더니 똑바로 섰다. 동생이 손뼉을 치며 깡충 뛰었다.","6 집에 오는 길에 동생이 내 손을 꼭 잡았다. 아무 말도 하지 않았다."],"title":"이야기 「종이배」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_c#18','kor',3,2,'u6','','g3_2_kor_u6_review_c','unit_review','K3-2-u6-C24',3,'ox','auto','한 문제에는 정답 의견이 하나뿐이라서 나와 다른 의견은 틀린 의견이에요.',ARRAY['K3-2-u6-X24']::text[],false,'{"seq":18,"concept":"K3-2-u6-C24","difficulty":3,"kind":"ox","stem":"한 문제에는 정답 의견이 하나뿐이라서 나와 다른 의견은 틀린 의견이에요.","answer":"X","reason_options":[{"t":"같은 문제에도 여러 의견이 나올 수 있고, 이유가 받쳐 주는지로 재기 때문에","correct":true},{"t":"의견이 다르면 둘 가운데 하나는 틀려야 하기 때문에","mis":"K3-2-u6-X24"}],"mis":"K3-2-u6-X24","explanation":["한 문제에 길은 여럿이에요.","이유로 재요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_c#19','kor',3,2,'u6','','g3_2_kor_u6_review_c','unit_review','K3-2-u6-C29',3,'mc','auto','「빈 교실의 불을 끄자」를 쓴 친구에게 해 줄 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X30','K3-2-u6-X29']::text[],false,'{"seq":19,"concept":"K3-2-u6-C29","difficulty":3,"kind":"mc","stem":"「빈 교실의 불을 끄자」를 쓴 친구에게 해 줄 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“문제 상황이 잘 보여. 4번 줄은 불 끄기와 이어지지 않으니 다른 이유로 바꾸면 좋겠어.”","correct":true},{"t":"“틀린 데가 있으니 처음부터 다시 써.”","mis":"K3-2-u6-X30"},{"t":"“고칠 곳이 하나도 없어.”","mis":"K3-2-u6-X29"},{"t":"“4번 줄 이상해.”","mis":"K3-2-u6-X30"}],"explanation":["잘된 곳을 먼저 말해요.","고칠 곳을 짚어요.","까닭을 붙여요."],"asset":{"type":"passage","lines":["1 체육 시간에 교실이 비어 있는데도 불이 켜져 있을 때가 많다.","2 그래서 교실을 나갈 때 마지막 사람이 불을 끄면 좋겠다.","3 첫째, 쓰지 않는 전기를 아낄 수 있기 때문이다.","4 둘째, 내가 우리 반에서 스위치에 손이 제일 잘 닿기 때문이다.","5 교실을 나설 때 불 끄는 일을 함께 지켜 보자."],"title":"글 「빈 교실의 불을 끄자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_c#20','kor',3,2,'u6','','g3_2_kor_u6_review_c','unit_review','K3-2-u6-C14',3,'mc','auto','「한 통의 물감」에서 내가 나누어 쓰기를 소중히 여겼다는 것을 알 수 있는 행동은 무엇인가요?',ARRAY['K3-2-u6-X15']::text[],false,'{"seq":20,"concept":"K3-2-u6-C14","difficulty":3,"kind":"mc","stem":"「한 통의 물감」에서 내가 나누어 쓰기를 소중히 여겼다는 것을 알 수 있는 행동은 무엇인가요?","options":[{"t":"남은 통을 옆 모둠에 건넨 것","correct":true},{"t":"하늘을 넓게 칠한 것","mis":"K3-2-u6-X15"},{"t":"짝이 붓을 내려놓은 것","mis":"K3-2-u6-X15"},{"t":"물감이 하늘색인 것","mis":"K3-2-u6-X15"}],"explanation":["행동에서 읽어 내요.","옆 모둠에 건넸어요.","나누어 쓴 거예요."],"asset":{"type":"passage","lines":["1 우리 모둠에는 하늘색 물감이 한 통뿐이었다.","2 나는 다른 모둠도 빌려 쓸 거라서 물감을 조금씩만 짜서 아껴 칠했다.","3 짝은 하늘을 크게 그리고 싶어 물감을 듬뿍 짜려다가 내 눈치를 보았다.","4 “이러면 하늘이 얼룩덜룩해지잖아.” 짝이 붓을 내려놓았다.","5 잠시 뒤 짝이 말했다. “흰색을 섞으면 양이 늘지 않을까?”","6 우리는 섞은 물감으로 하늘을 넓게 칠했고, 남은 통은 옆 모둠에 건넸다."],"title":"이야기 「한 통의 물감」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_c#21','kor',3,2,'u6','','g3_2_kor_u6_review_c','unit_review','K3-2-u6-C34',3,'error','auto','「빈 교실의 불을 끄자」를 점검표로 재었어요. 잘못 잰 친구는 누구인가요?',ARRAY['K3-2-u6-X22','K3-2-u6-X23']::text[],false,'{"seq":21,"concept":"K3-2-u6-C34","difficulty":3,"kind":"error","stem":"「빈 교실의 불을 끄자」를 점검표로 재었어요. 잘못 잰 친구는 누구인가요?","options":[{"t":"친구 나 — 「이유가 둘이니 이유는 다 괜찮아.」","correct":true,"mis_target":"K3-2-u6-X22"},{"t":"친구 가 — 「문제 상황에 어울리는 의견이야.」","mis":"K3-2-u6-X22"},{"t":"친구 다 — 「4번 줄은 의견을 받쳐 주지 못해.」","mis":"K3-2-u6-X23"}],"explanation":["개수만 세면 안 돼요.","받쳐 주는지 하나씩 대어 봐요.","친구 나가 잘못 쟀어요."],"asset":{"type":"passage","lines":["1 체육 시간에 교실이 비어 있는데도 불이 켜져 있을 때가 많다.","2 그래서 교실을 나갈 때 마지막 사람이 불을 끄면 좋겠다.","3 첫째, 쓰지 않는 전기를 아낄 수 있기 때문이다.","4 둘째, 내가 우리 반에서 스위치에 손이 제일 잘 닿기 때문이다.","5 교실을 나설 때 불 끄는 일을 함께 지켜 보자."],"title":"글 「빈 교실의 불을 끄자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_c#22','kor',3,2,'u6','','g3_2_kor_u6_review_c','unit_review','K3-2-u6-C13',3,'error','auto','「종이배」 감상을 나눈 뒤 말했어요. 나누는 까닭을 잘못 안 친구는 누구인가요?',ARRAY['K3-2-u6-X14']::text[],false,'{"seq":22,"concept":"K3-2-u6-C13","difficulty":3,"kind":"error","stem":"「종이배」 감상을 나눈 뒤 말했어요. 나누는 까닭을 잘못 안 친구는 누구인가요?","options":[{"t":"친구 다 — 「내 감상이랑 같은지 맞춰 보니 내가 맞았어.」","correct":true,"mis_target":"K3-2-u6-X14"},{"t":"친구 가 — 「지우개 장면은 못 봤는데 다시 읽어 봐야지.」","mis":"K3-2-u6-X14"},{"t":"친구 나 — 「친구 말 덕분에 동생 마음이 더 보였어.」","mis":"K3-2-u6-X14"}],"explanation":["맞춰 보는 게 아니에요.","못 본 곳을 알게 돼요.","친구 다가 잘못 알았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_c#23','kor',3,2,'u6','','g3_2_kor_u6_review_c','unit_review','K3-2-u6-C16',4,'mc','auto','「한 통의 물감」과 「같은 자리」의 공통점으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X16','K3-2-u6-X18']::text[],false,'{"seq":23,"concept":"K3-2-u6-C16","difficulty":4,"kind":"mc","stem":"「한 통의 물감」과 「같은 자리」의 공통점으로 알맞은 것은 무엇인가요?","options":[{"t":"두 사람 모두 소중히 여기는 것이 있어 부딪쳤고, 둘 다 지킬 길을 찾았다","correct":true},{"t":"둘 다 한 사람이 잘못해서 벌을 받았다","mis":"K3-2-u6-X16"},{"t":"둘 다 부딪친 일을 끝까지 말하지 않았다","mis":"K3-2-u6-X18"},{"t":"둘 다 선생님이 누가 옳은지 정해 주었다","mis":"K3-2-u6-X16"}],"explanation":["물감 · 화분이에요.","둘 다 물러설 수 없었어요.","둘 다 지킬 길을 찾았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_c#24','kor',3,2,'u6','','g3_2_kor_u6_review_c','unit_review','K3-2-u6-C16',4,'essay','teacher','「한 통의 물감」의 두 사람이 소중히 여긴 것을 말과 행동을 근거로 각각 쓰고, 「누가 옳았을까?」에 어떻게 답할지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u6-C16","difficulty":4,"kind":"essay","stem":"「한 통의 물감」의 두 사람이 소중히 여긴 것을 말과 행동을 근거로 각각 쓰고, 「누가 옳았을까?」에 어떻게 답할지 쓰세요.","answer_guide":{"answer":"예: 나는 다른 모둠도 빌려 쓸 거라서 물감을 조금씩 짜고 남은 통을 옆 모둠에 건넨 것으로 보아 함께 쓰는 물건을 나누는 것을 소중히 여겼다. 짝은 하늘을 크게 그리고 싶어 했고 “얼룩덜룩해지잖아.”라고 한 것으로 보아 그림을 마음먹은 대로 그리는 것을 소중히 여겼다. 둘 다 소중히 여기는 것이 있었으므로 한쪽을 고를 물음이 아니다.","scoring_points":["나의 소중한 것을 근거와 함께 썼는가","짝의 소중한 것을 근거와 함께 썼는가","한쪽을 고를 물음이 아니라고 썼는가"]},"explanation":["행동이 근거예요.","말도 근거예요.","한쪽을 고르지 않아요."],"asset":{"type":"passage","lines":["1 우리 모둠에는 하늘색 물감이 한 통뿐이었다.","2 나는 다른 모둠도 빌려 쓸 거라서 물감을 조금씩만 짜서 아껴 칠했다.","3 짝은 하늘을 크게 그리고 싶어 물감을 듬뿍 짜려다가 내 눈치를 보았다.","4 “이러면 하늘이 얼룩덜룩해지잖아.” 짝이 붓을 내려놓았다.","5 잠시 뒤 짝이 말했다. “흰색을 섞으면 양이 늘지 않을까?”","6 우리는 섞은 물감으로 하늘을 넓게 칠했고, 남은 통은 옆 모둠에 건넸다."],"title":"이야기 「한 통의 물감」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_c#25','kor',3,2,'u6','','g3_2_kor_u6_review_c','unit_review','K3-2-u6-C35',4,'essay','teacher','㉮ 바구니 글의 의견을 손 팻말로 만든다면 무엇이라고 쓸지 쓰고, 의견과 이유를 함께 담은 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u6-C35","difficulty":4,"kind":"essay","stem":"㉮ 바구니 글의 의견을 손 팻말로 만든다면 무엇이라고 쓸지 쓰고, 의견과 이유를 함께 담은 까닭을 쓰세요.","answer_guide":{"answer":"예: “모둠 바구니에 준비물을 넣어 두어요. 빌리러 다니지 않고 바로 시작해요.” 의견만 크게 쓰면 명령처럼 느껴지고, 이유만 길면 무엇을 하자는지 안 보인다. 의견과 이유가 함께 있어야 읽는 사람이 고개를 끄덕이고 함께 지키고 싶어진다.","scoring_points":["팻말에 의견을 썼는가","팻말에 이유를 썼는가","함께 담은 까닭을 썼는가"]},"explanation":["의견을 크게 써요.","이유를 한 줄 붙여요.","함께 가야 해요."],"asset":{"type":"passage","lines":["문제 — 모둠 활동 때마다 준비물을 빌리러 돌아다닌다.","㉮ 모둠마다 준비물 바구니를 두자.","   바로 시작할 수 있고, 물건마다 돌아갈 자리가 생기기 때문이다.","㉯ 모둠마다 준비물 당번을 정해 활동 전에 한꺼번에 받아 오자.","   한 사람이 챙기니 빠뜨리는 것이 없고, 줄을 서지 않아도 되기 때문이다."],"title":"같은 문제를 두고 쓴 두 글 ㉮ 바구니 · ㉯ 당번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_d#1','kor',3,2,'u6','','g3_2_kor_u6_review_d','unit_review','K3-2-u6-C3',1,'mc','auto','「종이배」를 읽고 “배가 바람에 뒤집히는 데서 웃음이 났어.”라고 한 것은 재미와 감동 가운데 무엇을 말한 것인가요?',ARRAY['K3-2-u6-X08','K3-2-u6-X06']::text[],false,'{"seq":1,"concept":"K3-2-u6-C3","difficulty":1,"kind":"mc","stem":"「종이배」를 읽고 “배가 바람에 뒤집히는 데서 웃음이 났어.”라고 한 것은 재미와 감동 가운데 무엇을 말한 것인가요?","options":[{"t":"재미","correct":true},{"t":"감동","mis":"K3-2-u6-X08"},{"t":"둘 다 아니다","mis":"K3-2-u6-X08"},{"t":"줄거리","mis":"K3-2-u6-X06"}],"explanation":["웃음이 났어요.","웃음이 나는 곳은 재미예요.","‘재미’예요."],"asset":{"type":"speech","turns":[{"who":"㉮","text":"배가 바람에 뒤집히는 데서 웃음이 났어."},{"who":"㉯","text":"동생이 말없이 손을 꼭 잡는 곳이 뭉클했어."},{"who":"㉰","text":"지우개를 올리니 배가 서는 게 신기했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_d#2','kor',3,2,'u6','','g3_2_kor_u6_review_d','unit_review','K3-2-u6-C4',1,'error','auto','「종이배」 감상을 듣고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u6-X03','K3-2-u6-X14']::text[],false,'{"seq":2,"concept":"K3-2-u6-C4","difficulty":1,"kind":"error","stem":"「종이배」 감상을 듣고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「너는 나랑 다른 곳을 골랐으니 틀렸어.」","correct":true,"mis_target":"K3-2-u6-X03"},{"t":"친구 가 — 「너는 어디를 보고 그렇게 느꼈어?」","mis":"K3-2-u6-X03"},{"t":"친구 다 — 「나는 못 본 곳이라 다시 읽어 볼래.」","mis":"K3-2-u6-X14"}],"explanation":["다른 곳을 골라도 돼요.","어디를 보았는지 물어요.","친구 나가 잘못 말했어요."],"asset":{"type":"speech","turns":[{"who":"㉮","text":"배가 바람에 뒤집히는 데서 웃음이 났어."},{"who":"㉯","text":"동생이 말없이 손을 꼭 잡는 곳이 뭉클했어."},{"who":"㉰","text":"지우개를 올리니 배가 서는 게 신기했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_d#3','kor',3,2,'u6','','g3_2_kor_u6_review_d','unit_review','K3-2-u6-C6',1,'ox','auto','“그냥 좋았어.”라고만 말해도 감상을 다 말한 거예요.',ARRAY['K3-2-u6-X07']::text[],false,'{"seq":3,"concept":"K3-2-u6-C6","difficulty":1,"kind":"ox","stem":"“그냥 좋았어.”라고만 말해도 감상을 다 말한 거예요.","answer":"X","reason_options":[{"t":"어느 장면에서 어떤 마음이 들었는지 이어 말해야 친구가 내 감상을 따라올 수 있기 때문에","correct":true},{"t":"느낌만 말하면 감상은 다 말한 것이기 때문에","mis":"K3-2-u6-X07"}],"mis":"K3-2-u6-X07","explanation":["어느 장면인지 빠졌어요.","친구가 따라올 수 없어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_d#4','kor',3,2,'u6','','g3_2_kor_u6_review_d','unit_review','K3-2-u6-C9',1,'mc','auto','「종이배」 3번 줄에서 “나”가 아무 말 없이 배를 다시 접은 행동으로 짐작할 수 있는 것은 무엇인가요?',ARRAY['K3-2-u6-X10','K3-2-u6-X11']::text[],false,'{"seq":4,"concept":"K3-2-u6-C9","difficulty":1,"kind":"mc","stem":"「종이배」 3번 줄에서 “나”가 아무 말 없이 배를 다시 접은 행동으로 짐작할 수 있는 것은 무엇인가요?","options":[{"t":"속상한 동생을 말 대신 행동으로 달래 주고 싶었다","correct":true},{"t":"동생에게 화가 나서 말을 하지 않았다","mis":"K3-2-u6-X10"},{"t":"공책이 필요 없어서 뜯었다","mis":"K3-2-u6-X10"},{"t":"종이배 접기 시험을 보고 있었다","mis":"K3-2-u6-X11"}],"explanation":["바로 앞에서 동생 입술이 나왔어요.","말 대신 배를 접었어요.","달래 주고 싶었던 거예요."],"asset":{"type":"passage","lines":["1 비가 그친 뒤 운동장 구석에 물웅덩이가 생겼다.","2 동생이 종이배를 띄웠는데 바람에 그만 뒤집혔다. 동생 입술이 삐죽 나왔다.","3 나는 아무 말 없이 공책 한 장을 뜯어 배를 다시 접었다.","4 이번에는 배 바닥에 지우개를 하나 올려 두었다.","5 배는 기우뚱하더니 똑바로 섰다. 동생이 손뼉을 치며 깡충 뛰었다.","6 집에 오는 길에 동생이 내 손을 꼭 잡았다. 아무 말도 하지 않았다."],"title":"이야기 「종이배」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_d#5','kor',3,2,'u6','','g3_2_kor_u6_review_d','unit_review','K3-2-u6-C16',1,'mc','auto','「한 통의 물감」의 두 사람 가운데 누가 옳았을까요?',ARRAY['K3-2-u6-X16']::text[],false,'{"seq":5,"concept":"K3-2-u6-C16","difficulty":1,"kind":"mc","stem":"「한 통의 물감」의 두 사람 가운데 누가 옳았을까요?","options":[{"t":"둘 다 소중히 여기는 것이 있었다. 한쪽을 고를 물음이 아니다","correct":true},{"t":"물감을 아낀 내가 옳았다","mis":"K3-2-u6-X16"},{"t":"넓게 칠하려던 짝이 옳았다","mis":"K3-2-u6-X16"},{"t":"붓을 먼저 내려놓은 짝이 잘못했다","mis":"K3-2-u6-X16"}],"explanation":["한쪽이 옳다고 하면","다른 쪽의 소중한 것은요?","둘 다 있었어요."],"asset":{"type":"passage","lines":["1 우리 모둠에는 하늘색 물감이 한 통뿐이었다.","2 나는 다른 모둠도 빌려 쓸 거라서 물감을 조금씩만 짜서 아껴 칠했다.","3 짝은 하늘을 크게 그리고 싶어 물감을 듬뿍 짜려다가 내 눈치를 보았다.","4 “이러면 하늘이 얼룩덜룩해지잖아.” 짝이 붓을 내려놓았다.","5 잠시 뒤 짝이 말했다. “흰색을 섞으면 양이 늘지 않을까?”","6 우리는 섞은 물감으로 하늘을 넓게 칠했고, 남은 통은 옆 모둠에 건넸다."],"title":"이야기 「한 통의 물감」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_d#6','kor',3,2,'u6','','g3_2_kor_u6_review_d','unit_review','K3-2-u6-C20',1,'blank','auto','의견을 제시하는 글은 문제 상황, 의견, (　)의 세 부분으로 이루어져요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u6-X21']::text[],false,'{"seq":6,"concept":"K3-2-u6-C20","difficulty":1,"kind":"blank","stem":"의견을 제시하는 글은 문제 상황, 의견, (　)의 세 부분으로 이루어져요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"이유","correct":true},{"t":"줄거리","mis":"K3-2-u6-X21"},{"t":"점수","mis":"K3-2-u6-X21"},{"t":"제목","mis":"K3-2-u6-X21"}],"explanation":["의견을 받쳐 줘요.","“왜냐하면”으로 시작해요.","‘이유’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_d#7','kor',3,2,'u6','','g3_2_kor_u6_review_d','unit_review','K3-2-u6-C27',1,'mc','auto','「빈 교실의 불을 끄자」에서 의견과 이어지지 않는 이유가 든 줄은 몇 번인가요?',ARRAY['K3-2-u6-X22']::text[],false,'{"seq":7,"concept":"K3-2-u6-C27","difficulty":1,"kind":"mc","stem":"「빈 교실의 불을 끄자」에서 의견과 이어지지 않는 이유가 든 줄은 몇 번인가요?","options":[{"t":"4번 줄","correct":true},{"t":"2번 줄","mis":"K3-2-u6-X22"},{"t":"3번 줄","mis":"K3-2-u6-X22"},{"t":"5번 줄","mis":"K3-2-u6-X22"}],"explanation":["스위치에 손이 잘 닿는다는 줄이에요.","불 끄자는 의견과 이어지지 않아요.","4번 줄이에요."],"asset":{"type":"passage","lines":["1 체육 시간에 교실이 비어 있는데도 불이 켜져 있을 때가 많다.","2 그래서 교실을 나갈 때 마지막 사람이 불을 끄면 좋겠다.","3 첫째, 쓰지 않는 전기를 아낄 수 있기 때문이다.","4 둘째, 내가 우리 반에서 스위치에 손이 제일 잘 닿기 때문이다.","5 교실을 나설 때 불 끄는 일을 함께 지켜 보자."],"title":"글 「빈 교실의 불을 끄자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_d#8','kor',3,2,'u6','','g3_2_kor_u6_review_d','unit_review','K3-2-u6-C41',1,'mc','auto','ㅞ가 든 낱말을 바르게 쓴 것은 무엇인가요?',ARRAY['K3-2-u6-X41']::text[],false,'{"seq":8,"concept":"K3-2-u6-C41","difficulty":1,"kind":"mc","stem":"ㅞ가 든 낱말을 바르게 쓴 것은 무엇인가요?","options":[{"t":"스웨터","correct":true},{"t":"스워터","mis":"K3-2-u6-X41"},{"t":"스위터","mis":"K3-2-u6-X41"},{"t":"스왜터","mis":"K3-2-u6-X41"}],"explanation":["ㅜ 옆에 ㅔ가 붙어요.","ㅞ예요.","‘스웨터’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_d#9','kor',3,2,'u6','','g3_2_kor_u6_review_d','unit_review','K3-2-u6-C7',2,'error','auto','「종이배」 감상을 말했어요. 근거를 이야기에서 찾을 수 없는 친구는 누구인가요?',ARRAY['K3-2-u6-X04']::text[],false,'{"seq":9,"concept":"K3-2-u6-C7","difficulty":2,"kind":"error","stem":"「종이배」 감상을 말했어요. 근거를 이야기에서 찾을 수 없는 친구는 누구인가요?","options":[{"t":"친구 다 — 「동생이 배를 바다에 띄우는 곳이 멋졌어.」","correct":true,"mis_target":"K3-2-u6-X04"},{"t":"친구 가 — 「입술이 삐죽 나오는 곳이 귀여웠어.」","mis":"K3-2-u6-X04"},{"t":"친구 나 — 「아무 말 없이 다시 접는 곳이 따뜻했어.」","mis":"K3-2-u6-X04"}],"explanation":["배는 물웅덩이에 띄웠어요.","바다는 이야기에 없어요.","친구 다는 근거가 없어요."],"asset":{"type":"passage","lines":["1 비가 그친 뒤 운동장 구석에 물웅덩이가 생겼다.","2 동생이 종이배를 띄웠는데 바람에 그만 뒤집혔다. 동생 입술이 삐죽 나왔다.","3 나는 아무 말 없이 공책 한 장을 뜯어 배를 다시 접었다.","4 이번에는 배 바닥에 지우개를 하나 올려 두었다.","5 배는 기우뚱하더니 똑바로 섰다. 동생이 손뼉을 치며 깡충 뛰었다.","6 집에 오는 길에 동생이 내 손을 꼭 잡았다. 아무 말도 하지 않았다."],"title":"이야기 「종이배」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_d#10','kor',3,2,'u6','','g3_2_kor_u6_review_d','unit_review','K3-2-u6-C11',2,'ox','auto','작품을 감상하는 방법은 줄거리를 차례대로 따라가는 한 가지뿐이에요.',ARRAY['K3-2-u6-X12']::text[],false,'{"seq":10,"concept":"K3-2-u6-C11","difficulty":2,"kind":"ox","stem":"작품을 감상하는 방법은 줄거리를 차례대로 따라가는 한 가지뿐이에요.","answer":"X","reason_options":[{"t":"표정에 주의하거나, 장면을 상상하거나, 내 일과 이어 보는 등 길이 여럿이기 때문에","correct":true},{"t":"감상 방법이 하나여야 모두 같은 감상을 하기 때문에","mis":"K3-2-u6-X12"}],"mis":"K3-2-u6-X12","explanation":["감상하는 길은 여럿이에요.","그래서 감상도 여럿이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_d#11','kor',3,2,'u6','','g3_2_kor_u6_review_d','unit_review','K3-2-u6-C18',2,'ox','auto','친구와 부딪친 일은 다시 다투지 않도록 덮어 두고 말하지 않는 것이 가장 좋아요.',ARRAY['K3-2-u6-X18']::text[],false,'{"seq":11,"concept":"K3-2-u6-C18","difficulty":2,"kind":"ox","stem":"친구와 부딪친 일은 다시 다투지 않도록 덮어 두고 말하지 않는 것이 가장 좋아요.","answer":"X","reason_options":[{"t":"서로 무엇을 소중히 여겼는지 말해야 둘 다 지킬 길을 찾을 수 있기 때문에","correct":true},{"t":"말을 꺼내면 누가 잘못했는지 가려야 하기 때문에","mis":"K3-2-u6-X18"}],"mis":"K3-2-u6-X18","explanation":["덮어 두면 길이 안 보여요.","소중한 것을 말해 봐요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_d#12','kor',3,2,'u6','','g3_2_kor_u6_review_d','unit_review','K3-2-u6-C15',2,'mc','auto','「한 통의 물감」에서 내가 물감을 조금씩만 짠 까닭은 무엇인가요?',ARRAY['K3-2-u6-X11','K3-2-u6-X16']::text[],false,'{"seq":12,"concept":"K3-2-u6-C15","difficulty":2,"kind":"mc","stem":"「한 통의 물감」에서 내가 물감을 조금씩만 짠 까닭은 무엇인가요?","options":[{"t":"다른 모둠도 빌려 쓸 물감이라서","correct":true},{"t":"하늘색을 싫어해서","mis":"K3-2-u6-X11"},{"t":"짝을 골탕 먹이려고","mis":"K3-2-u6-X16"},{"t":"물감이 굳어서","mis":"K3-2-u6-X11"}],"explanation":["2번 줄을 봐요.","“다른 모둠도 빌려 쓸 거라서”예요.","나누려던 거예요."],"asset":{"type":"passage","lines":["1 우리 모둠에는 하늘색 물감이 한 통뿐이었다.","2 나는 다른 모둠도 빌려 쓸 거라서 물감을 조금씩만 짜서 아껴 칠했다.","3 짝은 하늘을 크게 그리고 싶어 물감을 듬뿍 짜려다가 내 눈치를 보았다.","4 “이러면 하늘이 얼룩덜룩해지잖아.” 짝이 붓을 내려놓았다.","5 잠시 뒤 짝이 말했다. “흰색을 섞으면 양이 늘지 않을까?”","6 우리는 섞은 물감으로 하늘을 넓게 칠했고, 남은 통은 옆 모둠에 건넸다."],"title":"이야기 「한 통의 물감」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_d#13','kor',3,2,'u6','','g3_2_kor_u6_review_d','unit_review','K3-2-u6-C22',2,'error','auto','「모둠마다 준비물 바구니를 두자」에 붙일 이유를 냈어요. 의견을 받쳐 주지 못하는 이유를 낸 친구는 누구인가요?',ARRAY['K3-2-u6-X23','K3-2-u6-X22']::text[],false,'{"seq":13,"concept":"K3-2-u6-C22","difficulty":2,"kind":"error","stem":"「모둠마다 준비물 바구니를 두자」에 붙일 이유를 냈어요. 의견을 받쳐 주지 못하는 이유를 낸 친구는 누구인가요?","options":[{"t":"친구 나 — 「내가 우리 반에서 정리를 제일 잘하기 때문이야.」","correct":true,"mis_target":"K3-2-u6-X23"},{"t":"친구 가 — 「물건이 제자리에 있어 잃어버리지 않기 때문이야.」","mis":"K3-2-u6-X22"},{"t":"친구 다 — 「활동할 시간이 늘어나기 때문이야.」","mis":"K3-2-u6-X22"}],"explanation":["나만 잘한다는 것은 받침이 아니에요.","바구니를 두면 좋아질 일이어야 해요.","친구 나가 잘못 냈어요."],"asset":{"type":"passage","lines":["1 모둠 활동을 할 때마다 가위와 풀을 빌리러 돌아다니느라 시간이 걸린다.","2 그래서 모둠마다 준비물 바구니를 두면 좋겠다.","3 첫째, 돌아다니지 않아도 되어 활동을 바로 시작할 수 있기 때문이다.","4 둘째, 물건마다 돌아갈 자리가 생겨 잃어버리는 일이 줄기 때문이다.","5 모둠 바구니를 함께 마련해 보자."],"title":"글 「모둠마다 준비물 바구니를 두자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_d#14','kor',3,2,'u6','','g3_2_kor_u6_review_d','unit_review','K3-2-u6-C30',2,'error','auto','의견 글로 다룰 문제를 골랐어요. 알맞지 않게 고른 친구는 누구인가요?',ARRAY['K3-2-u6-X31']::text[],false,'{"seq":14,"concept":"K3-2-u6-C30","difficulty":2,"kind":"error","stem":"의견 글로 다룰 문제를 골랐어요. 알맞지 않게 고른 친구는 누구인가요?","options":[{"t":"친구 다 — 「오늘 비가 와서 운동장에 못 나간 일」","correct":true,"mis_target":"K3-2-u6-X31"},{"t":"친구 가 — 「모둠 활동 때 준비물을 빌리러 돌아다니는 일」","mis":"K3-2-u6-X31"},{"t":"친구 나 — 「빈 교실에 불이 켜져 있는 일」","mis":"K3-2-u6-X31"}],"explanation":["비는 우리가 바꿀 수 없어요.","함께 바꿀 일을 골라요.","친구 다가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_d#15','kor',3,2,'u6','','g3_2_kor_u6_review_d','unit_review','K3-2-u6-C31',2,'ox','auto','읽을 사람이 누구든 의견을 제시하는 글은 똑같이 써요.',ARRAY['K3-2-u6-X33']::text[],false,'{"seq":15,"concept":"K3-2-u6-C31","difficulty":2,"kind":"ox","stem":"읽을 사람이 누구든 의견을 제시하는 글은 똑같이 써요.","answer":"X","reason_options":[{"t":"읽을 사람이 이미 아는 일과 모르는 일이 달라 쓸 말이 달라지기 때문에","correct":true},{"t":"의견 글에는 읽을 사람이 정해져 있지 않기 때문에","mis":"K3-2-u6-X33"}],"mis":"K3-2-u6-X33","explanation":["누가 읽을지 먼저 정해요.","쓸 말이 달라져요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_d#16','kor',3,2,'u6','','g3_2_kor_u6_review_d','unit_review','K3-2-u6-C36',2,'mc','auto','「종이배」로 “만약 이랬더라면?” 놀이를 할 때 바꿔 보기 좋은 것은 무엇인가요?',ARRAY['K3-2-u6-X36']::text[],false,'{"seq":16,"concept":"K3-2-u6-C36","difficulty":2,"kind":"mc","stem":"「종이배」로 “만약 이랬더라면?” 놀이를 할 때 바꿔 보기 좋은 것은 무엇인가요?","options":[{"t":"배가 뒤집혔을 때 “나”가 말없이 접는 대신 다른 행동을 했더라면","correct":true},{"t":"제목을 「물웅덩이」로 바꾸기","mis":"K3-2-u6-X36"},{"t":"이야기 줄 수를 늘리기","mis":"K3-2-u6-X36"},{"t":"글씨체 바꾸기","mis":"K3-2-u6-X36"}],"explanation":["마음이 움직인 장면을 골라요.","말이나 행동을 바꿔요.","그다음을 상상해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_d#17','kor',3,2,'u6','','g3_2_kor_u6_review_d','unit_review','K3-2-u6-C4',3,'ox','auto','감상에는 정답이 없으니 이야기에 없는 장면을 들어 말해도 돼요.',ARRAY['K3-2-u6-X04']::text[],false,'{"seq":17,"concept":"K3-2-u6-C4","difficulty":3,"kind":"ox","stem":"감상에는 정답이 없으니 이야기에 없는 장면을 들어 말해도 돼요.","answer":"X","reason_options":[{"t":"감상은 사람마다 달라도 이야기 안에서 무엇을 보고 그랬는지 근거가 있어야 하기 때문에","correct":true},{"t":"감상은 아무렇게나 말해도 되는 것이기 때문에","mis":"K3-2-u6-X04"}],"mis":"K3-2-u6-X04","explanation":["정답은 없어요.","그래도 근거는 있어야 해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_d#18','kor',3,2,'u6','','g3_2_kor_u6_review_d','unit_review','K3-2-u6-C24',3,'mc','auto','㉯ 당번 글에 대해 바르게 말한 것은 무엇인가요?',ARRAY['K3-2-u6-X24','K3-2-u6-X20']::text[],false,'{"seq":18,"concept":"K3-2-u6-C24","difficulty":3,"kind":"mc","stem":"㉯ 당번 글에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"㉮와 의견은 다르지만, 빠뜨리는 것이 없다는 이유가 의견을 받쳐 준다","correct":true},{"t":"㉮와 의견이 다르니 틀린 글이다","mis":"K3-2-u6-X24"},{"t":"이유가 없으니 낼 수 없는 글이다","mis":"K3-2-u6-X20"},{"t":"의견은 다 똑같으니 재 볼 것이 없다","mis":"K3-2-u6-X24"}],"explanation":["㉯에도 이유가 있어요.","빠뜨리지 않고 줄도 안 서요.","받쳐 주고 있어요."],"asset":{"type":"passage","lines":["문제 — 모둠 활동 때마다 준비물을 빌리러 돌아다닌다.","㉮ 모둠마다 준비물 바구니를 두자.","   바로 시작할 수 있고, 물건마다 돌아갈 자리가 생기기 때문이다.","㉯ 모둠마다 준비물 당번을 정해 활동 전에 한꺼번에 받아 오자.","   한 사람이 챙기니 빠뜨리는 것이 없고, 줄을 서지 않아도 되기 때문이다."],"title":"같은 문제를 두고 쓴 두 글 ㉮ 바구니 · ㉯ 당번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_d#19','kor',3,2,'u6','','g3_2_kor_u6_review_d','unit_review','K3-2-u6-C28',3,'ox','auto','고쳐 쓰기는 친구 글의 흠을 찾아 알려 주는 일이에요.',ARRAY['K3-2-u6-X30']::text[],false,'{"seq":19,"concept":"K3-2-u6-C28","difficulty":3,"kind":"ox","stem":"고쳐 쓰기는 친구 글의 흠을 찾아 알려 주는 일이에요.","answer":"X","reason_options":[{"t":"전하려던 생각을 더 잘 전하도록 글을 좋게 만드는 일이기 때문에","correct":true},{"t":"친구 글은 흠을 찾으려고 읽는 것이기 때문에","mis":"K3-2-u6-X30"}],"mis":"K3-2-u6-X30","explanation":["흠 찾기가 아니에요.","더 잘 전하게 만드는 일이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_d#20','kor',3,2,'u6','','g3_2_kor_u6_review_d','unit_review','K3-2-u6-C14',3,'ox','auto','「한 통의 물감」에는 “나는 나누어 쓰는 것을 소중히 여긴다.”라는 문장이 있어서 내가 소중히 여긴 것을 알 수 있어요.',ARRAY['K3-2-u6-X15']::text[],false,'{"seq":20,"concept":"K3-2-u6-C14","difficulty":3,"kind":"ox","stem":"「한 통의 물감」에는 “나는 나누어 쓰는 것을 소중히 여긴다.”라는 문장이 있어서 내가 소중히 여긴 것을 알 수 있어요.","answer":"X","reason_options":[{"t":"그런 문장은 없고, 물감을 조금씩 짠 행동과 옆 모둠에 건넨 일에서 읽어 내기 때문에","correct":true},{"t":"소중히 여기는 것은 이야기에 적혀 있어야 알 수 있기 때문에","mis":"K3-2-u6-X15"}],"mis":"K3-2-u6-X15","explanation":["그런 문장은 없어요.","말과 행동에서 읽어요.","그래서 X예요."],"asset":{"type":"passage","lines":["1 우리 모둠에는 하늘색 물감이 한 통뿐이었다.","2 나는 다른 모둠도 빌려 쓸 거라서 물감을 조금씩만 짜서 아껴 칠했다.","3 짝은 하늘을 크게 그리고 싶어 물감을 듬뿍 짜려다가 내 눈치를 보았다.","4 “이러면 하늘이 얼룩덜룩해지잖아.” 짝이 붓을 내려놓았다.","5 잠시 뒤 짝이 말했다. “흰색을 섞으면 양이 늘지 않을까?”","6 우리는 섞은 물감으로 하늘을 넓게 칠했고, 남은 통은 옆 모둠에 건넸다."],"title":"이야기 「한 통의 물감」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_d#21','kor',3,2,'u6','','g3_2_kor_u6_review_d','unit_review','K3-2-u6-C32',3,'mc','auto','㉯ 당번 글에 이유를 하나 더 떠올리는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X32','K3-2-u6-X23','K3-2-u6-X26']::text[],false,'{"seq":21,"concept":"K3-2-u6-C32","difficulty":3,"kind":"mc","stem":"㉯ 당번 글에 이유를 하나 더 떠올리는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"당번을 정하면 무엇이 좋아질지 먼저 적어 본다","correct":true},{"t":"당번을 안 하는 친구 이름을 적는다","mis":"K3-2-u6-X32"},{"t":"내가 당번을 제일 잘한다고 적는다","mis":"K3-2-u6-X23"},{"t":"글을 길게 쓸 말을 먼저 고른다","mis":"K3-2-u6-X26"}],"explanation":["의견을 가운데 써요.","좋아질 일을 뻗어 적어요.","그것이 이유가 돼요."],"asset":{"type":"passage","lines":["문제 — 모둠 활동 때마다 준비물을 빌리러 돌아다닌다.","㉮ 모둠마다 준비물 바구니를 두자.","   바로 시작할 수 있고, 물건마다 돌아갈 자리가 생기기 때문이다.","㉯ 모둠마다 준비물 당번을 정해 활동 전에 한꺼번에 받아 오자.","   한 사람이 챙기니 빠뜨리는 것이 없고, 줄을 서지 않아도 되기 때문이다."],"title":"같은 문제를 두고 쓴 두 글 ㉮ 바구니 · ㉯ 당번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_d#22','kor',3,2,'u6','','g3_2_kor_u6_review_d','unit_review','K3-2-u6-C11',3,'mc','auto','「종이배」 2번 줄을 읽고 “입술이 삐죽 나온 얼굴이 보이는 것 같았어.”라고 말한 친구가 쓴 감상 방법은 무엇인가요?',ARRAY['K3-2-u6-X12','K3-2-u6-X01','K3-2-u6-X02']::text[],false,'{"seq":22,"concept":"K3-2-u6-C11","difficulty":3,"kind":"mc","stem":"「종이배」 2번 줄을 읽고 “입술이 삐죽 나온 얼굴이 보이는 것 같았어.”라고 말한 친구가 쓴 감상 방법은 무엇인가요?","options":[{"t":"표정과 말투에 주의하기","correct":true},{"t":"인물의 일을 내 일과 이어 보기","mis":"K3-2-u6-X12"},{"t":"줄거리를 외우기","mis":"K3-2-u6-X01"},{"t":"작품에 점수 매기기","mis":"K3-2-u6-X02"}],"explanation":["얼굴을 보았어요.","표정이에요.","표정에 주의한 거예요."],"asset":{"type":"passage","lines":["1 비가 그친 뒤 운동장 구석에 물웅덩이가 생겼다.","2 동생이 종이배를 띄웠는데 바람에 그만 뒤집혔다. 동생 입술이 삐죽 나왔다.","3 나는 아무 말 없이 공책 한 장을 뜯어 배를 다시 접었다.","4 이번에는 배 바닥에 지우개를 하나 올려 두었다.","5 배는 기우뚱하더니 똑바로 섰다. 동생이 손뼉을 치며 깡충 뛰었다.","6 집에 오는 길에 동생이 내 손을 꼭 잡았다. 아무 말도 하지 않았다."],"title":"이야기 「종이배」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_d#23','kor',3,2,'u6','','g3_2_kor_u6_review_d','unit_review','K3-2-u6-C28',4,'mc','auto','「빈 교실의 불을 끄자」를 고쳐 쓰는 과정으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u6-X29','K3-2-u6-X28','K3-2-u6-X30']::text[],false,'{"seq":23,"concept":"K3-2-u6-C28","difficulty":4,"kind":"mc","stem":"「빈 교실의 불을 끄자」를 고쳐 쓰는 과정으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"점검표로 재어 4번 줄을 찾고 → 받쳐 주는 이유로 바꾸고 → 다시 읽는다","correct":true},{"t":"고칠 곳이 있으니 글을 버리고 새로 쓴다","mis":"K3-2-u6-X29"},{"t":"4번 줄만 지우고 끝낸다","mis":"K3-2-u6-X28"},{"t":"짝 글에서 흠을 찾아 점수를 매긴다","mis":"K3-2-u6-X30"}],"explanation":["재요.","바꿔요.","다시 읽어요."],"asset":{"type":"passage","lines":["1 체육 시간에 교실이 비어 있는데도 불이 켜져 있을 때가 많다.","2 그래서 교실을 나갈 때 마지막 사람이 불을 끄면 좋겠다.","3 첫째, 쓰지 않는 전기를 아낄 수 있기 때문이다.","4 둘째, 내가 우리 반에서 스위치에 손이 제일 잘 닿기 때문이다.","5 교실을 나설 때 불 끄는 일을 함께 지켜 보자."],"title":"글 「빈 교실의 불을 끄자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_d#24','kor',3,2,'u6','','g3_2_kor_u6_review_d','unit_review','K3-2-u6-C27',4,'essay','teacher','「빈 교실의 불을 끄자」에서 고쳐 쓸 줄을 찾아 왜 고쳐야 하는지 쓰고, 의견을 받쳐 주는 이유로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u6-C27","difficulty":4,"kind":"essay","stem":"「빈 교실의 불을 끄자」에서 고쳐 쓸 줄을 찾아 왜 고쳐야 하는지 쓰고, 의견을 받쳐 주는 이유로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 4번 줄이다. 글쓴이가 스위치에 손이 잘 닿는다는 것은 마지막 사람이 불을 끄자는 의견을 받쳐 주지 못한다. “둘째, 함께 지키면 교실을 아끼는 마음이 생기기 때문이다.”처럼 바꾸어 쓸 수 있다.","scoring_points":["고칠 줄을 찾았는가","고칠 까닭을 썼는가","받쳐 주는 이유로 바꾸어 썼는가"]},"explanation":["줄을 찾아요.","까닭을 써요.","받쳐 주는 이유로 바꿔요."],"asset":{"type":"passage","lines":["1 체육 시간에 교실이 비어 있는데도 불이 켜져 있을 때가 많다.","2 그래서 교실을 나갈 때 마지막 사람이 불을 끄면 좋겠다.","3 첫째, 쓰지 않는 전기를 아낄 수 있기 때문이다.","4 둘째, 내가 우리 반에서 스위치에 손이 제일 잘 닿기 때문이다.","5 교실을 나설 때 불 끄는 일을 함께 지켜 보자."],"title":"글 「빈 교실의 불을 끄자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u6_review_d#25','kor',3,2,'u6','','g3_2_kor_u6_review_d','unit_review','K3-2-u6-C1',4,'essay','teacher','이 단원에서 배운 것 가운데 앞으로 작품을 볼 때 쓸 것과 글을 쓸 때 쓸 것을 하나씩 쓰고, 각각 어떻게 쓸지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u6-C1","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 것 가운데 앞으로 작품을 볼 때 쓸 것과 글을 쓸 때 쓸 것을 하나씩 쓰고, 각각 어떻게 쓸지 쓰세요.","answer_guide":{"answer":"예: 작품을 볼 때는 인물의 표정과 행동을 살피며 보고, 마음이 움직인 곳에서 어떤 마음이 들었는지와 무엇을 보고 그랬는지를 함께 말하겠다. 글을 쓸 때는 의견에 이유를 함께 쓰고, 다 쓴 뒤에 한 번 더 읽고 받쳐 주지 못하는 이유를 고쳐 쓰겠다.","scoring_points":["작품을 볼 때 쓸 것을 썼는가","글을 쓸 때 쓸 것을 썼는가","각각 어떻게 쓸지 구체적으로 썼는가"]},"explanation":["감상할 때 쓸 것이에요.","글을 쓸 때 쓸 것이에요.","어떻게 쓸지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
